WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[76359] = { title = "Searing Slalom - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76361] = { title = "Fashion Week", description = "Ah, the Trial of Style is upon us, {class}. \n\nThe outfits, the creativity, the elegance of the Trial are truly a sight to see.\n\nSpeak to a Trial of Style Envoy to learn more about the event.\n\nA word of warning, those envoys can be... challenging to deal with.", objectives = "" }
WordHunterWoW_QuestEN[76362] = { title = "An Antlered Skull", description = "<Despite its surroundings, this skull does not appear to be fel-corrupted.\n\nAs you move your hand closer, you feel a sense of calm emanating from it. \n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76364] = { title = "Twilight Terror", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76365] = { title = "Twilight Terror - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76366] = { title = "Twilight Terror - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76379] = { title = "A Murloc and a Dragon Walk into a Time Rift...", description = "Grurguglg.\n\nGuuglrllghulgrgl grugll gur. Murgllgllrugl guglrllg murgu gruggullgl. Murglgurrrr gurgll Gurlgul, guruuuurllgr gurgull gurgllglrl  .\n\nArgurgulul?\n\n<You aren't certain what's being said. This world's version of Alexstrasza is handing you an hourglass and miming flipping it. It is probably of interest to Soridormi.>", objectives = "" }
WordHunterWoW_QuestEN[76380] = { title = "Deadwind Derby", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76381] = { title = "Deadwind Derby - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76382] = { title = "Deadwind Derby - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76384] = { title = "The Bloom Begins", description = "I sense a change on the wind. Like the dawning rays of the sun. Like petals before they unfurl. A great swelling energy, right at the heart of the Emerald Dream.\n\nThe Bloom. It has begun.", objectives = "" }
WordHunterWoW_QuestEN[76385] = { title = "Hazardous Horticulture", description = "We may be outnumbered, but this is my domain. And I have a way of evening our odds.\n\nTake this pouch of seeds. Plant them throughout Wildfire Canyon and the Dream's faerie dragons will transform them into treants.\n\nWith luck, they will draw attention from our front lines and bolster our ground forces.", objectives = "" }
WordHunterWoW_QuestEN[76386] = { title = "A Clash of Ice and Fire", description = "The Primalists have erected great flame wards throughout their encampment. Yet we know not why. I have asked our ground forces to investigate, but they are blocked at every turn.\n\nTwo fire elementals in particular stand against us, empowered by Fyrakk's shadowflame.\n\nYou must clear the area of enemies. I have imbued this scale with my magic. Use it to weaken the elementals and any other who stands in your way.", objectives = "" }
WordHunterWoW_QuestEN[76387] = { title = "Defense of the Ancients", description = "Fyrakk's forces at Skystone Falls are already threatening to overwhelm us. I fear not even the combined might of the Sentinels and Ancients can hold out against them.\n\nThe Ancients are bearing the brunt of the offensive. We have reports of djaradin attempting to capture them for some unknown purpose.\n\nWe cannot allow Igira to succeed in whatever nefarious plan she has in mind. You must seek out the Ancients on the battlefield and free any who are captured.", objectives = "" }
WordHunterWoW_QuestEN[76388] = { title = "Fighting Fire With Fire", description = "The notes you found, combined with Merithra's reconnaissance, have revealed Ashendir's plan. The flame wards that surround the Wellspring Temple are blocking our reinforcements.\n\nOur allies will distract Fyrakk while you and I slip behind enemy lines to destroy the wards.\n\nThe skies are filled with drakes, and I must fend them off. Once you find a flame ward and thin out its defenses, signal me to destroy it.", objectives = "" }
WordHunterWoW_QuestEN[76389] = { title = "The Age of Mortals", description = "Once again, the mortal races have come together to defend a World Tree. It is only fitting then that we bolster their efforts with a relic from that past battle. The Horn of Cenarius.\n\nI entrust the horn to you, {name}. Use it to bestow the blessings of Cenarius to our allies. With luck, it will allow us to break through Fyrakk's forces and open a path to the temple.\n\nAnd do not forget to lend your strength as well. Every enemy felled is one fewer between us and Fyrakk.", objectives = "" }
WordHunterWoW_QuestEN[76390] = { title = "Inconvenience Fee", description = "I have no idea how you managed to find me or what possessed you to douse a dead guy with holy water, but we can both agree that you owe me. That stuff hurts!\n\nFortunately for you, I like bribes more than my naps. I will happily overlook this horrible first impression you gave so you and I can be best pals; scratch my back and I'll scratch yours.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[76394] = { title = "Shadows of Flavor", description = "I've set out to create a meal that transcends the ordinary, one that even the emperor wouldn't turn away.\n\nI require ingredients from the darkest of shadows to craft this extraordinary meal. Many consider these ingredients forbidden, but they will become a harmony of light and shadow in my hands.\n\nPlease assist me by harvesting the following ingredients: Shadowblind Grouper, Dark-Nurtured Scallions, and a Vial of Twilight Spice.", objectives = "" }
WordHunterWoW_QuestEN[76397] = { title = "Elwynn Forest Flash", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76398] = { title = "Aerial Supremacy", description = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales.\n\nMount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", objectives = "" }
WordHunterWoW_QuestEN[76399] = { title = "Elwynn Forest Flash - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76400] = { title = "Elwynn Forest Flash - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76401] = { title = "Echo of the Firelands", description = "We have finally broken through the enemy's ranks, yet the Prophet of the Flame now bars our path. And he has unleashed his full power.\n\nThe Prophet must be defeated if we have any hope of making our way to the temple. I ask you to face him, champion. We shall hold back his forces as you do so.\n\nThe end is in sight. Let us finally finish this war.", objectives = "" }
WordHunterWoW_QuestEN[76402] = { title = "Amirdrassil, the Dream's Hope: Fyrakk", description = "Fyrakk may have entered the temple, but our fight has not ended. Thanks to your efforts, we have broken through his forces. There is still time to stop him.\n\nYou must gather your allies and follow Fyrakk into the Wellspring Temple. We will cover your flank.\n\nKnow that it is not only Amirdrassil that you protect this day, {name}. All of Azeroth will burn if Fyrakk claims the World Tree. He must be stopped, here and now. This is our final stand.", objectives = "" }
WordHunterWoW_QuestEN[76403] = { title = "Mayhem Incarnate", description = "We need to uncover exactly what Fyrakk's plan is. He is holding his forces away from the tree, but we do not know why.\n\nI can do some scouting, but direct conflict with Fyrakk would not help our cause right now.\n\nFollow me further into the Dream. There is a Primalist encampment to the north. Let us start there, so we can put an end to this madness.", objectives = "" }
WordHunterWoW_QuestEN[76404] = { title = "Cogs in a Machine", description = "<This cog spiraled out of a mechanized creature as you sent it back to its timeway.\n\nWhile its design is similar to Mechagnome technology, it's sleeker and more refined.\n\nIt bears a small inscription.\n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76406] = { title = "The Sins of the Ashbringer", description = "<As you near this blade, you can feel necromantic power thrumming from it.\n\nPerhaps you should wrap the sword in cloth and avoid touching it directly.\n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76407] = { title = "Not Today, Fate", description = "Eternus intends to show us what happened. I think she also seeks to change the past.\n\nNormally, I would not entertain this idea, but understanding the infinites is the only way forward.", objectives = "" }
WordHunterWoW_QuestEN[76410] = { title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", objectives = "" }
WordHunterWoW_QuestEN[76416] = { title = "Forward Unto Fire", description = "Amirdrassil draws power from the Wellspring Temple in preparation for its bloom. The barrier protecting the temple will not last much longer under Fyrakk's assault.\n\nI have sent messengers all across Azeroth asking for reinforcements, but none have yet arrived. Something blocks their path into the Dream. For now, we must rely on the forces we have.\n\nI ask you to travel to the Verdant Pass. If there is anyone I would have by my side, it is you.", objectives = "" }
WordHunterWoW_QuestEN[76419] = { title = "Violence Will Solve It", description = "Do you not agree that Moraidormi can be saved? We infinites often save those we think suffered needlessly--worthy or not.\n\nSupposedly, Mori died too close to the Caverns of Time just east of us. Using too much time magic here could have... consequences.\n\nBut this should be quick. Chrono-Lord Deios was in possession of artifacts that could forcefully rewind time. The bronze dragonflight has them now. \n\nWe will rewind time and then destroy Vexemia.\n\nSimple.", objectives = "" }
WordHunterWoW_QuestEN[76420] = { title = "Butterfly Effects", description = "We were overwhelmed by her companions. Moraidormi was still killed.\n\nI need another strategy, one that will actually protect her. She is what matters. Go rewind time, including our actions.\n\nAfter the rewind, I will hold time in place. Then we can try to make defenses for her.", objectives = "" }
WordHunterWoW_QuestEN[76421] = { title = "The Fate We Make", description = "We just need to be stronger and faster!\n\nWe cannot leave it like this, not with the eggs also destroyed.\n\nI will come up with another idea. Restart time, and...\n\n<Eternus sighs.>\n\nPerhaps I will listen to Nozdormu. He keeps telling me I have \"missed\" something...", objectives = "" }
WordHunterWoW_QuestEN[76422] = { title = "Infinity and Beyond", description = "If we continue to look into the past, we miss out on the present--or even the future.\n\nLet us return to Thaldraszus.\n\nDo not worry about these time fracture elementals. They too will heal with time.\n\nAs we all do.", objectives = "" }
WordHunterWoW_QuestEN[76423] = { title = "No Limits", description = "After confronting the infinites and, well, myself--we have had a lot to think about.\n\nEternus, one of the infinites, has apparently been thinking a lot too.\n\nThe infinites want to change Nozdormu into his infinite form, Murozond. We don't want that. And after learning about Nozdormu, I think Eternus may be persuaded to not want that either.\n\nI've set up a meeting between Nozdormu and Eternus to get them talking. But I want someone else there... in case something goes wrong.", objectives = "" }
WordHunterWoW_QuestEN[76426] = { title = "The Kalimdor Cup Circuit", description = "The Riders of Azeroth have learned much from us, and now we test their mettle, as well as yours, skyrider!\n\nMy bronze colleagues have traveled to Kalimdor to create new challenges. They await you with many races across the continent.\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[76427] = { title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", objectives = "" }
WordHunterWoW_QuestEN[76429] = { title = "The Kalimdor Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[76430] = { title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", objectives = "" }
WordHunterWoW_QuestEN[76433] = { title = "Ashen Soil", description = "It seems the Druids of the Flame wasted no time in seeking to expand their influence. \n\nDeep within these barrow dens, some manner of corruption has taken root. It will spread if left unchecked, consuming the entire den before expanding outwards to threaten the rest of the dream.\n\nTime is short, {name}. Delve into the barrow, seek out the sources of the spreading flame, and excise them before the smoldering embers can grow and spread.", objectives = "" }
WordHunterWoW_QuestEN[76434] = { title = "Not Yet Lost", description = "The flame did not take root here on a whim. \n\nNo doubt there are servants of the Firelands cloistered within, trying to spread their flame to the creatures that reside within these barrows. We must do what we can to save those who can still be saved, and mete out swift justice to the heretics that lurk within.", objectives = "" }
WordHunterWoW_QuestEN[76435] = { title = "The Smoldering Copse", description = "Andi'thur tells me of smoke rising from a grove to the west. Norana's new allies are not exactly the subtle sort.\n\nI do not care what her motivations are. I will not allow her to set another inch of this land ablaze. Ride for the western groves. However the Druids of the Flame plan to seek their so-called rebirth, we will do all we can to stop them.", objectives = "" }
WordHunterWoW_QuestEN[76436] = { title = "A Scrap of Hope", description = "It is only a matter of time before Fyrakk's forces decimate our own. And then there will be nothing stopping him from entering the Wellspring Temple.\n\nIf the Prophet of the Flame is responsible for blocking our reinforcements from entering the Dream, there must be some record or communication of his plan. We just have to find it.\n\nSearch for any communications amongst Fyrakk's forces at Skystone Falls. If we can disrupt their efforts in some way, we might have a chance to turn the tide.", objectives = "" }
WordHunterWoW_QuestEN[76437] = { title = "Burning Ground", description = "We allowed ourselves to be distracted. We thought the Druids of the Flame had followed us into the Dream, when clearly they arrived before we did.\n\nWith Amirdrassil so close at hand, we cannot allow them to plant their ashen roots here. Release their prisoners. Ransack their supplies. Do whatever you can to ensure that this burning corruption does not spread further.", objectives = "" }
WordHunterWoW_QuestEN[76438] = { title = "Gurubashi Gala", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76439] = { title = "Gurubashi Gala - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76440] = { title = "Gurubashi Gala - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76441] = { title = "Grim Reprisal", description = "The Druids of the Flame will not allow you to proceed unfettered once your intentions here become clear.\n\nThey are my kin, my brothers and sisters under Elune... But they seek to undo all that we have toiled for. Their machinations would condemn countless lives to an all-consuming inferno.\n\nI won't allow it. We cannot allow it.\n\nDisrupt their rituals. Destroy their supplies. If they raise their blades against you, cut them down.", objectives = "" }
WordHunterWoW_QuestEN[76442] = { title = "Forlorn Hope", description = "You've arrived just in time. Norana lurks just beyond the ridge. She appears to be taking part in some manner of ritual - alongside a man who appears to be their leader.\n\nThese are powerful druids, and their strength is amplified by their ties to the Firelands. Taking the blade to all of them at once would be foolish.\n\nStill, the least we can do is disrupt their ritual. If we send them scattering, we buy ourselves time - and an opportunity to press the advance elsewhere.", objectives = "" }
WordHunterWoW_QuestEN[76443] = { title = "The Looming Cinder", description = "The Druids of the Flame are nothing more than allies of convenience to Fyrakk and his ilk. Nevertheless, they present a dire threat to the well-being of Amirdrassil, to say nothing of the rest of the Dream.\n\nThe victory we earned here today was hard-fought, but it only served to stem the tide. No doubt the Prophet and the Priestess have already reunited with their erstwhile allies.\n\nWe should return to Merithra. She needs to know of this.", objectives = "" }
WordHunterWoW_QuestEN[76445] = { title = "Ironforge Interceptor", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76446] = { title = "Ironforge Interceptor - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76447] = { title = "Ironforge Interceptor - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76448] = { title = "The Fate of Scalecommander Abereth", description = "According to our colleagues, this cave was used to test prospective scalecommanders.\n\nExcuse me. It either tested them or housed their remains. The trials were so difficult that it usually amounted to the same thing.\n\nWe're searching for an ancient scalecommander referenced in our records as \"The Cleaving Blade\": a promising young dracthyr whose future ended abruptly somewhere near this cave. Perhaps we'll discover how their story ends.", objectives = "" }
WordHunterWoW_QuestEN[76449] = { title = "The Endless Conflict", description = "<You notice a book beside the body of a Great Glorious Alliance soldier.\n\nQuickly flicking through the pages, you see that it's some type of journal. \n\nParts of it were ruined by a puddle of oil.\n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76453] = { title = "A Stony Reception", description = "<This chipped stone tablet stands out from its surroundings.\n\nAs you go to pick it up, it weighs quite a lot more than you expected.\n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76456] = { title = "Using the Idol", description = "Ah, the Idol of Ohn'ahra! Let's use it to find gems. I've hidden three gems nearby in Valdrakken, all outside.\n\nThe idol will reveal the gems when you're near.\n\nCome back when you've tracked them down.", objectives = "" }
WordHunterWoW_QuestEN[76459] = { title = "The Resistance", description = "<The person in front of you is clearly an uncorrupted night elf, albeit significantly more feral and malnourished than usual.>\n\nNice world. No Legion. No fel.\n\nIf you can, send help. Suramar, ask for Tyrande.\n\n<Soridormi may want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76460] = { title = "A Dragon in Hand is Worth Two in the Roost", description = "Ah, {name}, so wonderful to see you!\n\nYou have arrived just in time. I was tasked with seeking out potential allies to aid with the protection of the world tree.\n\nYour accomplishments speak for themselves--your help in this matter would be greatly appreciated.\n\nWhat do you say, up for some diplomacy?", objectives = "" }
WordHunterWoW_QuestEN[76461] = { title = "Draconic Diplomacy", description = "I suspect Vyranoth might also be interested in recruiting new dragons to our cause... but she'll need a little convincing. \n\nI just so happen to be very good at convincing. \n\nI'll speak with Vyranoth, and we'll meet you in Valdrakken once she's decided to join us.", objectives = "" }
WordHunterWoW_QuestEN[76462] = { title = "Cavern Cleaning", description = "This cave is adequate. It has a commanding view of the surrounding land, and is highly defensible.\n\nBut the state of it is not acceptable. \n\nI will place an enchantment upon you. When you draw near to the smaller spiders, it will freeze them, allowing us to relocate them. The sacs and larger spider will need to be addressed with more... finality. \n\nSee that it is done.", objectives = "" }
WordHunterWoW_QuestEN[76463] = { title = "Delectable Delicacies", description = "Of course we will take care of the netherwhelps.\n\nHowever, we might run low on snacks. The beetles close by are a delicious treat for the little ones. \n\nCan you bring me back some juicy beetle bits? Only the best for the little darlings!", objectives = "" }
WordHunterWoW_QuestEN[76464] = { title = "The Thorignir", description = "The Thorignir of Stormheim have the strength and power to greatly aid us in defending Amirdrassil, but they have yet to come to the Dragon Isles. I suspect this... Odyn has interfered with their journey.\n\nWe will go and speak with their matriarch. Wrathion tells me her brood is amenable to your kind, and to assisting others. \n\nWe will investigate.", objectives = "" }
WordHunterWoW_QuestEN[76465] = { title = "Dragon Keeping", description = "First he opposes dragonkind, then he enslaves them, denying them their birthrights.\n\nWe shall visit these so-called \"Halls of Valor,\" defeat any who oppose us, and liberate the storm drakes from that which binds them.\n\nCome along.", objectives = "" }
WordHunterWoW_QuestEN[76469] = { title = "Blasted Lands Bolt", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76470] = { title = "Blasted Lands Bolt - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76471] = { title = "Blasted Lands Bolt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76504] = { title = "The Tricked-Out Thinking Cap", description = "The cap has an amazing function: Put it on, and you'll know where you're going! Let's practice!\n\nThe arrow above me has a clue on it, to another arrow somewhere in Valdrakken. And THAT arrow leads to another...\n\nFollow the arrows until you find them all, and the prize at the end!", objectives = "" }
WordHunterWoW_QuestEN[76510] = { title = "Plaguelands Plunge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76512] = { title = "Plaguelands Plunge - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76513] = { title = "Plaguelands Plunge - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76515] = { title = "Booty Bay Blast", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76516] = { title = "Booty Bay Blast - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76517] = { title = "Booty Bay Blast - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76521] = { title = "Buzzing Boffins", description = "<After running up to you with great speed, this robotic creature does not attack you.\n\nIt is persistent in its desire to be close to you.\n\nIt has the word \"Boffins\" etched into its side.\n\nSoridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76523] = { title = "Fuselight Night Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76524] = { title = "Fuselight Night Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76525] = { title = "Fuselight Night Flight - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76527] = { title = "Krazzworks Klash", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76528] = { title = "Krazzworks Klash - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76529] = { title = "Krazzworks Klash - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76530] = { title = "Unliving Summons", description = "We need you in Tirisfal, {name}. Come quickly.\n\nThere's a new situation brewing just outside the Ruins of Lordaeron, and it's not looking pretty. I'll get you up to speed when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[76531] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[76532] = { title = "Assault on the Wellspring", description = "Terro gave his life to protect the Dream. Which means we must see it through.\n\nVyranoth should be able to handle Lethka, we must find Suzska.\n\nI hope Lethka did not attack her first. We should start looking near the Wellspring. \n\nMeet me there so we can continue our search.", objectives = "" }
WordHunterWoW_QuestEN[76533] = { title = "Dangerous Documentation", description = "<The flickering of a hologram stands out among the surrounding greenery.>\n\nA quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren.\n\n<Soridormi will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76536] = { title = "Redridge Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76537] = { title = "Redridge Rally - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76538] = { title = "Redridge Rally - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76544] = { title = "Wasteland Warriors", description = "<This book has what appears to be a modified Horde symbol on it. You recognize it as the Blood Horde symbol you have seen from timeway incursions.\n\nIt is odd it is still here, after the incursion has ended. \n\nThe book has been soaked in blood, though it has long since dried off.\n\nSoridormi might be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[76545] = { title = "Brewfest in Valdrakken", description = "Have you heard? Brewfest has made its way here! You should speak to Bragdur Battlebrew in the Artisan's Market--he can tell you all about it.", objectives = "" }
WordHunterWoW_QuestEN[76546] = { title = "Mantid Methodology", description = "<This amber sword was left behind as you knocked one of the Mantid back through a time rift.\n\nYou take a moment to ensure it's safe, then place it in your pack.\n\nPerhaps Soridormi would be interested in it.>", objectives = "" }
WordHunterWoW_QuestEN[76547] = { title = "All That Glitters...", description = "<Having recently defeated the Time Anomaly in this timeway, you notice this golden vase glittering.\n\nIt is extremely worn, be it by time or something else. You can't make out the details of its carvings along the edges.\n\nBattered as it is, it still manages to give off a warm light, contrasting the chill here. \n\nIt looks very out of place. Soridormi may be interested in it.>", objectives = "" }
WordHunterWoW_QuestEN[76548] = { title = "A Fishy Gift", description = "Murglgalgul!\n\nGlulmual, rluu glua ffrl wawawamual. Lalala!\n\nMowua ha mwaaay.\n\n<Murloc You raises a fish up in both of his hands towards you. It seems very officious. Soridormi may want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[76552] = { title = "In Sync", description = "While Pedgi had you out killing slimes, I asked the investigators here how we can actually help.\n\nSeems quite a few of them are stuck in time anomalies. Luckily, I've just finished giving the metronographer a few temporal upgrades. It should now help the investigators get back in sync.\n\nBut we need to test it out first. Looks like there's someone nearby who will do the trick.", objectives = "" }
WordHunterWoW_QuestEN[76557] = { title = "Without Honor", description = "Ok, the goggles should be calibrated. Looks like the confluence point is right here on the ledge. I wonder what happened to him?", objectives = "" }
WordHunterWoW_QuestEN[76560] = { title = "[PH] Cogs Breadcrumb", description = "Talk to the thinking cap guy. A gnome.", objectives = "" }
WordHunterWoW_QuestEN[76564] = { title = "The Tools of the Dragonkillers", description = "If you're going to go after a dragon, who better to employ than the Djaradin?\n\nLet's see what we can find, {name}.", objectives = "" }
WordHunterWoW_QuestEN[76566] = { title = "The Dryad Garden", description = "{name}, there is a situation I am personally concerned about. \n\nA garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth.\n\nAn overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. \n\nPlease assist him in his task on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[76567] = { title = "Grousing Garden", description = "The sanctuary has been overrun!\n\nThe roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change.\n\nPlease help them get out their restless energy. Perhaps tired out, they will relax in this space again.", objectives = "" }
WordHunterWoW_QuestEN[76568] = { title = "Pineshrew Panic", description = "With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching.\n\nA gentle shake will release the seeds properly. Please hurry before they run off with any more!", objectives = "" }
WordHunterWoW_QuestEN[76569] = { title = "Druid-Guardian Conference", description = "Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own.\n\nUnfortunately, it is difficult to separate a dryad from whoever she imprints on.\n\n<Ethidris sighs and rubs his eyes.>\n\nWhich she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.", objectives = "" }
WordHunterWoW_QuestEN[76570] = { title = "The Family Business", description = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them.\n\nSince it seems you are practiced at completing tasks, you will show Dionaessa the ropes.\n\nA group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", objectives = "" }
WordHunterWoW_QuestEN[76571] = { title = "Growth Experience", description = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice.\n\nThe stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves.\n\n<Melyrine smiles. Her eyes shine with intensity.>\n\nIf she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", objectives = "" }
WordHunterWoW_QuestEN[76572] = { title = "A Poisonous Promotion", description = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora!\n\nIf we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion!\n\nLet us kill it. This is what you have prepared me for--a dire quest!", objectives = "" }
WordHunterWoW_QuestEN[76576] = { title = "An Unlikely Proposal", description = "Tuskarr artifacts, underground, deep in Djaradin territory?\n\nIf we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here?\n\nOk looks like the nexus point is right here in this cave. Let's get to the bottom of this!", objectives = "" }
WordHunterWoW_QuestEN[76577] = { title = "Brewfest in Valdrakken", description = "We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!", objectives = "" }
WordHunterWoW_QuestEN[76578] = { title = "Khaz Algar Rally", description = "Race through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[76579] = { title = "Brewfest in Valdrakken", description = "Seems the dracthyr have decided to host their own Brewfest festivities this year! Once you've finished celebrating here, you should venture to the Dragon Isles and see what they've put together.", objectives = "" }
WordHunterWoW_QuestEN[76588] = { title = "Defender of the Flame", description = "The Expedition forces face formidable adversaries.\n\nDrawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts.\n\nPlease help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.", objectives = "" }
WordHunterWoW_QuestEN[76591] = { title = "Bubbling Brews", description = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "" }
WordHunterWoW_QuestEN[76592] = { title = "A Single Wing", description = "Amythora has returned with grave news. The Sundered Flame live on!\n\nWe have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. \n\nAnd they have captured Marithos!\n\nGiven that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.", objectives = "" }
WordHunterWoW_QuestEN[76593] = { title = "The Best Intentions", description = "Not only did they beat him--they put him in shackles too!\n\nWhat's worse is... I probably would have done the same...\n\nWe will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, {name}, while I keep him comfortable.", objectives = "" }
WordHunterWoW_QuestEN[76594] = { title = "Dracthyr Down", description = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care.\n\nThankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway.\n\nLook around and collect some of the Wingfoil nearby, {name}.", objectives = "" }
WordHunterWoW_QuestEN[76595] = { title = "Urgent Exfiltration", description = "The Sundered Flame here are not going to take Quartermaster Doros's death well...\n\nThey are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us.\n\nSecure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", objectives = "" }
WordHunterWoW_QuestEN[76597] = { title = "On New Wings", description = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently.\n\nWe must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people.\n\nThey have suffered. We have suffered. Perhaps now we can all heal.\n\nFollow me back to Valdrakken. We have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[76598] = { title = "Rough Edges", description = "I apologize for not meeting you in person, {name}, but this method seemed most timely.\n\nOur war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become.\n\nShe left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned.\n\nPlease--seek her out, and make sure she is all right. She does not need to know I sent you.", objectives = "" }
WordHunterWoW_QuestEN[76600] = { title = "Right Between the Gyro-Optics", description = "My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why!\n\nThe lights go out, and they all start trying to kill us!\n\nYou want to help me sort this out?\n\nI'm a crack shot with a rifle. You mark the target, and I'll start shooting!", objectives = "" }
WordHunterWoW_QuestEN[76733] = { title = "Tater Trawl", description = "Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely.\n\nIf you light the harvest torches, you might uncover some potatoes hiding in the shadows. \n\nUsing those lights, gather as many potatoes as you can. Every bit helps in these trying times.", objectives = "" }
WordHunterWoW_QuestEN[76997] = { title = "Lost in Shadows", description = "Greetings, {name}. I find myself in a dire situation. \n\nSome fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented.\n\nI found safety in this house, but most of the recruits fled, confused into the darkness. \n\nWill you help me locate them? I have a spare Patrol Torch. The mere sight of it should rally them to your side.", objectives = "" }
WordHunterWoW_QuestEN[77092] = { title = "Test Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[77093] = { title = "The Shadowflame Axe", description = "The moment you attempted to wield  Fyrakk's axe, Fyr'alath, its flames consumed you. Clearly the weapon's shadowflame was too intense.\n\nPerhaps you should consult an expert on shadowflame and ancient artifacts. Maybe one of the scholars at the Azerothian Archives can deduce a method for handling it safely.", objectives = "" }
WordHunterWoW_QuestEN[77094] = { title = "Basic Kill Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[77095] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77096] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77097] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77098] = { title = "Getting to Ground", description = "He needs to be healed--now. \n\nWe're too out in the open here. Sundered Flame loyalists could ambush us at any time. \n\nLet's find cover somewhere so we can assess his wounds.\n\nCover me!", objectives = "" }
WordHunterWoW_QuestEN[77099] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77100] = { title = "Surveying the Cliffside", description = "Nothing like brisk ocean air to get you in the mood to dig!\n\nWe're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters.\n\nIf there's anything left that hasn't fallen into the sea, we'll find it!", objectives = "" }
WordHunterWoW_QuestEN[77101] = { title = "Ingredient Quest Template", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", objectives = "" }
WordHunterWoW_QuestEN[77102] = { title = "Hellfire Hustle", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77103] = { title = "Hellfire Hustle - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77104] = { title = "Hellfire Hustle - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77151] = { title = "The Cache in the Crag", description = "<This barrel is salt-encrusted and buried amongst the rubble but remarkably intact.\n\nIt looks like the sort of mundane cache that villagers would use to store goods, but no one has lived here for thousands of years. Could there still be something inside?\n\nRoska will want to have a look at this!>", objectives = "" }
WordHunterWoW_QuestEN[77152] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77153] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77154] = { title = "A Taste of the Past", description = "Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel.\n\nThat said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find.\n\nI'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?", objectives = "" }
WordHunterWoW_QuestEN[77155] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77163] = { title = "Seeing Reason", description = "They seem to know that Sarkareth is gone, but because their missions were so far from Zaralek Cavern, it looks like they never heard how he met his demise. \n\nWe should talk to them. Maybe if they knew why so many of their brethren now follow me they would become Ebon Scales again. Or not...\n\n<Emberthal sighs.>\n\nThis could backfire catastrophically, but I feel like we must try. Quartermaster Doros seems to be in command here. Go and speak to him, {name}. I do not think he would listen to me...", objectives = "" }
WordHunterWoW_QuestEN[77164] = { title = "Scarab Test One", description = "", objectives = "" }
WordHunterWoW_QuestEN[77166] = { title = "A Practical Test", description = "Now that you know how to use the device, we will put your skills to the test.\n\nI have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there.\n\nIt is time for science! Put... the goggles... on! Resume your scrying!", objectives = "" }
WordHunterWoW_QuestEN[77169] = { title = "Coilfang Caper", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77170] = { title = "Coilfang Caper - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77171] = { title = "Coilfang Caper - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77176] = { title = "I Can See Through Time!", description = "Okay, the Technoscryers should be calibrated. I have made the same adjustments to my own pair, so we can view the same phenomena.\n\nAre you ready? Put... them on... again! This time, we will use the Observation mode.", objectives = "" }
WordHunterWoW_QuestEN[77178] = { title = "Tactical Withdrawal", description = "We have stopped this attack on the barrier, but Fyrakk will find a way through.\n\n{name}, we need to return to Alexstrasza and Merithra and tell them his plans for the Wellspring.\n\nReturn as soon as possible. It is more urgent than ever to stop Fyrakk.", objectives = "" }
WordHunterWoW_QuestEN[77191] = { title = "Handling It", description = "If you want to wield Fyr'alath safely, you'll need to modify the weapon's haft with three components.\n\nFirst, you'll need a fireproof hide that can handle intense heat. Next, acquire enchanted vellum that can contain the weapon's volatile magic. Finally, a scribe must apply the proper runes, so you can bind the first two materials to the axe.\n\nMy journal over there includes a few recommendations of crafters who can help you. You might also know a few!", objectives = "" }
WordHunterWoW_QuestEN[77192] = { title = "An Axe Tempered", description = "Exemplary. Some of the components can be wrapped and attached by hand, but for the last step, you'll need a powerful forge to unify all three in flame.\n\nI've been speaking to Wrathion. He can direct you to a suitable forge in the Obsidian Citadel. I'll meet you both there! I can't wait to see what happens as a result of my ingenious plan!", objectives = "" }
WordHunterWoW_QuestEN[77193] = { title = "The Power of Temptation", description = "Just to be clear: if the axe defeats you, I will be obligated to step in. \n\nBut that's not going to happen, is it? You're not going to be corrupted by shadowflame. You won't devolve into a monstrous, murderous shadow of your former self. I'm not going to have to... intervene.\n\nAs long as we're clear on this, no one is going to have to kill anyone. All right, let's get this done.", objectives = "" }
WordHunterWoW_QuestEN[77195] = { title = "A Dragon's Eye View", description = "I believe I know just the location for the Netherwing to roost.\n\nIt has a wonderful view and is quite secluded.\n\nI'd like to show our guest some of the sights of Valdrakken before we go. Meet you there?", objectives = "" }
WordHunterWoW_QuestEN[77197] = { title = "A Whelping Hand", description = "Well done, {name}.\n\nNow we must ensure the whelps of the netherwing have the best opportunities to grow and flourish. \n\nLet us speak to Mother Elion. I know she would relish the opportunity to care for the young of a new flight. \n\nCan you meet us at the Ruby Lifeshrine?", objectives = "" }
WordHunterWoW_QuestEN[77198] = { title = "Home in Time for Tea", description = "I must admit, I did not expect to be altering the future of my flight when I arrived. But it feels as though we belong here. Perhaps this is the call they spoke of...\n\nRegardless, I am looking forward to some rest. \n\nWrathion mentioned retiring to the Roasted Ram Inn. \n\nCan you meet us there?", objectives = "" }
WordHunterWoW_QuestEN[77200] = { title = "Offerings for the Well", description = "Amirdrassil has been ushered into this world by the denizens of the Dream. Now we must ensure its roots are bathed in the waters of Elune by creating a new moonwell.\n\nSo many of my people have brought us to this moment. Each should have a part in this dedication. \n\nGo, speak to the kaldorei gathered here, and see if they have offerings for the ceremony.", objectives = "" }
WordHunterWoW_QuestEN[77201] = { title = "A Personal Offering", description = "{name}. You have done so much for our people. I would have you participate in this ceremony and provide an offering of your own, should you wish it.\n\nLet me know what it is that you would like to put forward and it will be done.", objectives = "" }
WordHunterWoW_QuestEN[77202] = { title = "The Preservationists", description = "Welcome, adventurer. Have you heard the news?\n\nThere's been a rash of artifact thefts as rumors of treasures and secret locations are being exposed.\n\nIf you'd like to learn more, seek out Preservationist Kathos. Your skills at deciphering secrets might help reveal who's behind this chaos.", objectives = "" }
WordHunterWoW_QuestEN[77203] = { title = "Preserving Rarities", description = "Let's unravel a secret! Prepare your mind for puzzles...\n\nSpeak to me again when you're ready to start down the path of the preservationists.", objectives = "" }
WordHunterWoW_QuestEN[77205] = { title = "Blade's Edge Brawl", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77206] = { title = "Blade's Edge Brawl - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77207] = { title = "Blade's Edge Brawl - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77208] = { title = "Barreling Down", description = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here.\n\nWe've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels down here? And try not to break 'em!", objectives = "" }
WordHunterWoW_QuestEN[77209] = { title = "Seed Legacy", description = "For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds.\n\nThe first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. \n\nWe will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.", objectives = "" }
WordHunterWoW_QuestEN[77231] = { title = "Technoscrying 101", description = "Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra!\n\nSimple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \"Technoscryers.\" Trademark and patent pending.\n\nHere, try them on!", objectives = "" }
WordHunterWoW_QuestEN[77236] = { title = "When Time Needs Mending", description = "We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get.\n\nThere's always more work to do. Are you ready for the next challenge?", objectives = "" }
WordHunterWoW_QuestEN[77237] = { title = "Unfinished Thinking Cap", description = "<Take the Unfinished Thinking Cap to Fangli Hoot near the Barber Shop in Valdrakken.>", objectives = "" }
WordHunterWoW_QuestEN[77238] = { title = "Telaar Tear", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77239] = { title = "Telaar Tear - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77240] = { title = "Telaar Tear - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77241] = { title = "A Foreseeable Friendship", description = "Thank you for your timely intervention. You've been a valuable ally in our campaign.", objectives = "" }
WordHunterWoW_QuestEN[77248] = { title = "A Recognition of Skill", description = "Impressive work. With champions like you on our side, the odds are in our favor.", objectives = "" }
WordHunterWoW_QuestEN[77249] = { title = "One of Us", description = "{name}, you've returned. I trust you have everything well in hand.", objectives = "" }
WordHunterWoW_QuestEN[77250] = { title = "Realized Potential", description = "I salute you, {name}. Would you care to chat?", objectives = "" }
WordHunterWoW_QuestEN[77251] = { title = "Shaping the Dreamsurge", description = "The Emerald Dream is thrumming with energies not felt in ages. \n\nSome of that energy is even slipping through the barrier between the dream and Azeroth, coalescing into a glimmering, pollen-like powder. \n\nGather as much as you can. This is not like any event we have seen before!", objectives = "" }
WordHunterWoW_QuestEN[77254] = { title = "Aiding the Accord: Time Rift", description = "The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late.\n\nThat's where you come in.\n\nYou can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken. Aid her in whatever way she deems necessary.", objectives = "" }
WordHunterWoW_QuestEN[77260] = { title = "Razorthorn Rise Rush", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77261] = { title = "Razorthorn Rise Rush - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77262] = { title = "Razorthorn Rise Rush - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77263] = { title = "The Torch of Pyrreth", description = "Let's begin with a simple test.\n\nI have hidden an artifact somewhere in the Ruby Enclave.\n\nIf you have the torch out, it should illuminate when you get close to the target. And if my theory is correct, it should interact with a lock I put on the artifact.\n\nBring me back what's inside. Got it?", objectives = "" }
WordHunterWoW_QuestEN[77264] = { title = "Auchindoun Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77265] = { title = "Auchindoun Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77266] = { title = "Auchindoun Coaster - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77267] = { title = "Excavation 101", description = "So, you want to learn how to excavate artifacts? You came to the right orc!\n\nTurns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand.\n\nBut you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.", objectives = "" }
WordHunterWoW_QuestEN[77268] = { title = "Hands-On Experience", description = "Great job on that small find! Now, are you ready for something big?\n\nMore often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it.\n\nA major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya.\n\nDon't worry! I can guide you through it.", objectives = "" }
WordHunterWoW_QuestEN[77277] = { title = "Preservationist Cleared", description = "Ya better return the item before the Preservationist notices it's missing.\n\nThen let Fangli know that her theory didn't pan out.", objectives = "" }
WordHunterWoW_QuestEN[77278] = { title = "Tempest Keep Sweep", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77279] = { title = "Tempest Keep Sweep - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77280] = { title = "Tempest Keep Sweep - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77282] = { title = "Artifact Secured", description = "<Returning the torch to Preservationist Kathos might give insight into how it was used.>", objectives = "" }
WordHunterWoW_QuestEN[77283] = { title = "A Multi-Front Battle", description = "The kaldorei have set up a temporary base beneath the boughs of Amirdrassil.\n\nWith hope and hard work, this encampment will become permanent when the tree enters our world. \n\nFeel free to acquaint yourself with the provisions available. Then return to me.", objectives = "" }
WordHunterWoW_QuestEN[77286] = { title = "A Knowledgeable Descent", description = "<The rubbing is in an ancient language. Perhaps Bobby Carlisle can get the text translated.>", objectives = "" }
WordHunterWoW_QuestEN[77304] = { title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[77305] = { title = "Out of the Sands", description = "<The Time-Lost fragments are now joined to form a stone tablet, but many of its inscriptions are worn and incomplete.\n\nPreservationist Kathos will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[77310] = { title = "Memory of the Dreamer", description = "In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours.\n\nPerhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see?\n\nRest here and let the magic of the Dream wash over you.", objectives = "" }
WordHunterWoW_QuestEN[77311] = { title = "Healing Helper", description = "Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. \n\nOur efforts to heal him so far have proved fruitless. But now that you are here, you can assist.\n\nGracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.", objectives = "" }
WordHunterWoW_QuestEN[77312] = { title = "Nature Persists", description = "Admittedly, I do not know what to do next.\n\nIf he is to rest here... flowers would be lovely.\n\nThe podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom.\n\nI think Gracus will like the flowers.", objectives = "" }
WordHunterWoW_QuestEN[77313] = { title = "A Solemn Summons", description = "It is as I feared. It is Gracus' time. \n\nHealing him would never have worked. The world beyond already calls to him. \n\nAlthough he has such peace, those that care for him will still grieve. He will still be dearly missed. \n\nNot everyone is granted a chance to say goodbye. \n\nWe must ensure that in this case, they are.", objectives = "" }
WordHunterWoW_QuestEN[77314] = { title = "Requiem in a Dream", description = "As one life ends so too will a life begin. \n\nWe must remind those that love Gracus of this, {name}. \n\nPlant seeds around Gracus. My sister can handle the rest. \n\nThis place will not only represent an end but also a beginning of new life.", objectives = "" }
WordHunterWoW_QuestEN[77315] = { title = "Ancient Memories", description = "Those dark memories cannot be allowed to fester in the Dream.\n\nUnleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent.\n\nDefeat the memory that haunts him most so that Gracus can slumber at last.", objectives = "" }
WordHunterWoW_QuestEN[77316] = { title = "Trouble at the Tree", description = "{name}! Merithra needs your help. \n\nSome nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc!\n\nLike the most important thing of all, stealing top secret super important supplies. \n\nIt's urgent you stop them and get the supplies back.", objectives = "" }
WordHunterWoW_QuestEN[77317] = { title = "Hatted Hibernation", description = "I'll let you in on a secret, these crates? They're prank supplies! \n\nPeople are so serious around here. What's better than a little prank to lift everyone's spirits?\n\nYou could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat?\n\nBe careful though, their connection to the dream could make anything happen!", objectives = "" }
WordHunterWoW_QuestEN[77318] = { title = "Merithra Says", description = "Some druids are volunteering to help tend to the tree and set up camp.  \n\nBut they're so sad! \n\n<Lady Moonberry grows a mischievous grin.> \n\nWe have to give them a reason to smile. You can give them some orders that remind them to have fun. \n\nBut there's no way they'll take orders from you. \n\nThat's why I got this costume for you. With this and a little spell they'll for sure listen to you!", objectives = "" }
WordHunterWoW_QuestEN[77322] = { title = "Shattrath City Sashay", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77323] = { title = "Shattrath City Sashay - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77324] = { title = "Shattrath City Sashay - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77325] = { title = "To the Archives!", description = "Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold?\n\nThen take hold of your future, and join the newly budding ranks of the Azerothian Archives!*\n\n<Your eyes move to the fine print near the parchment's edge.>\n\n*Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.", objectives = "" }
WordHunterWoW_QuestEN[77327] = { title = "Nirobin and the Office", description = "Perhaps there is more to investigate, but I need time to go over our findings here first.\n\nOur colleague, Nirobin, the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in.\n\nI'm positive he'll be there... Mostly because he never leaves it.", objectives = "" }
WordHunterWoW_QuestEN[77328] = { title = "Back to Headquarters!", description = "Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean.\n\nI'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.", objectives = "" }
WordHunterWoW_QuestEN[77329] = { title = "Auspicious Gathering", description = "As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. \n\nI am certain that Tyrande would want you there for the dedication.\n\nLet us join them at the Central Encampment.", objectives = "" }
WordHunterWoW_QuestEN[77331] = { title = "Graduation Day", description = "You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt.\n\nBetween the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest.\n\nThere will always be work and companionship here when you desire it. We hope you'll join us on other continents as well.\n\n...When we receive appropriate funding, that is.", objectives = "" }
WordHunterWoW_QuestEN[77339] = { title = "Data Recovery", description = "After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. \n\nMeet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. \n\nWe will finally make Tyr whole again!", objectives = "" }
WordHunterWoW_QuestEN[77340] = { title = "Infiltrating the Nighthold", description = "The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise.\n\nIt is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ.\n\nAll of you are on your own once you get there, so try not to muck it up.", objectives = "" }
WordHunterWoW_QuestEN[77341] = { title = "Logotyrapy", description = "Dear {name},\n\nIt seems wrong to say this of someone as mighty as Tyr, but I am worried about him. When he arrived at Tyr's Rest, he spent many days talking with us. We all asked him many questions, learning about the titans, ancient history, and his philosophy.\n\nBut recently, Tyr has been speaking less, and the answers he does give are shorter and some have an edge to them.\n\nI'm not sure what's wrong, but something is different. Will you come speak with him?\n\nFor Tyr,\nValunei", objectives = "" }
WordHunterWoW_QuestEN[77342] = { title = "Disc Delivery", description = "You have recovered the disc? \n\nGood. At last, we can awake Tyr.\n\nThe disc must be placed in the console so it can attune to the Silver Scale and pass on to Tyr.\n\nI believe you should do the honors, {name}.", objectives = "" }
WordHunterWoW_QuestEN[77343] = { title = "A Tyrful Reunion", description = "This is incredible, seeing our friend back after so many thousands of years. So much has happened since we last spoke.\n\nThe world has changed. Our loss of Tyr was before even the Sundering. But there will be time to discuss all those things later. For now, it's simply good to be with our friend. Stay with us, will you, {name}, while we reconnect?", objectives = "" }
WordHunterWoW_QuestEN[77344] = { title = "Time to Process", description = "Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. \n\nMeanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?", objectives = "" }
WordHunterWoW_QuestEN[77345] = { title = "The Need For Higher Velocities", description = "Sometimes you'll need to travel longer distances.\n\nIf you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky.\n\nFollow the rings again to your destination and use Surge Forward when prompted to maintain your speed.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "" }
WordHunterWoW_QuestEN[77346] = { title = "Shadowmoon Slam", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77347] = { title = "Shadowmoon Slam - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77348] = { title = "Shadowmoon Slam - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77377] = { title = "To Tyrhold! For Tyr!", description = "We recovered. We trained. And now it's time to face Elisande. \n\nCome with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold.\n\nWe will get that disc, and Tyr will finally be with us once more.", objectives = "" }
WordHunterWoW_QuestEN[77398] = { title = "Eco-Dome Excursion", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77399] = { title = "Eco-Dome Excursion - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77400] = { title = "Eco-Dome Excursion - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77408] = { title = "Prophecy Stirs", description = "Prophet Velen has roused from meditation and he requests your immediate presence.\n\nA matter of great import has come to his attention. He would value both your wisdom and strength in addressing it.\n\nThe Prophet awaits you aboard the Vindicaar.\n\nTake this crystal. Our artificers have attuned it to the ship's teleportation matrix.", objectives = "" }
WordHunterWoW_QuestEN[77409] = { title = "Uncertainty", description = "Scattered visions came to me as I meditated. Yellow and red. Shattering glass. A rush of warmth. I see my own hand, but I am afraid to grasp it. The scent of fel--of Argus.\n\nWhen I awoke, a message had been delivered. Hatuun wishes to meet.\n\nAfter the defeat of the Legion, I offered to help Hatuun and his people rejoin us. However, they chose to remain on Argus. \n\nHatuun has seldom reached out to us since then. Perhaps he has reconsidered.\n\nI will make the journey to Krokuun. Please, join me.", objectives = "" }
WordHunterWoW_QuestEN[77410] = { title = "Opening Wounds", description = "My hunters were the ones who found Arzal'kal. They said he helped them fight off several Legion ambushes.\n\nDuring our endless vigil on Argus, we had seen nothing like it. He was not as powerful as some demons, but he was persistent.\n\nHe said he wished to speak with Velen and knew that we had been in contact with him. So, I have fulfilled his request.\n\nIf Velen is all he claims to be, then he would not turn away even the least worthy of his people.\n\nWe will see. I expect little.", objectives = "" }
WordHunterWoW_QuestEN[77411] = { title = "Contrition", description = "The man'ari have grown desperate since the Legion fell. Some grasp for power. Some isolate themselves. Others have formed cults awaiting the return of Sargeras. They have faith that he will lead them again one day.\n\nNalridun is the leader of one such cult. They are reclusive, but it is rumored that he has seized an ancient relic that Kil'jaeden kept until his death. Nalridun claims to use it to commune with Sargeras.\n\nI believe I know what this relic is. If I am correct, it must be returned to Velen.", objectives = "" }
WordHunterWoW_QuestEN[77412] = { title = "Proof and Promise", description = "Reinforcements are unlikely, but the relic is too important to risk. You should return to Prophet Velen with it immediately.\n\nThere is a teleporter just ahead that I can attune to a sigil of my own. It will provide you swift passage.\n\nI will rejoin you later.", objectives = "" }
WordHunterWoW_QuestEN[77414] = { title = "Dreamsurge Investigation", description = "The Emerald Dream bleeding over into Azeroth is unprecedented, {name}. We need to understand exactly what is being affected by this phenomenon if we're to prepare ourselves for what is to come.\n\nPerhaps we can even turn this to our advantage.\n\nHead out into the affected area and see what you can learn. Bring back anything of interest and we will see what can be done.", objectives = "" }
WordHunterWoW_QuestEN[77415] = { title = "The Hidden Hand", description = "Catching him at the very moment he's alone? They must've been watching somewhere nearby but just out of sight. Can you check that cave across the water?\n\nThose hornswogs are known hoarders. If those drakonid left something behind, it may still be there.", objectives = "" }
WordHunterWoW_QuestEN[77417] = { title = "What Makes an Infinite", description = "Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. \n\nBut I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment.\n\nWhen you are ready, I will see what she has to say.", objectives = "" }
WordHunterWoW_QuestEN[77423] = { title = "Surging Dreams", description = "Change is coming, {name}. Those attuned to the Emerald Dream can feel it on the wind.\n\nWe need your aid in uncovering what this change entails.\n\nLet us reconvene in the affected area and formulate a plan.", objectives = "" }
WordHunterWoW_QuestEN[77425] = { title = "The Scale of it All", description = "The Djaradin were trading harpoons with the Tuskarr? I suppose fish harpoons don't cut it when you're dealing with a dragon.\n\nHow big was this shipment do you think? Check around the Zaqali Quartermaster and see if they held onto any ancestral records.", objectives = "" }
WordHunterWoW_QuestEN[77432] = { title = "Pedgi the Parched", description = "Pedgi's being dramatic. Again.\n\nI know it seems childish, and that's because it is childish, but he responds well to little treats when he's in a mood.\n\nCould you get him a coffee from the bar downstairs?", objectives = "" }
WordHunterWoW_QuestEN[77433] = { title = "Excavation: Riverbed", description = "There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan!\n\nMeet me there as quick as you can! And wear your best, old, mud-ready boots!", objectives = "" }
WordHunterWoW_QuestEN[77434] = { title = "Technoscrying: Observatory", description = "My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores.\n\nI know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. \n\nAlways.", objectives = "" }
WordHunterWoW_QuestEN[77436] = { title = "The Burning Barrow", description = "Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil.\n\nWhile you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.", objectives = "" }
WordHunterWoW_QuestEN[77437] = { title = "Eon's Fringe", description = "Timewalker Tempo and their team finally unfroze Eon's Fringe!\n\nEr... mostly. The Timewalkers have things more or less under control but Eon's Fringe has some problems the people of the town wouldn't mind a hand with. \n\nTell Bob I sent ya!", objectives = "" }
WordHunterWoW_QuestEN[77483] = { title = "Technoscrying: Dragonskull Island", description = "I tuned my various sensors for Dracthyr relics, and they've triangulated a new location for us to investigate off the eastern coast of the Forbidden Reach.\n\nThe local Drakonid tell me it's named Dragonskull Island. Ominous, no?  You're not easily frightened, are you?", objectives = "" }
WordHunterWoW_QuestEN[77484] = { title = "Technoscrying: Igira's Watch", description = "Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. \n\nBest bring a weapon for this excursion. My preliminary scouting indicated a elevated  presence of both lava and djaradin.", objectives = "" }
WordHunterWoW_QuestEN[77485] = { title = "Technoscrying: Back to Eadweard!", description = "Thanks for all your help!\n\nLet's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.", objectives = "" }
WordHunterWoW_QuestEN[77486] = { title = "Excavation: Gaze of Neltharion", description = "A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's.\n\nGrab your favorite shovel and meet me there!", objectives = "" }
WordHunterWoW_QuestEN[77487] = { title = "Excavation: Winglord's Perch", description = "We've discovered an ancient fishing village in the Forbidden Reach! It's this humble isle off the northwest coast with its own crumbling bridge and everything!\n\nI'll be there if you're looking for more dirt to dig up!", objectives = "" }
WordHunterWoW_QuestEN[77488] = { title = "Excavation: Back to Eadweard!", description = "Great job, {name}!\n\nWe've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!", objectives = "" }
WordHunterWoW_QuestEN[77581] = { title = "Kill them Gnolls!", description = "", objectives = "" }
WordHunterWoW_QuestEN[77589] = { title = "Warmaul Wingding", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77591] = { title = "Warmaul Wingding - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77593] = { title = "Warmaul Wingding - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77644] = { title = "The Scarlet Key", description = "<Though dirt and rust have accumulated on these keys, the one you currently possess looks no different otherwise.>", objectives = "" }
WordHunterWoW_QuestEN[77645] = { title = "Skettis Scramble", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77646] = { title = "Skettis Scramble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77647] = { title = "Skettis Scramble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77662] = { title = "A Call to Aid", description = "Ah, so you are {name}?\n\nHm, I suppose Lilian consorts with heroes of all sorts now...\n\nLilian sent me with a message. She and Shandris have been tasked with tracking a powerful Druid of the Flame.\n\nHe continues to elude them, but with your assistance, they believe they can corner him and his dryad conspirators.\n\nSeek them out if you are able to aid them.", objectives = "" }
WordHunterWoW_QuestEN[77664] = { title = "One Last Step", description = "This operation would not have come this far without Lilian's aid. \n\nWe may not have much in common, but Lillian is a... dependable ally. After fighting side-by-side in the Dream, we have an odd kinship that was forged by this mission.\n\nTogether, we will finish this. With the stones in our hands, it is now safe to take out Raelas and end his little crusade.\n\nOnward.", objectives = "" }
WordHunterWoW_QuestEN[77665] = { title = "Bound to You", description = "I haven't worked with Shandris long, but... it's unusual for her to act like that.\n\nBut it doesn't matter.\n\nWhile she deals with logistics, you and I should go ahead and find a way to cleanse these stones.\n\nMaybe Shae'lune knows what to do next.", objectives = "" }
WordHunterWoW_QuestEN[77673] = { title = "Under the Surface", description = "I knew coming into this that Shandris likes to work alone, but letting us know where she's going would be nice.\n\nNot a great turn in our professional relationship.\n\nKeeper Sillas won't speak to me...\n\nWe should take a look around the camp. Maybe she left a note or some clue... maybe in her mission log?\n\nTake a look, and see if you can get anything out of Sillas. \n\nI'll wait here in case she comes back.", objectives = "" }
WordHunterWoW_QuestEN[77674] = { title = "Wounds of the Past", description = "It's all making sense now. I believe the missing dream spirit bonded with her--like Cyanthesa said.\n\nIt's making Shandris relive traumatic moments from her life. \n\nIt's not malicious, but the spirit and Shandris are feeding off each others' fears. We have to bring her back to the camp. Shae'lune might be able to help her.\n\nTalk to her. I look like the enemy right now. But maybe she'll talk to you.", objectives = "" }
WordHunterWoW_QuestEN[77675] = { title = "A Better Future, Together", description = "{name}, we need to work with Shae'lune and help her perform the purification ritual on Shandris.\n\nShae'lune says she's only done it on objects before--not people. There is some... risk involved.\n\nBut I've come to know Shandris. She'd do the same for me.\n\nTalk to Shae'lune and follow her instructions.", objectives = "" }
WordHunterWoW_QuestEN[77677] = { title = "Some Water...", description = "<The plant is clear of soot and flame, but its leaves are limp with thirst. Perhaps someone from Central Encampment will know the perfect remedy.>", objectives = "" }
WordHunterWoW_QuestEN[77679] = { title = "To Soridormi's Aid", description = "Have you heard? Time rifts are opening in Tyrhold Reservoir! It's a catastrophe! Folks have seen portals to other timeways randomly appearing. Now all kinds of fantastic creatures are swarming into Azeroth.\n\nThank goodness for Soridormi. I heard she's getting everyone organized to make a stand. If you can offer any assistance, I'm sure she could use it.\n\nThey say she's still stationed in Tyrhold Reservoir. Do it for Valdrakken. Do it for Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[77681] = { title = "Alerting all Adversaries!", description = "The Artisan's Consortium has struck another deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this leaflet to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", objectives = "" }
WordHunterWoW_QuestEN[77684] = { title = "Fel Pit Fracas", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77685] = { title = "Fel Pit Fracas - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77686] = { title = "Fel Pit Fracas - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77697] = { title = "The Right Food...", description = "<The plant is now a promising sapling and has thrived with the attention you've given.\n\nPeering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>", objectives = "" }
WordHunterWoW_QuestEN[77698] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[77711] = { title = "And a Pinch of Magic", description = "The diligence you've shown here is astounding, {name}. I never suspected that someone who couldn't even find their own bucket, could do something like this.\n\nI think the sapling is almost there, and with my help we can bring it the rest of the way.\n\nTake this totem and place it near some of the weakened, flame-corrupted Roottenders found in the Singing Fen. This should siphon the unstable magical energies out of their bodies and transform it into something we can use.", objectives = "" }
WordHunterWoW_QuestEN[77739] = { title = "Smother the Flames", description = "Lilian and I have been shadowing Raelas Firewind and have uncovered his plan. He has manipulated the Sisters of the Flame to bind spirits from the Dream to magical spirit stones.\n\nWith Raelas's blessing, these stones became powerful tools of corruption, allowing these fallen dryads to twist the Dream and its denizens.\n\nWe will start our purge with the dryads--they have the stones. Then we will end Raelas.\n\nThe hunt begins, {name}.", objectives = "" }
WordHunterWoW_QuestEN[77744] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77745] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77746] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77747] = { title = "Bar Tab Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[77760] = { title = "Curious Find: Dragonhorn Flute", description = "<This flute is inexpertly hewn out of the horn of a dragon. The cracking around the base suggests the dragon was long gone by the time the flute was made.\n\nThe mouthpiece is strange. It's almost like it isn't designed to be played with the mouth at all but the nose. Could this flute have been crafted by the niffen?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "" }
WordHunterWoW_QuestEN[77762] = { title = "A Little Hope is Never Without Worth", description = "The plant has matured and is thriving. And with this little corner of our ecosystem restored, we've seen something I've been wishing for since I learned what you were up to: the dreamtalons have returned with their kits!\n\nOne of the grateful mature dreamtalons has offered their services to you, if you wish it.", objectives = "" }
WordHunterWoW_QuestEN[77763] = { title = "Curious Find: Waterlogged Ledger", description = "<This leather-bound ledger is so waterlogged it's nearly falling apart.\n\nMost of it is illegible, but the text that has survived is in an ancient draconic dialect. It appears to be lists and lists of ordinary items, with numbers assigned to them-- perhaps a household accounting book?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "" }
WordHunterWoW_QuestEN[77766] = { title = "Curious Find: Hole-Punched Bakar Tooth", description = "<This milk-tooth came from a young bakar, though the way the bone has yellowed suggests it's thousands of years old.\n\nSomeone has carefully drilled a hole at the top of this tooth to turn it into a bead. Upon closer examination, the tattered remains of a woolen cord can still be seen threaded through it.\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", objectives = "" }
WordHunterWoW_QuestEN[77777] = { title = "Ruby Lifeshrine Loop - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77779] = { title = "The Tale of Sir Thomas", description = "Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, {name}.\n\nDo you still have my tome? My story has reached its end, and I would see it penned by my own hand.\n\n<Thomas glides his finger across a blank page, spectral ink marking his words.>\n\nPlease return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?", objectives = "" }
WordHunterWoW_QuestEN[77780] = { title = "A Blossom Witnessed", description = "Amirdrassil has bloomed beyond the confines of the Dream.\n\nLet us venture to the Dragon Isles and see where this new World Tree has taken root.", objectives = "" }
WordHunterWoW_QuestEN[77781] = { title = "A Different Enthusiasm", description = "I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes.\n\nTheir pranks have been more than disruptive. Please root them out so the celebration may continue in peace.", objectives = "" }
WordHunterWoW_QuestEN[77784] = { title = "Tyrhold Trial - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77785] = { title = "Fen Flythrough - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77786] = { title = "Vakthros Ascent - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77787] = { title = "Stormsunder Crater Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77788] = { title = "Ashphodel Research Notes", description = "<You find some singed research notes on the slain druid. \n \nThe notes detail experiments being carried out by the Druids of the Flame.  \n\nYou learn that they have created an unusual pollen capable of infusing dream flora with their flame-imbued magic. The next stage targets the local wildlife with the same pollen. \n \nQ'onzu would definitely be interested in a sample of the pollen and these notes.>", objectives = "" }
WordHunterWoW_QuestEN[77789] = { title = "Severing Ties", description = "Nalridun has recruited a small army of cultists. They believe he speaks for Sargeras through the relic, clinging to every word he says. The same way we clung to our leaders when Sargeras came to Argus. It was a comfort. A hope.\n\nAnd, in the end, empty deception.\n\nBut his followers do not believe they are deceived. They have constructed their own conduits in the area to try to tap into the relic's power. To hear the voice themselves.\n\nThey will try to stop us. We must cut a path through them.", objectives = "" }
WordHunterWoW_QuestEN[77791] = { title = "Handling It: Symbiotic Glowspore Grip", description = "I know a crafter who could help temper Fyr'alath. Erden of Clan Shikaar is extremely resourceful. He's performed many experiments with various reagents throughout the Dragon Isles.\n\nHunters are only as good as their weapons. Erden is known for crafting exquisite weaponry with exotic materials. His expertise in various flora and fauna should prove quite informative.", objectives = "" }
WordHunterWoW_QuestEN[77793] = { title = "Crystal Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77795] = { title = "Scavenged Artifacts", description = "", objectives = "" }
WordHunterWoW_QuestEN[77802] = { title = "What Do I Call You?", description = "Guardian! Or... teacher! Parent?\n\nI want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own.\n\nI want to tell them that I do not have a druid. I have you!\n\nTell me what title you prefer.", objectives = "" }
WordHunterWoW_QuestEN[77813] = { title = "Lightning Strikes", description = "<Flaps does a spin and deposits a drool-soaked note into your hand.>\n\nAh, {name}. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself!\n\nI would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.", objectives = "" }
WordHunterWoW_QuestEN[77815] = { title = "The Storm Race Tour", description = "This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration.\n\nBut since you are here, let us test its training--and your riding skills.\n\nMy colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\".\n\nFortune favors the bold, {name}. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[77818] = { title = "The Cruel", description = "Primalists, djaradin, and Druids of the Flame all work together against us.\n\nBut I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.", objectives = "" }
WordHunterWoW_QuestEN[77822] = { title = "A Titanic Mold", description = "<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>", objectives = "" }
WordHunterWoW_QuestEN[77831] = { title = "A Key To Reforg(ing)", description = "You have the final materials! Perfect.\n\nI prepared the forge and the mold. I just need you to add the ingredients when I say.\n\nOh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!", objectives = "" }
WordHunterWoW_QuestEN[77832] = { title = "Shadows upon shadows", description = "I need to save him.", objectives = "" }
WordHunterWoW_QuestEN[77833] = { title = "Handling It: Concentrated Sophic Vellum", description = "I know of a sage who can help temper Fyr'alath. Shalasar Glimmerdusk is an expert in intellectual matters, often pondering theories for controlling volatile magics. Few understand sophic matters as well as she does.\n\nSeek her guidance in managing shadowflame. I suspect her solution may include a sprinkle of Chromatic Dust!", objectives = "" }
WordHunterWoW_QuestEN[77835] = { title = "Handling It: Rune of Shadowbinding", description = "Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them.\n\nIf there is anyone who can assist in binding Fyr'alath's power, it's her.", objectives = "" }
WordHunterWoW_QuestEN[77838] = { title = "Tattered Dreamleaf", description = "The properties of Dreamleaf are foreign to you. \n\nCompleting events during the Superbloom will give you the knowledge necessary to help your ally.", objectives = "" }
WordHunterWoW_QuestEN[77839] = { title = "The Eastern Kingdoms Cup Circuit", description = "It is once again time to test your mettle.\n\nMy bronze colleagues have traveled to the Eastern Kingdoms to create new racing challenges. Many racecourses await you across the continent.\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[77840] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[77841] = { title = "Ysera Invitational", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77842] = { title = "Ysera Invitational - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77843] = { title = "Ysera Invitational - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77844] = { title = "Ysera Invitational - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77845] = { title = "Ysera Invitational - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77869] = { title = "Return to the Echo Isles", description = "{name}, there appears to be trouble in the Echo Isles.\n\nRokhan has requested your help.", objectives = "" }
WordHunterWoW_QuestEN[77871] = { title = "De Old Loa", description = "Bwonsamdi does not be visiting in person without a good reason. Listen to all he has to say. \n\nDen we think, den we act.", objectives = "" }
WordHunterWoW_QuestEN[77874] = { title = "De Loa of de Past", description = "We need to be findin' de old loa and call dem back. There must be a way to find where dey went. \n\nIf we can find de old loa, we can host a Trial of the Loa to reconnect with their power.\n\nBwonsamdi said dey are still out there. I think he be dropping a hint for us...", objectives = "" }
WordHunterWoW_QuestEN[77877] = { title = "One with the Loa", description = "Pieces of Lukou be scattered.\n\nBut her heart be deep inside the ogre mound.\n\nDe shadows can take us there. Quietly. Quickly. Speak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[77879] = { title = "Stalking the Stalker", description = "If dis loa be huntin' here, he may have seen us already. Since we don't know for sure, let's split up.\n\nI be hunting for him, while ya get his attention. Jani says the loa has been taking the offerings meant for Hakkar, the loa of blood. \n\nBut we don't know WHY. Collect some and see if he wants them. If his motive is something else... we be knowin' soon enough.", objectives = "" }
WordHunterWoW_QuestEN[77880] = { title = "Looking for Lukou", description = "Dis be the last place Kevo ya Siti sensed Lukou.\n\nWe be needing to ask around, see who knows where she might have gone.", objectives = "" }
WordHunterWoW_QuestEN[77881] = { title = "There is Another", description = "If Mueh'zala be involved... I will help. But for a loa trial fit to push Mueh'zala out, we will need another.\n\nOur sister loa is also lost. We were a team, her and I, until disagreement pushed us apart. Lukou is the loa of regeneration. She be the ideal loa to balance against death.\n\nI owe her an apology. You are here, and it be time.\n\nI last sensed her presence near the small settlement of Bambala. I be meeting you there.", objectives = "" }
WordHunterWoW_QuestEN[77882] = { title = "Stolen but Not Forgotten", description = "There be many pieces missin' from dis altar. We be needing to repair it so dat Lukou is not angered when she returns, Lukou must see dat we are on her side.", objectives = "" }
WordHunterWoW_QuestEN[77886] = { title = "Handling It: Shadowed Dreamleaf", description = "When Fyr'alath's power is at its limit, you will need a grip that can cool itself. It is like standing your ground when a beast charges you: as the battle heats up, you need a way to stay focused.\n\nVarious leathers throughout the Dragon Isles have that cooling property, but I know of something better. Foliage that is routinely exposed to shadowflame would be the best choice for binding the components together. Let us gather what you need.", objectives = "" }
WordHunterWoW_QuestEN[77889] = { title = "A Fiery Proposal", description = "Ah hello!\n\nI have been working with some inscribers recently. We've been making a new type of ink. It's like fire ink, but even fierier! \n\nWe need fiery essence from fire elementals, and fire elementals are currently attacking the dream. I believe this is what is called a \"win win\" scenario.\n\nPlease drop their essence off at my associate in Amirdrassil.", objectives = "" }
WordHunterWoW_QuestEN[77891] = { title = "Fixing The Dream", description = "Engineering is an exact science! When something explodes, engineers plan it that way. \n\nDreams are not exact, especially emerald ones! Someday, someone will want engineers to fix the Dream, and we won't know how to do it. We need a lot more information to understand what we're dealing with!\n\nGo to the Dream and place research beacons at my designated points. They will gather the information needed for any future repairs. Use this handy teleport device if you want to find the locations quickly.", objectives = "" }
WordHunterWoW_QuestEN[77892] = { title = "Pearls Of Great Value", description = "When Amirdrassil's roots spread to the water, many rare creatures arose from the ocean's depths and now flourish around the dreams.\n\nOne such rare creature is the Sandsparkle Clam, which can contain magical pearls!\n\nSee if you can locate these clams and find some pearls within.", objectives = "" }
WordHunterWoW_QuestEN[77894] = { title = "Heart of Lukou", description = "I was hoping we'd be getting more pieces than dis, but we make do with what we got, eh?\n\nCall Lukou to de altar. Hopefully she will answer.", objectives = "" }
WordHunterWoW_QuestEN[77896] = { title = "A Sleepy Search", description = "In our fight against Fyrakk's forces, a group of my fellow druids went out in search for a quiet and safe place to rest. But with Fyrakk's forces closing in on their location...\n\nI have to start planning for another assault, I can't split my time as much as I wish. \n\nI last saw them heading south to a cave by the shore. Please, I just need to make sure they're safe.", objectives = "" }
WordHunterWoW_QuestEN[77898] = { title = "Honor and Tribute", description = "It be time to return home. Let us welcome dese loa to the Echo Isles. Their positive influence should make short work of Mueh'zala's presence.\n\nGo ahead, I be right behind ya.", objectives = "" }
WordHunterWoW_QuestEN[77899] = { title = "The Rush'kah", description = "When we make de rush'kah, we recreate de shape of the loa as we be seein' dem in our mind. By knowing the shape of de loa, we better understand who dey are. But de mask be shaped by our hands, so when de loa sees it, dey know what we expect dem to be. \n\nIf the loa don't bless the mask, we expect dem to be something dey will not be. If de loa bless de mask, dey like what we see in dem and a bargain can be struck. \n\nWe could just write a contract, but it is easier to lie with words than with your hands.", objectives = "" }
WordHunterWoW_QuestEN[77900] = { title = "The Loa Trials", description = "When de loa bless the rush'kah, de trials will begin. Loa be giving tasks to teach us. Once de trials start, dey don't stop for nobody!\n\nLet's go to de altar together. Witch Doctor Tzadah will lead us in de ritual. She be Master Gadrin's apprentice, but be showin' real initiative in helping out on the trial.", objectives = "" }
WordHunterWoW_QuestEN[77901] = { title = "Retraining the Trainees", description = "Your witch doctor is trying to twist the trial to empower Mueh'zala. Many will be enthralled by this power, but we still stand with the Darkspear.\n\nI had a different trial in mind. Now, we adapt. Free your fellow trolls from his sacrificial magic. Dis charm will help them, but you must weaken them first.\n\nTry not to sacrifice dem.", objectives = "" }
WordHunterWoW_QuestEN[77902] = { title = "Ritual Recovery", description = "Dat witch doctor has stolen de trial. She mocks us, trying to eat de life of living things to free Mueh'zala. We still have influence over it, though. \n\nTogether, we will overwhelm her evil circles. When you find a circle, call upon me, and we will push death aside.", objectives = "" }
WordHunterWoW_QuestEN[77903] = { title = "De Power of Death", description = "De trial can't be stopped after it starts, but we won't let Tzadah use our people or our loa to aid Mueh'zala.\n\nIf we be doing nothing, even more Darkspear could be swayed to find power in Mueh'zala. I'll look for a way to breach Tzadah's protective energy, you stop the spirits from taking over our home!", objectives = "" }
WordHunterWoW_QuestEN[77905] = { title = "Avatar of Mueh'zala", description = "It be down to dis moment: working with our loa to save de soul of de Darkspear.\n\nSee if Jani has found anything. Hopefully, his item will let you get close enough to Tzadah's effigies to destroy dem. That should give us a chance to strike the Witch Doctor herself. I'll occupy her attention with Kevo ya Siti's aid, but watch out for her guardians. Dey won't let you destroy her effigies without a fight.", objectives = "" }
WordHunterWoW_QuestEN[77906] = { title = "De Darkspear Loa", description = "Dat was not a traditional trial, but we only keep tradition if it be helping de tribe.\n\nIt be our strength: to adapt to what comes.\n\nIt be time to shed de past and honor those most important to us. De Darkspear was never de largest tribe, nor de strongest. We endure because we choose our path, and our allies, well.\n\nDese loa and you all worked and sacrificed not just to help Bwonsamdi, but to protect de souls of de Darkspear. Dat be why we honor our loa... and you.", objectives = "" }
WordHunterWoW_QuestEN[77908] = { title = "A Legacy of Secrets", description = "<Return the book to Bobby Carlisle in Valdrakken to assist with deciphering the tablet text!>", objectives = "" }
WordHunterWoW_QuestEN[77910] = { title = "Enchanted Shrubbery", description = "Certain plants from the Emerald Dream could contain ingredients that would be helpful in our work here, but we need a lot of them, and I'm not hiring some herbalist to collect them.\n\nI've enchanted a water pot to help solve the problem. \nTravel to the Emerald Dream and use it on the plants I require. The plants should then deliver themselves.", objectives = "" }
WordHunterWoW_QuestEN[77911] = { title = "Build-a-Blanket", description = "I am unable to rest! I have spent all my energy in battle, but there is too much noise and the ground is too hard for me to sleep...\n\nI know! It pains me to ask this, but I need to rest so I can go back out and fight.\n\nCould you feed two birds with one seed for me? Take out the enraged lashers and retrieve their leaves so I can make a blanket to rest on.", objectives = "" }
WordHunterWoW_QuestEN[77912] = { title = "Unmodern Jewelry", description = "Some of the local Jewelcrafters are looking to study examples of the Zaqali tribes adornments.\n\nGiven they are currently attacking my home, we may take advantage of the situation.\n\nI thought you might take them violently, yes?\n\nArgonax waits once you have collected them.", objectives = "" }
WordHunterWoW_QuestEN[77914] = { title = "Burning Runes", description = "I am told that the Druids of the Flame help to stabilize their portals into the dream through the use of a unique sort of inscription! While their ends are abhorrent, I cannot help but be curious as to their means.\n\nIf we can better understand their methods, then perhaps we can better equip our allies to stem the tide of their arrival. If you get your hands on any burning runes, could you bring them to my colleague for further study?", objectives = "" }
WordHunterWoW_QuestEN[77922] = { title = "Fluffy Filler Retrieval", description = "There is no way I could rest without something soft to sleep on. Luckily, the dream has some sage so plush, that it would even put roc feathers to shame! It would be a perfect filling! \n\nCould you collect some sage around the area for me to rest on?", objectives = "" }
WordHunterWoW_QuestEN[77932] = { title = "Warmth of Life", description = "The Druids of the Flame practice virulent magics that warp and burn all they touch. They do, however, have excellent taste in alchemical reagents.\n\nIf you should happen across any of their metamorphic ash, could you gather it up for me? One of my contacts within the Dream has been asking after the stuff.", objectives = "" }
WordHunterWoW_QuestEN[77933] = { title = "Bubbling Discoveries", description = "The rise of Amirdrassil has unlocked various geological wonders in the dream. Among these are a variety of magical springs, bubbling water from deep within Azeroth.\n\nTravel the dream and gather samples from these springs.", objectives = "" }
WordHunterWoW_QuestEN[77934] = { title = "A Complete Inventory", description = "<Compile your notes on the caches for Fangli Hoot in Valdrakken.>", objectives = "" }
WordHunterWoW_QuestEN[77935] = { title = "A-Sword-ed Needs", description = "Swords!\n\nSorry, I saw you and I did not want to forget.\n\nYes. We need swords. In the Dream. You can provide, yes?\n\nPlease deliver them to Cylania.", objectives = "" }
WordHunterWoW_QuestEN[77936] = { title = "A Warm Harvest", description = "Everyone knows heat plays a critical role in blacksmithing.\n\nI hear the Emerald Dream is still heavily under attack by allies of the flame. There must be a way to harvest fuel from those eternally fiery creatures.\n\nIf you do secure anything, I'm sure one of the local blacksmiths in the Dream will be very interested.", objectives = "" }
WordHunterWoW_QuestEN[77937] = { title = "Forbidden Sugar", description = "During this very unique time of bloom, a new flower has been discovered in the Dream. These stunning flowers produce a marvelous pollen. Its aroma is a delight, just like fresh baked cookies.\n\nTo the dismay of chefs, even eating a tiny bit will result in rapid, severe poisoning of the liver.\n\nHowever, it is an incredible all-purpose addition to enchanting. Early tests demonstrate potency as high as quadruple that of Chromatic Dust. Traders from Valdrakken are very interested in its acquisition.", objectives = "" }
WordHunterWoW_QuestEN[77938] = { title = "An Unlikely Engineer", description = "I hear there is a legendary engineer in the Dream who crafts the most beautiful dream catchers.\n\nThis engineer, Nyla Bushtail, enjoys acorn-flavored morels and relies on them to fuel her work. Acorn-flavored mushrooms... certainly strange, but perhaps not unheard of.\n\nThere's a coastal area close to the Eye of Ysera where these morels grow abundantly. Do tread carefully around any wildlife in the area. If these morels are as tasty as I hear, they will be guarded greedily.", objectives = "" }
WordHunterWoW_QuestEN[77945] = { title = "Boots on the Ground", description = "Just who I wanted to see.\n\nI have a requisition script for items of leather from some of the denizens of the Dream. Shoes, of course. Bipeds tend to go through them like a bird through the forest, yes?\n\nOnce you have acquired them, please take them to Cylania.", objectives = "" }
WordHunterWoW_QuestEN[77946] = { title = "Fibrous Thread", description = "Fine thread may conjure images of tailory, but it can serve a vital role in leatherwork as well.\n\nSome of the Dream's hardier flora can be processed into a thread strong enough to secure even the thickest of hides and scales. If you happen upon any dense fiber during your travels, you would be well-served by bringing it to my colleague in the Dream.", objectives = "" }
WordHunterWoW_QuestEN[77947] = { title = "Primalist Fashion", description = "Ah, {name}, there you are!\n\nThe robes of the primalists make for interesting study for the local tailors. If you could retrieve some from the primalists assaulting the dream, I would be pleased, yes?\n\nNo rips or tears please. Blood stains optional. They can be washed out.", objectives = "" }
WordHunterWoW_QuestEN[77948] = { title = "Burning Out", description = "Please, I know how this looks, but we are on the same side!\n\nMy siblings and I intended to defect from the Flame together. However, none of them have escaped or met up with me since I left, and it's been days! I fear the worst.\n\nDo you think I would be begging for aid, alone and unarmed, if I was not honest? Please, find them. They are all I have left.", objectives = "" }
WordHunterWoW_QuestEN[77949] = { title = "Fashion Feathers", description = "Much of the Dream's wildlife is feathered or furred. Their shed, whether it be down fur or feathers, is reputed to be extremely durable, soft, and fashionable.\n\nThe great somnowls' feathers are particularly desirable. They don't shed often, and feathers are quickly retrieved by local wildlife for nest building.\n\nI've heard that your best chance is scouring the Meandering Rootlands in the Dream.", objectives = "" }
WordHunterWoW_QuestEN[77954] = { title = "A Curious Orb", description = "<Tithris told you to return the orb to him in Valdrakken. He will pass it to Preservationist Kathos.>", objectives = "" }
WordHunterWoW_QuestEN[77955] = { title = "Heated Hearthstone Hustle", description = "Wait, my hearthstone! I can't sleep without my hearthstone. \n\nA djaradin stole it during our last battle. It stays warm perpetually and I always sleep with it. \n\nI hate that I must ask more of you, but could you get my hearthstone? \n\nThe djaradin that stole it should be near Fyrakk's army, just north of here.", objectives = "" }
WordHunterWoW_QuestEN[77958] = { title = "Sleepy Druid in Emerald Dream", description = "Why can I still not fall asleep, even with a heated blanket? \n\n<Thaalean curses the air then sighs.>\n\nThis is embarrassing to request, but my mother used to sing me a lullaby before I slept back in Teldrassil, may I ask you to do the same?\n\nAny lullaby will do, I just want to rest peacefully.", objectives = "" }
WordHunterWoW_QuestEN[77976] = { title = "Aiding the Accord: Dreamsurge", description = "A group of druids from across Azeroth have gathered to investigate a sudden surge in energies coming from the Emerald Dream.\n\nThis has the potential to affect us all, {name}. Please aid them in their endeavor to understand this new phenomena.", objectives = "" }
WordHunterWoW_QuestEN[77977] = { title = "An Ominous Artifact", description = "<An orb would fit perfectly atop the console.>", objectives = "" }
WordHunterWoW_QuestEN[77978] = { title = "A Passed Torch", description = "<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> \n\n<It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>", objectives = "" }
WordHunterWoW_QuestEN[77983] = { title = "Smoldering Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77984] = { title = "Smoldering Sprint - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77985] = { title = "Smoldering Sprint - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77986] = { title = "Smoldering Sprint - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77987] = { title = "Smoldering Sprint - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77988] = { title = "Test", description = "Bronze whelps can be careless when trying to win, so be careful with the timeways!\n\n[Growth Spurt]: Tranform into an adult and gain improved speed.\n[Bedtime Rewind]: Restore 1 Vigor until all Vigor has been recovered.\n[Sacred Timeline]: Resets cooldowns.", objectives = "" }
WordHunterWoW_QuestEN[77996] = { title = "Viridescent Venture", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77997] = { title = "Viridescent Venture - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77998] = { title = "Viridescent Venture - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[77999] = { title = "Viridescent Venture - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78000] = { title = "Viridescent Venture - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78002] = { title = "To The Test: Concentrated Sophic Vellum", description = "The Order and shadowflame magics are competing with each other. The enchantment will never be able to funnel Fyr'alath's power if we can't channel the excess Order magic being forced away from it.\n\nIf you can channel the enchantment, your allies can catch any excess Order magic.", objectives = "" }
WordHunterWoW_QuestEN[78003] = { title = "Handling It: Taut Tethercoil", description = "I've read of a root in the Emerald Dream known for its defensive qualities. It binds its tendrils to powerful foes as a way to protect surrounding flora and fauna. A friendly scribe might be able to help you adapt its properties.\n\nIf I could just get my hands on some of that root, I'm sure I could dissect its properties and mold it into something capable of harnessing Fyr'alath's power.\n\nHere are my notes. You should be able to find powerful creatures guarding patches of wild tethercoil. Good hunting.", objectives = "" }
WordHunterWoW_QuestEN[78016] = { title = "Shoreline Switchback", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78017] = { title = "Shoreline Switchback - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78018] = { title = "Shoreline Switchback - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78019] = { title = "Shoreline Switchback - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78020] = { title = "Shoreline Switchback - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78040] = { title = "The Outland Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[78041] = { title = "Sky Mother's Ire", description = "We received reports that the Druids of the Flame have established another staging ground just south of the Eye of Ysera.\n\nUnfortunately for them, their incursion point has disrupted the local winged wildlife and drawn the ire of the Mother of Flight.\n\nSpeak with Aviana and lend her your aid. We will need her eyes and wings in the battle to come.", objectives = "" }
WordHunterWoW_QuestEN[78042] = { title = "Aviana's Assessment", description = "<Aviana's eyes narrow as she watches the Druids of the Flame far below.>\n\nQ'onzu may be content with letting these heretics destroy the very fabric of the Dream, but I am not.\n\nBring me scraps of their armor stained with blood as proof of your deed.\n\nDo not hold back, {name}. Remember what these heathens are capable of.", objectives = "" }
WordHunterWoW_QuestEN[78043] = { title = "Q'onzu's Quandary", description = "You again! Well, you must be here to help, correct? \n\nAbsolutely you are. Why would you not? This development is so exciting. What could these desolating druids be up to?\n\nFortunately, a few of my friends have infiltrated the druids. I'm sure they have quite the story to tell. \n\nGo forth, my curious companion and bring back exciting news!", objectives = "" }
WordHunterWoW_QuestEN[78044] = { title = "Appalling Pollen", description = "This cinder pollen doesn't evoke interesting change. It consumes all until nothing, but ash remains. It brings... uniformity.  \n\nAnd I find that to be tragically stale. \n\nI'm all for change, no matter the origin. But if THIS change stymies all future possibilities for further change, then it must be stopped. \n  \nIf creatures of the dream have been infected by this pollen, then they must be extinguished. This is not a flame that can be allowed to grow.", objectives = "" }
WordHunterWoW_QuestEN[78045] = { title = "Uproot the Cause", description = "<Aviana's gaze remains locked on Q'onzu for a moment, her brow furrowed.> \n \nWhile I don't see eye to eye with Q'onzu's fascination for change, their incessant inquiry has unveiled a more deep-seated plot than originally suspected. \n\nPutting down the wildlife won't mean much if we don't tear out the root of the cause.  \n \nLocate the burning ashphodels in the glade below and tear them out.", objectives = "" }
WordHunterWoW_QuestEN[78046] = { title = "Overseer Oversight", description = "Those research notes you brought Q'onzu made mention of the ones behind these foul experiments.  \n \nThe overseer, the one named Chardryn, has been under our noses this whole time. \n\nHe oversees their research station below us.  \n \nIf we are to permanently end their terrible experiments and disrupt their progress, then he must be made an example of.", objectives = "" }
WordHunterWoW_QuestEN[78047] = { title = "The Outland Cup Circuit", description = "It is time once again to test your mettle.\n\nMy bronze colleagues have traveled to Outland to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit!\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[78064] = { title = "Q'onzu's Perception", description = "You have many questions and I have many worries. \n\nSuch pressing worries. An interloper, a rude disrupter of our joyous day. How I worry so. If only someone could confront this trespasser.\n\nWait, you could do it for me! It's a win-win, you go confront the trespasser and I answer your questions. I've tracked them down to a cave in the north. Surely you can handle them.", objectives = "" }
WordHunterWoW_QuestEN[78065] = { title = "The Q'onzu Query", description = "Champion, I understand we were unable to convince Q'onzu to join us. However, we need all the aid we can gather.   \n\nYou must discover why they refuse to aid us and convince them of the right path. Q'onzu and I have a rather strained relationship. Your efforts could bear more fruit. \n\nI hear Q'onzu has built a nest near Shiversnap Grove. Would you go and approach them?", objectives = "" }
WordHunterWoW_QuestEN[78066] = { title = "The Answers You've Earned", description = "Ah, that's much better. Now I can think.\n\nWhat did you want, again? Oh yes! Questions. \n\nAsk away, if you must.", objectives = "" }
WordHunterWoW_QuestEN[78068] = { title = "An Artificer's Appeal", description = "{name}, I received an item for you from Grand Artificer Romuul.\n\nRomuul wished for you to listen to the message before proceeding to the Exodar.", objectives = "" }
WordHunterWoW_QuestEN[78069] = { title = "Reviving Tradition", description = "The Prophet wished to personally ask for your help with the Tishamaat. But since he is working elsewhere, I asked you first to jumpstart our task.\n\nMy colleague and I have been working on a special project. And since the Prophet has declared today the Tishamaat, we will unveil it at the celebration!\n\nFor this, I need the emitter, but it needs an overhaul. We only have time for a hot wiring.\n\nGet some filament and a soldering tool from the crates nearby, {name}. Then maybe I can wire it to an array.", objectives = "" }
WordHunterWoW_QuestEN[78070] = { title = "Pressing Deadlines", description = "During this Tishamaat, Ataanya and I will present our project's schematics.\n\nAtaanya is High Artificer of Shattrath. Her father was my late mentor, the famed Exarch Hataaru.\n\nHataaru's hoofplates are hard to fill, but Ataanya has more than done so.\n\nShe has the schematics, and she should be here when they are presented. But she is not responding to my messages.\n\nAtaanya seldom leaves the city, but surely she can make an exception for the Tishamaat. Perhaps you can reason with her.", objectives = "" }
WordHunterWoW_QuestEN[78071] = { title = "Rush Order", description = "My schematics speak for themselves.\n\nEach calculation has been verified. It is respectful of all building codes. I even included a layout of the channels that the power grid must follow.\n\nRomuul knows the project. He already signed off on everything. He can explain it to the masses himself.\n\nI do not need to waste my valuable time traveling to the Exodar for this ridiculous holiday.\n\nMy apprentice will give you the schematics on a data crystal. Take it and leave.", objectives = "" }
WordHunterWoW_QuestEN[78072] = { title = "An Old Wound", description = "<Beruun whispers to you.>\n\nThere are ways, I'm sure you know, for the draenei to speak to the dead.\n\nIt's not the same as having a loved one back but...\n\nHataaru's ashes were taken to Auchindoun after the soulpriests reclaimed the temple. Maybe they might know a way to help Ataanya with her loss?", objectives = "" }
WordHunterWoW_QuestEN[78073] = { title = "Lingering Scars", description = "I believe we may be able to help.\n\nBut perhaps you could aid me first...\n\nWhen we received word that the Tishamaat was upon us, we hurried to prepare our most tortured spirits for the journey to the Exodar. The celebration's sacraments may help them rest peacefully.\n\nHowever, they must consent to being moved. So, we must commune with and soothe them first.\n\nWill you help calm these spirits? Afterward, I will take you to where Hataaru is entombed and give you what you seek.", objectives = "" }
WordHunterWoW_QuestEN[78074] = { title = "To See Clearly", description = "Fortunately, not all of the fallen entombed here in Auchindoun suffer as these three do. Some ease gracefully into death, like soil settling after a rainfall.\n\nExarch Hataaru is one such soul. Thanks be to the Light that he rests easy.\n\nCome, I will show you to his tomb.", objectives = "" }
WordHunterWoW_QuestEN[78075] = { title = "Moving Past", description = "My mother died on a colony planet. My father and I helped each other move past that, but when he died in the siege of Shattrath, watching the walls of his greatest accomplishment crumble to dust... \n\nThere was no one left for me.\n\nSo I worked. And now I have the schematics of my own Shattrath. A better Shattrath.\n\n<Ataanya clenches the lens in her fist then exhales in resignation.>\n\nI'll go to the Exodar--but if Romuul says one word about it, I will make him eat his soldering tool.", objectives = "" }
WordHunterWoW_QuestEN[78076] = { title = "Emergency Efforts", description = "{name}! Velen told me I may find you here. He needs your assistance.\n\nThe satyr that infest a nearby island have been ambushing draenei traveling for the Tishamaat.\n\nVelen and I have been attempting to solve the problem quietly. He does not wish to mobilize the vindicators and alarm his people on a day of sacrament.\n\nBut, despite our efforts, the attacks have continued. The event may need to be canceled if we cannot get the demons under control.\n\nCome with me so we may end this threat.", objectives = "" }
WordHunterWoW_QuestEN[78077] = { title = "Beneath the Skin", description = "Arzaal and I are of the same mind. We must know the strength of these satyr before we attempt to drive them back with force. Else we may be walking into a fight we cannot win.\n\nI can learn much about my enemies by observing what damage they leave in their wake. \n\nThe wildlife here was corrupted by the Exodar's lingering energies, but I suspect the demons' presence made it worse.\n\nCollect bones from the local wildlife for me. Studying them may give us some clues.", objectives = "" }
WordHunterWoW_QuestEN[78078] = { title = "Assessing the Enemy", description = "The Legion may be one entity, but it is vast. The demons that comprise it are as varied as the innumerable worlds they have conquered.\n\nBut I have had no dealings with satyr. From what the Prophet has told me, they seem disorganized. Intelligent certainly, but feral in their malevolence.\n\nI am inclined to believe their recent attacks are random, but perhaps not. Bring me the totems they have scattered across Bloodmyst. I may be able to ascertain what, if anything, their end goal is.", objectives = "" }
WordHunterWoW_QuestEN[78079] = { title = "Excision", description = "I cannot in good conscience gather the draenei for the Tishamaat if we are threatened this close to home.\n\nIf one of the man'ari is using the satyr to orchestrate these attacks, or to distract us from some larger foul purpose, then they must be rooted out immediately.\n\nWe will divide our efforts to look for signs of the enemy. Arzaal will search the northern satyr camp. You, Hatuun, and myself will search the closer camp.", objectives = "" }
WordHunterWoW_QuestEN[78080] = { title = "At the Source", description = "Can you hear that? The silence? \n\nThe area is empty. Not even the rabid wildlife dare approach the camp.\n\nI do not see any immediate cause, but the fel resonance here is overwhelming. I sense it was woven by man'ari hands, but I'm being blocked from probing more deeply.\n\nSomething is being hidden.\n\nIt must be the cloaking magic Hatuun reported from the other camp that hinders me. I can dispel it, but I cannot guarantee what we will find when I do.", objectives = "" }
WordHunterWoW_QuestEN[78081] = { title = "Pain Recedes", description = "With Sironas slain once again, Bloodmyst will finally be able to heal. Her influence was no doubt anchoring the corruption to the land.\n\nIt is another reason to celebrate today. But it is not the true reason I called Hatuun and Arzaal to Azeroth.\n\nI would have them attend the Tishamaat with us.\n\nThe sacrament asks us to reflect on the past and commit to a better future. The unity of our efforts epitomizes that.\n\nI will bring them to the Exodar. Please join us when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[78082] = { title = "A Burden Shared", description = "The Tishamaat was once a solitary holiday. Each eredar would inscribe a stone with a painful memory we carried. We would reflect on what that memory could teach us then commit to moving forward with that wisdom.\n\nAt last, the stones are dissolved in the Flame of Reprieve, symbolically removing the weight from our souls.\n\nToday, the Tishamaat will be celebrated not in solitude, but as a community.\n\nGather the stones of those who would trust you with them then take them to the flame.", objectives = "" }
WordHunterWoW_QuestEN[78083] = { title = "Our Path Forward", description = "Ah, I believe I hear the Prophet calling the attendants before the stage.\n\nI am curious to see what he and Romuul plan to announce now that everyone is gathered.\n\nWe should make haste, yes?", objectives = "" }
