WordHunterWoW_QuestEN[78113] = { title = "The Challenge Tour", description = "Hello again adventurer!\n\nDo you like a challenge? I hope so as my bronze colleagues have a new set of challenge courses for you to fly.\n\nMake no mistake, these will be more difficult than the previous courses. All the obstacles remain but there none of the boons waiting for you along the route.\n\nAre you up to the challenge?", objectives = "" }
WordHunterWoW_QuestEN[78115] = { title = "Emerald Amble", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78116] = { title = "Emerald Amble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78117] = { title = "Emerald Amble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
