WordHunterWoW_QuestEN[78119] = { title = "Emerald Amble - Reverse Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78131] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[78153] = { title = "Handling It: Prototype Rune", description = "Ah, I see! We're in uncharted territory here, but I've got a plan.\n\nYou'll need some Cosmic Ink, Runed Writhebark, and Shadowflame Essence.\n\nSharing this recipe with a friendly scribe should allow them to complete a Crafting Order for you. Let me update my notes with a recipe for the Rune of Shadowbinding.", objectives = "" }
WordHunterWoW_QuestEN[78154] = { title = "To the Test: Rune of Shadowbinding", description = "We need to finalize the binding. We can attune the components properly by testing them in combat against Fyrakk's most powerful lieutenants. Then we can bind the attuned materials to Fyr'alath.\n\nIf you can defeat Gnarlroot, Igira the Cruel, and Volcoross while this rune is bound to them, you'll be ready to fully attune the Rune of Shadowbinding.", objectives = "" }
WordHunterWoW_QuestEN[78155] = { title = "Handling It: Radiant Fleck of Ash", description = "I've heard that in the Emerald Dream, a coarse ash with strong properties of shadowflame tends to cling to powerful pieces of equipment. The only way to harvest that powerful dust is by disassembling the equipment. \n\nHere, use this rod I've enchanted. It should allow you to siphon off the dust you need.", objectives = "" }
WordHunterWoW_QuestEN[78156] = { title = "Handling It: Radiant Vellum", description = "We can refine my creation by embedding the enchantment with Order magic. \n\nHere are my notes on Concentrated Sophic Vellum. Sharing this with another friendly enchanter should give them enough info to complete a Crafting Order for you.", objectives = "" }
WordHunterWoW_QuestEN[78159] = { title = "Handling It: Glowspore Grip", description = "To craft something workable, we'll need a substantial amount of Zaralek Glowspores and some leather.\n\nHere are my notes on the Symbiotic Glowspore Grip. Sharing this with a friendly leatherworker should give them enough info to complete a Crafting Order for you.", objectives = "" }
WordHunterWoW_QuestEN[78160] = { title = "To the Test: Symbiotic Glowspore Grip", description = "You will have to trust me. We need to activate the reagents embedded in the grip.\n\nWrapping the grip around Fyr'alath's haft should work, as long as you can survive the onslaught that follows. You're going to need to make adjustments as you go, and you won't get it the first time. The spores need to adapt to the axe.", objectives = "" }
WordHunterWoW_QuestEN[78162] = { title = "Q'onzu's Distraction", description = "Truly your questions are important to me. Alas, I am simply too distracted. \n\nThese podlings--nasty little ones. I'm sure you've seen them. They're encroaching upon my nest and just a total nuisance. \n\nBothering myself and my friends? The nerve! Here's my feather. Why don't you go change these nuisances into something less bothersome.", objectives = "" }
WordHunterWoW_QuestEN[78163] = { title = "Q'onzu's Qualification", description = "You seek an audience with Q'onzu but bring no offerings? \n\nOne does not just walk up and speak to the loa of Change, I'm afraid. You must first prove you are worth their time.\n\nThe friends of Q'onzu have been granted one hundred questions by the loa themself! You must prove your wit and answer each of them true.\n\nReturn to me if you answer all one hundred. Then perhaps you'll earn an audience.", objectives = "" }
WordHunterWoW_QuestEN[78170] = { title = "Nurturing Ageless Seeds", description = "The growth of these seeds is a delicate balance, requiring constant nurturing.\n\nI've found that Ageless Dewdrops, gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. \n\nIf you could collect some dewdrops and apply them to the plants, we can unlock their full potential.", objectives = "" }
WordHunterWoW_QuestEN[78171] = { title = "Blossoms of the Past", description = "With your help, these seeds have grown into magnificent plants. However, the most exciting part is yet to come.\n\nEach of these plant's blossoms contain a treasure trove of information about their history and the magic that binds them to the world tree. By studying these blossoms, we can better understand the lineage of each plant.\n\nGently collect the blossoms that have fallen and return them to me.", objectives = "" }
WordHunterWoW_QuestEN[78172] = { title = "Mysterious Seeds", description = "<These mysterious seeds might be of interest to Sylvia Whisperbloom.>", objectives = "" }
WordHunterWoW_QuestEN[78177] = { title = "To Gilneas", description = "The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised.\n\nHowever, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. \n\nJoin me in retaking Gilneas.", objectives = "" }
WordHunterWoW_QuestEN[78178] = { title = "To Gilneas", description = "{name}, we've received word of an offensive occurring soon in Gilneas. \n\nWe have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city.\n\nWe wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. \n\nLilian and I want you to join us in this operation.", objectives = "" }
WordHunterWoW_QuestEN[78180] = { title = "A Crusade of Red", description = "Calia will lead the Forsaken army in a distracting assault to the North.\n\nI'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops.\n\nThere's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?", objectives = "" }
WordHunterWoW_QuestEN[78181] = { title = "Aderic's Retort", description = "The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. \n\nToo many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner!\n\nTake out their leader, and send them a message they won't soon forget.", objectives = "" }
WordHunterWoW_QuestEN[78182] = { title = "Knee-High", description = "Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city.\n\nHead through the tunnel to meet them. Take this torch, the way is infested with vermin. \n\nI'll ready our forces to storm the gate the moment it is opened.", objectives = "" }
WordHunterWoW_QuestEN[78183] = { title = "Scarlet Blood", description = "Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. \n\nWe'll whittle their numbers down one by one.", objectives = "" }
WordHunterWoW_QuestEN[78184] = { title = "Smokepowder and Mirrors", description = "Opening the gate is all well and good, but we'll need to clear a way for our forces to advance first. Our scouts reported that the Crusade has explosives that they've stashed in the area.\n\nSurely they won't mind if we borrow some?", objectives = "" }
WordHunterWoW_QuestEN[78185] = { title = "Hounds of War", description = "I think we've had enough fun on our own, yes? \n\nThe Scarlets stationed near the city's chapel seem to be the most elite of their forces. I believe we'll find whoever is leading them there, but going alone is unnecessarily dangerous.\n\nTime to bring the true might of Gilneas and take our city back. My forces stand ready to charge!", objectives = "" }
WordHunterWoW_QuestEN[78186] = { title = "Crushing the Crusade", description = "The most powerful members of the Scarlet Crusade will be defending the nest of their leader, {name}. That's where I come in. \n\nNothing like a little distraction to take an enemy down swiftly. Just let me know where and when to strike.", objectives = "" }
WordHunterWoW_QuestEN[78187] = { title = "Artillerist Arsonist", description = "The chapel seems to be their base, and it is well defended--they've set up multiple defenses throughout the courtyard. The troops would have an easier time sieging if we could get some of them out of the way.\n\nRemember those explosives we gathered? Now is when they come in handy.", objectives = "" }
WordHunterWoW_QuestEN[78188] = { title = "Righteous Fire, Righteous Fury", description = "Only one person remains standing between us and our city. Ready yourself--this won't be an easy fight.", objectives = "" }
WordHunterWoW_QuestEN[78189] = { title = "Beginning a New Dawn", description = "Much has changed since we had to leave this city. Both the land, and my people.\n\nBear witness, {name}, to the future of Gilneas.", objectives = "" }
WordHunterWoW_QuestEN[78190] = { title = "What We Left Behind", description = "He just... handed me the kingdom.\n\nMe!\n\nThis is going to take a bit to process. But... look, {name}. I know my father's a strong man, but there are times he holds himself so rigid that I fear he'll break. I'm not about to coddle him, but if you could just follow along, make sure he's all right? Soothe a daughter's heart? \n\nA queen's heart?", objectives = "" }
WordHunterWoW_QuestEN[78206] = { title = "Emerald Bounty", description = "There are so many more species to locate and study. As you explore the Dream, you will find more seeds known as Dreamseeds. Please, nurture them to continue our studies, and enjoy the bounty they share with you!\n\nYou will find Dreamseeds all over, but many are hoarded by powerful creatures around the Dream.\n\nAdditionally, you should keep an eye out for the surge of life energy we call an Emerald Frenzy. It will be a source of many Emerald Dewdrops, which will help in nurturing Dreamseeds.", objectives = "" }
WordHunterWoW_QuestEN[78226] = { title = "A Most Intriguing Invitation", description = "We've received an invitation. Or rather, you have, {name}.\n\nIt's a request to meet with the Vizier. That name rattles even the most wealthy and powerful figures in the City of Threads.\n\nGaining this individual as an ally could seal our victory against Ansurek's horrid little shadow for good.\n\nYou're to meet them in the Burrows. Use the pheromone dispenser here in my lair to mask yourself enough to enter safely.", objectives = "" }
WordHunterWoW_QuestEN[78228] = { title = "Into a Skittering City", description = "I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however...\n\nNevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive.\n\nPerhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.", objectives = "" }
WordHunterWoW_QuestEN[78231] = { title = "Like a Spider on the Wall", description = "Inviting Alleria was a risk... but even at this moment, I feel it was worth taking. I know it was.\n\nI will speak with her on my own. In the meantime, I'd like you to venture into the city above. The pheromones Nizrek gifted you will allow access into the Umbral Bazaar. Observe the merchants, listen to the conversations, purchase their goods.\n\nThis city is as vibrant as Stormwind. And its people are as worthy of freeing from abuse as our own. Experience for yourself how similar we all are.", objectives = "" }
WordHunterWoW_QuestEN[78232] = { title = "Rewriting the Rewritten", description = "We called you here today because it is \"Ascendance Day\". Queen Ansurek has deigned declare it a day to revel in our newfound, void-infused evolution--our \"Ascendance\". Please note my satirical nuance.\n\nWhile the streets are alive with festivity and joyous citizens, the Shadecasters planted through the Bazaar will be drowning the air with Ansurek's vile propaganda.\n\nTake this invention of mine. Use it to overwrite them with more... illuminating information for the public.", objectives = "" }
WordHunterWoW_QuestEN[78233] = { title = "The Weaver's Gift", description = "A little weave-rat tells me that an intriguing series of events are playing out to the north. It seems there has been a remarkably coincidental waterfall of failures marring the military efforts there.\n\nI want to know who is responsible. Look into it for me, and see if your curiously binary eyes can pluck out any potential allies.\n\nSome of your little friends are among the escapees drawing the ire of one \"Zev'kall.\" Do go catch up. Tell them the Weaver bids them... greetings.", objectives = "" }
WordHunterWoW_QuestEN[78234] = { title = "Force Your Way", description = "Even with the general gone, it's not going to be easy getting out of here. This place is infested.\n\nI know I'm hiding it well, but I'm not exactly feeling my best. I'm not sure I'll be much help in this state.\n\nYou're going to have to clear a path for us.", objectives = "" }
WordHunterWoW_QuestEN[78236] = { title = "Scrappy Straggler", description = "If someone got left behind, we need to do something about that.\n\nI hate to say it, but these people need someone to protect them here. I have to stay.\n\nFind this straggler. And while you're at it, take a peek behind enemy lines. See if you can find anything useful.", objectives = "" }
WordHunterWoW_QuestEN[78237] = { title = "Let Fly!", description = "Hm. This Anub'azal gave the orders that led to the prisoners' escape. Zev'kall here didn't seem very pleased with that.\n\nSo how about this--you sneak into Siegehold, and make best friends with Anub'azal. Easy.\n\nI've noticed a lot of cargo being ferried over, I'm sure no one would notice if we just swapped out the contents of a particular crate.\n\nIn the meantime, I'll share our discoveries with the Weaver. I'd love to come with you, but I'd rather not tempt more Flynn stabbings today.", objectives = "" }
WordHunterWoW_QuestEN[78240] = { title = "[DNT] DEPRECATED", description = "<The little spider holds out a new note for you.>\n\nSiegehold is dangerous, but you have made it this far already.\n\nBring me the pheromones. Then we will be ready to set our sights on bigger goals.", objectives = "" }
WordHunterWoW_QuestEN[78244] = { title = "Kaheti Hospitality", description = "That stage in the distance is where Ansurek will give her Ascendance Day speech.\n\nYou, Alleria, and I shall make our way up one of the nearby towers and observe. If we are to turn her own citizens against her, then we must also gain as much first hand experience with her tactics as we can manage.\n\nI've already told Alleria as much, but we cannot make our presence known. If we do run into any trouble, the Vizier has arranged for a set of getaway fliers at the edge of the Burrows where we first met.", objectives = "" }
WordHunterWoW_QuestEN[78248] = { title = "What We Still Have", description = "I went into the city prepared--prepared to end this war even if I was ended with it.\n\nBut I am alive. As are you. As is Anduin. We have new allies and a new way forward. I realize at this moment that my vision may have been obscured by my guilt.\n\nPart of me feels those words are Anduin's, not mine. Perhaps he's rubbing off on me.\n\nLet us return to your Weaver's Lair. I wish to see yours and Anduin's efforts to save these people as well as our own through.", objectives = "" }
WordHunterWoW_QuestEN[78249] = { title = "Specific Personages", description = "Zev'kall has recently placed his own loyal lackeys in key positions around Siegehold. Killing them will force replacements, which will cause chaos and re-training.\n\nAll of which will make Zev'kall struggle. Get rid of all three.", objectives = "" }
WordHunterWoW_QuestEN[78250] = { title = "General Admission", description = "It isn't enough to inconvenience Zev'kall. He should be humiliated. I already have some information, but I need more.\n\nHe stores military logs in a room that is too tiny for me to access. See what information he's hiding. I'm sure there's potential blackmail material in there somewhere.", objectives = "" }
WordHunterWoW_QuestEN[78251] = { title = "Dalaran's Most Distressed", description = "I don't trust this big bug at all. He let me lay there ages without saying anything!\n\nBut if he wants to give us access to Siegehold, let's use it. I saw some other people dragged away into other parts of the base. I don't think they're eating them. It looks more like they're transporting them somewhere.\n\nLet's gather them up, make a prisoner convoy, and roll on out. Find me outside!", objectives = "" }
WordHunterWoW_QuestEN[78254] = { title = "Stolen Influence", description = "These logs of Zev'kall's... he is wasting numerous nerubian lives. Throwing them away like some rabid mantid.\n\nWe must act. As I said, Zev'kall doesn't produce his own pheromone marks anymore due to this 'Ascension' process. He's been forced to use mine. His alchemist is trying to concoct some for him... but once they do, what of me?\n\nTake those false pheromones and sneak them out of Siegehold. Expose Zev'kall, use them... you're creative, aren't you? Just make it messy.", objectives = "" }
WordHunterWoW_QuestEN[78255] = { title = "Just Act Casual", description = "It's time to get outta here with the prisoners and those pheromones. I've found some convincing chains, since we have such a big group. Long as everybody stays in character, our chances look good. \n\nWe've only got General Anub'azal's marker scent goop for you and I, so we'll be the drones with permission. You do all the talkin', while I mind the cart. I hope this works.\n\nLead us through the gate, {name}!", objectives = "" }
WordHunterWoW_QuestEN[78256] = { title = "The General's Consensus", description = "We got lucky here. That General Anub'azal is so interested in sabotaging Zev'kall that it's an \"enemy of our enemy is our friend\" situation for today.\n\nI feel like this is gonna be a theme: spiders tryin' to use us against each other. Ah, well.\n\nYou're gonna want to take those pheromones somewhere useful, huh? You do that. I'll take these folks safely out of harm's way.", objectives = "" }
WordHunterWoW_QuestEN[78262] = { title = "It Starts With a Stone", description = "This land holds so many secrets. And even more power!\n\nAnd you... we both know you enjoy unraveling secrets and collecting marvelous gear. And when you're ready to unlock the power of gear you find in this new land, come visit Cuzolth and me. We are experimenting and will be able to upgrade your gear by the time you come back.\n\nPlease bring me some Flightstones and a new item so I can show you how these upgrades work.", objectives = "" }
WordHunterWoW_QuestEN[78268] = { title = "[DNT] Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[78271] = { title = "Dreaming of Crests", description = "Now that you've learned the fundamentals, you can easily upgrade lower-level gear.\n\nSooner than later, though, you will find better gear that requires various types of Dreaming Crests to upgrade. Much like Flightstones, these Crests are rewarded through many different activities. Dreaming Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nGo and help with tasks, down formidable foes, find treasures, and bring me a few handfuls of Whelpling's Dreaming Crests!", objectives = "" }
WordHunterWoW_QuestEN[78274] = { title = "Quacking Down", description = "Here they go again. Do you mind scaring off those ducks again? I need to stay here and keep an eye on my golden egg.", objectives = "" }
WordHunterWoW_QuestEN[78289] = { title = "To Rambleshire", description = "There's word of troubles in the village of Rambleshire, at the base of Thunderhead Peak. \n\nCan't abide the place myself. Always wet and rumbling.\n\nBut Rooktender Lufsela thought it worth a look, however, seeing as how the birds fancy the moss that the village produces. She's still green though, and might just need a hand.", objectives = "" }
WordHunterWoW_QuestEN[78290] = { title = "Sleepy Sheep", description = "The energized moss that these flocks produce is a favorite treat for the storm rooks. But with the storm gone, the rams are lethargic, vulnerable, and no longer producing.\n\nWe may not be able to conjure a storm, but we could offer the mosswools a motivating zap. See if you can find a lodestone that will hold a charge. Then bring it here to Shraubendre so she can get it loaded up.", objectives = "" }
WordHunterWoW_QuestEN[78291] = { title = "Power Predators", description = "Thunderhead Peak normally boasts a perpetual storm from which the local mosswools draw energy. Without it, the poor dears look to be listless and near dead on their feet. That makes them easy pickings for predators.\n\nTo get moss production back on track, we'll need to get to the bottom of the missing storm. But first we need to beat back these predators before they turn the mosswools to gravel.", objectives = "" }
WordHunterWoW_QuestEN[78292] = { title = "Lost Lord of the Storm", description = "Listen well, stranger. Once a year, the great ram Durzan, Lord of the Southern Storm, crosses the isle to meet his brother Belzt on Thunderhead Peak. The clash of their horns heralds the storm and brings prosperity for another year.\n\nBut something is wrong. Durzan has not come and the skies have cleared. The Stormrider may not believe, but I sense you have seen wilder things.\n\nAsk around if you still have doubts. Just please help us find Durzan.", objectives = "" }
WordHunterWoW_QuestEN[78293] = { title = "Their Moss, Our Gain", description = "You say nerubians had him? Not sure what they wanted with old Durzan, but he looks weakened by the ordeal. We can't have that if he's to challenge his brother Belzt on the mountain.\n\nThe moss harvested from our flocks gives the storm rooks a kick, so Durzan might benefit from it as well. Collect a bushel's worth and make an offering.\n\nAnd if the mosswools get ornery, be sure to put them in their place.", objectives = "" }
WordHunterWoW_QuestEN[78294] = { title = "Thunderhead Butt", description = "Durzan looks hale and hearty again. That moss packs a real punch.\n\nI have a sense that he's ready to go. I just wish we had more time. I have so many questions. But the greatest of those questions will be answered when he reaches the peak.\n\nWe shouldn't send him up there alone. But I think he trusts you to take him.", objectives = "" }
WordHunterWoW_QuestEN[78301] = { title = "Scalawag Slither", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78302] = { title = "Scalawag Slither - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78303] = { title = "Scalawag Slither - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78319] = { title = "The Superbloom", description = "Amirdrassil is growing and needs nourishment. Dear old Sprucecrown has a ritual to bloom life around the tree, but our enemies have taken note. We need all the help we can get.\n\nDuring the ritual, Sprucecrown will draw on the magic of the Dream to grow Dreamfruit. Consuming these will grant you amazing powers. Only a few of these powerful and delicious fruits can appear. Keep an eye out for them!\n\nPray lend a hand, hero, and the dream will reward you aplenty.", objectives = "" }
WordHunterWoW_QuestEN[78325] = { title = "Daggercap Dart", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78326] = { title = "Daggercap Dart - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78327] = { title = "Daggercap Dart - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78328] = { title = "Take a Look Around", description = "The Gala of Gifts is here to showcase the many wonderful artisans carefully crafting gifts just for you and your loved ones.\n\nYou should see what they have to offer, and talk to the other attendees. Who knows, you might just find the perfect gift for someone you care about!", objectives = "" }
WordHunterWoW_QuestEN[78329] = { title = "Love is in the Air", description = "Smell these roses! My partner got them for me at the Gala of Gifts.\n\nInterested in seeing things yourself? Head to the gates of Stormwind. There are gifts, and food, and you should taste the chocolate, it's delicious!", objectives = "" }
WordHunterWoW_QuestEN[78332] = { title = "I Smell Trouble", description = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it?\n\nWell, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away!\n\nAre you in? I could use a good partner to solve this.", objectives = "" }
WordHunterWoW_QuestEN[78334] = { title = "Blackriver Burble", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78335] = { title = "Blackriver Burble - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78336] = { title = "Blackriver Burble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78337] = { title = "An Unwelcome Gift", description = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent!\n\nBut let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", objectives = "" }
WordHunterWoW_QuestEN[78346] = { title = "Zul'Drak Zephyr", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78347] = { title = "Zul'Drak Zephyr - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78348] = { title = "Friends in Low Places", description = "When we crashed, the nerubians were upon us in an instant. We would have lost nearly everyone we brought with us, had someone not intervened.\n\nI do not know who--or what--stepped in on our behalf. But if there is even a shred of hope that we have allies in this place then we must seize upon it and refuse to let go.", objectives = "" }
WordHunterWoW_QuestEN[78349] = { title = "Zul'Drak Zephyr - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78350] = { title = "Heroes Never Die", description = "Damn it all! We were too hasty, and now my people are paying the price.\n\nWe were fools to think the nerubians wouldn't be prepared for an incursion. Arathi soldiers are made of stern stuff, but even they will struggle to walk off an airship crash.\n\nI will keep everyone here safe. Please, go into the field and rescue as many people as you can.", objectives = "" }
WordHunterWoW_QuestEN[78351] = { title = "[DNT] DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[78352] = { title = "For Naught, So Vial", description = "Truthfully, I don't care what the nerubians are plotting. They are not the first upstart people seeking power, and they certainly won't be the last. The problem is how they're going about it. I fear that tampering with this Black Blood will threaten far more than the delicate ecosystems of Khaz Algar.\n\nWe must make sure that they never return to this pit again. Their equipment is still strewn throughout the pit. Destroy as much of it as you can manage.", objectives = "" }
WordHunterWoW_QuestEN[78353] = { title = "Fear the Old Blood", description = "This is not exactly the place for a long talk, so I will be brief.\n\nThese roots you see are part of something much greater than you know, and it is my job to protect them. \n\nIf it isn't obvious to you already, this place is teeming with writhing Black Blood. If we do not act, it will spread deeper and further still.\n\nYou want allies? Fine. Help me cleanse this place and protect these roots, and I will at least hear you out.", objectives = "" }
WordHunterWoW_QuestEN[78354] = { title = "A Guiding Thread", description = "<The words on the parchment appear burned, not written. A venomous tang singes your nose.>\n\nBlind and alone, you stumble in the dark. I offer you a thread to cling to.\n\nFollow it, should you wish to find your allies.", objectives = "" }
WordHunterWoW_QuestEN[78355] = { title = "Essence of a Broken Dream", description = "<You feel an echo of ancient sorrow, fear, and rage as you gaze into the swirling depths of this strange sphere. Maybe Merithra will know more about it?>", objectives = "" }
WordHunterWoW_QuestEN[78356] = { title = "DO NOT USE", description = "", objectives = "" }
WordHunterWoW_QuestEN[78357] = { title = "Dreamy Drakewatching", description = "", objectives = "" }
WordHunterWoW_QuestEN[78358] = { title = "Drake's Crests", description = "", objectives = "" }
WordHunterWoW_QuestEN[78363] = { title = "The Tabard of Your Dreams", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we are immensely grateful for all you've done to help us. Please meet me at Central Encampment so we can properly reward you for your efforts!\n\n- Amrymn", objectives = "" }
WordHunterWoW_QuestEN[78364] = { title = "Drake's Crests", description = "", objectives = "" }
WordHunterWoW_QuestEN[78369] = { title = "Crushing the Crown", description = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver.\n\n<Snagglebolt points to the unmarked box.>\n\nBombs. I got bombs.\n\nPlaytime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", objectives = "" }
WordHunterWoW_QuestEN[78372] = { title = "Drake's Crests", description = "", objectives = "" }
WordHunterWoW_QuestEN[78373] = { title = "The Dream Thanks You", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, your contributions to the dream are immeasurable. Please meet me at the Central Encampment, we have a reward we're excited to give you.\n\n- Amrymn", objectives = "" }
WordHunterWoW_QuestEN[78374] = { title = "Flightstones", description = "", objectives = "" }
WordHunterWoW_QuestEN[78377] = { title = "Counting Drakes", description = "", objectives = "" }
WordHunterWoW_QuestEN[78379] = { title = "The Stench of Revenge", description = "We're never gonna see an end to this unless we take on the boss himself.\n\nLook, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Stormwind if we let him finish his research.\n\nYou go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", objectives = "" }
WordHunterWoW_QuestEN[78380] = { title = "I Dream of Drakes", description = "", objectives = "" }
WordHunterWoW_QuestEN[78381] = { title = "Dreams Unified", description = "Another incredible find, {name}!\n\nThis half of a Spark of Dreams could prove useful in your crafting endeavors if you could unite it with a sister piece.\n\nSet out in search of another Splintered Spark of Dreams and combine them.", objectives = "" }
WordHunterWoW_QuestEN[78383] = { title = "Strategic Edge", description = "To add insult to injury, they disarmed me. I'm not leaving without those blades!\n\nWhile we're looking, keep an eye out for any evidence of what's going on here. Anything that could give us an advantage against the nerubians.\n\nSomething strange happened that provided us the opening to escape. I have a feeling that could be something we can exploit.", objectives = "" }
WordHunterWoW_QuestEN[78384] = { title = "Chasing the Light", description = "Anduin survived that swarm. I do not doubt that for a moment. Even so, the nerubians are everywhere and he is just one man.\n\nWherever he goes, wherever he is taken, I will find him. Find me any sign that he yet lives. That is all I need to follow him to Azeroth's end.", objectives = "" }
WordHunterWoW_QuestEN[78385] = { title = "Small Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", objectives = "" }
WordHunterWoW_QuestEN[78386] = { title = "Emerald Reawakening", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we found a way to bring creatures into the dream. Speak to me if you'd like to know more!\n\n- Elianna", objectives = "" }
WordHunterWoW_QuestEN[78387] = { title = "Plump Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", objectives = "" }
WordHunterWoW_QuestEN[78388] = { title = "Gigantic Dreamseeds", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds.\n\n- [NPC]", objectives = "" }
WordHunterWoW_QuestEN[78389] = { title = "The Makers' Marathon", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78390] = { title = "The Makers' Marathon - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78391] = { title = "The Makers' Marathon - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78392] = { title = "The Tangled Web", description = "Make no mistake--I have no intention of sending you off to skitter about in the dark like a freshly-hatched beetle. It wouldn't do to have my little morsel snatched up by a starving cave borer.\n\nYou must educate yourself, my dear. Your allies have found themselves ensconced in a torrid tapestry. Only by familiarizing yourself with its erstwhile architects can you hope to reclaim them.\n\nLuckily for you, I have made some of my personal resources available to you.", objectives = "" }
WordHunterWoW_QuestEN[78393] = { title = "A Seeming Respite", description = "You have endured quite the evening since your ill-fated little ship ride, haven't you? Worry not, little morsel. You will find that my friends here are most accommodating, even to someone with your predilections--as strange as they may be.\n\nPlease, take a moment to explore. Avail yourself of my many amenities. With luck, you will find some sorely-needed rest.\n\n...Oh, but do take care not to move about too quickly. Sudden movements, I'm sure you understand.", objectives = "" }
WordHunterWoW_QuestEN[78398] = { title = "A Dash of Minerals...", description = "I think we have a chance with this one, {name}. But we'll need to begin revitalizing the soil if we want to see this plant flourish.\n\nHead to the Eye of Ysera and harvest fish bones from the Fathomless Lurkers in the depths of the water. They're rich in minerals and degrade easily. It won't replenish the soil on its own, but it's a great start.", objectives = "" }
WordHunterWoW_QuestEN[78421] = { title = "The Power of Dreams", description = "It seems that the fabric of the Emerald Dream itself is rejecting the invaders, leaving behind shadows of their dreams in the form of these Essences. So close to Amirdrassil, even your own actions are leaving behind ephemeral echoes of power. \n\nWith enough time, perhaps we can use these echoes to awaken their strength and turn it against Fyrakk himself. Defeat the invaders wherever you find them and return to me when you have gathered enough of the Dream's power.", objectives = "" }
WordHunterWoW_QuestEN[78427] = { title = "Great Crates!", description = "The assault on the Dream grows ever stronger.\n\nWe are in desperate need of trade goods and supplies to support the defense effort. Even just one crate could make the difference on the front line.\n\nVashonir can assist you with packing the shipments. Then bring the shipment to me.\n\nElune watch over you, defender of the Dream.", objectives = "" }
WordHunterWoW_QuestEN[78428] = { title = "Crate of the Art", description = "Our stockpiles have taken a grave hit, {name}. \n\nWe need to replenish our reserves as soon as possible, lest the enemy gain the upper hand. We will need far more supplies than we previously envisioned.\n\nOnce again, Vashonir can assist you with packing the shipments. Please return to me with five crates of goods.\n\nElune, watch over you.", objectives = "" }
WordHunterWoW_QuestEN[78429] = { title = "The Power of Dreams, Awoken", description = "Are you ready, {name}? I will fuse the essences of their fiery dreams together for you. Focus the Echoed Ephemera you have collected to awaken the latent power within. Show Fyrakk that even he should fear the power of the Dream!", objectives = "" }
WordHunterWoW_QuestEN[78430] = { title = "Mean Green Infusion Machine", description = "Pleased to meet you. I am Elianna, a Dream Researcher.\n\nA strange phenomenon has recently been detected in the Dream. Fragments of dream magic are being left behind by the creatures here.\n\nI'm curious to know the effects of such magic in concentrated doses. But I need someone to extract it for me.\n\nThere are some problematic lashers and podlings to the south of here. \n\nSeveral of them should be enough for a lesser infusion.", objectives = "" }
WordHunterWoW_QuestEN[78431] = { title = "Green Dream Team", description = "Most interesting! \n\nI was able to concentrate the Dream energy you brought me. \n\nWith this, we can perform the infusion!\n\nGo ahead, I'll watch.", objectives = "" }
WordHunterWoW_QuestEN[78441] = { title = "Crystalsong Crisis", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78442] = { title = "Crystalsong Crisis - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78443] = { title = "Crystalsong Crisis - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78444] = { title = "A Worthy Ally: Dream Wardens", description = "So much change to that which should be unchanging... \n\nRarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. \n\nChampion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream.\n\nI have no doubt the Dream will share its plenty with you in return.", objectives = "" }
WordHunterWoW_QuestEN[78446] = { title = "Aiding the Accord: Superbloom", description = "As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. \n\nThe Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! \n\nPlease lend your aid to Sprucecrown on his journey.", objectives = "" }
WordHunterWoW_QuestEN[78447] = { title = "Aiding the Accord: Emerald Bounty", description = "The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. \n\nIn exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you.\n\nGo forth and help life blossom in the Emerald Dream!", objectives = "" }
WordHunterWoW_QuestEN[78454] = { title = "Dragonblight Dragon Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78455] = { title = "Dragonblight Dragon Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78456] = { title = "Dragonblight Dragon Flight - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78457] = { title = "Stones of Dornogal", description = "I am Merrix, Councilward of Dornogal.\n\nI appreciate your aid--especially in light of the fraught nature of your arrival. You must forgive Stormward Baelgrim. Being suspicious is part of his directive. \n\nA formal discussion of our situation is warranted. If you wish to strike back at the nerubians, as we do, meet us at the Foundation Hall. Baelgrim and I need to review the data so far.\n\nIn the meantime, you are my guest. Take my ring. It will allow you to access Dornogal's amenities.", objectives = "" }
WordHunterWoW_QuestEN[78459] = { title = "State of the Union", description = "I hate to admit it, but we have been caught unprepared by the nerubians.\n\nOur processes focused on sustaining Dornogal and our declining population. \n\nStormward Baelgrim's stalwart pride has kept him and the Stormriders capable fighters, but they are already stretched thin, and they are not builders.\n\nThe Coreway's damage surpasses our ability to fix it.\n\nBut... that was not always so. I suppose if you wish to understand, you must learn more about us.", objectives = "" }
WordHunterWoW_QuestEN[78460] = { title = "Hypocenter", description = "I have failed my people. The Coreway is impassible. Dornogal's lifeline to the Ringing Deeps has been severed as has the path beyond.\n\nThe nerubians will get their comeuppance. It is my edict as it is my will.\n\nI will ascertain if the Councilward yet functions and bring him to the Archive. Speaker Brinthe should be there, titans willing.\n\nBut Oathsworn citizens are still in peril. If you wish to ally with us, clear the debris here and help our survivors. \n\nI will meet you at the Archive.", objectives = "" }
WordHunterWoW_QuestEN[78461] = { title = "The Fourth Seat", description = "With me da' and Anduin weakened and Alleria nowhere to be found, it's up to us, {name}, to clear the way for Thrall an' Jaina's army if we hope tae strike back at the nerubians an' Xal'atath.\n\nBut we cannae get to the nerubians without the Coreway. An' we cannae repair the Coreway without the earthen's help.\n\nIf Merrix thinks this Adelgonn an' her \"Unbound\" are the only ones that can fix the Coreway, then we need tae find her.\n\nTime tae sharpen me smile an' put on me diplomat hat. Are ye with me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[78462] = { title = "Echoes of Compassion", description = "The last thing I expected today was to see Baelgrim--much less receive his help. But I guess since the Coreway was damaged, he has no choice.  I... do not know how to compute this. It is only logical to accept it.\n\n<Adelgonn begins crushing the fungarian flesh roughly in her stone hands. It becomes a masticated pulp disturbingly quickly.>\n\nHere. Mix this with mud and apply it to the injured.", objectives = "" }
WordHunterWoW_QuestEN[78463] = { title = "Building Blocks", description = "The quarry is overrun with fungarians, all of the mining tunnels are collapsed, and we do not have time to clear them out and rebuild!\n\nHowever, I did spy a good amount of ore on the ground on the way here. It would be a start at repairing the Coreway but...\n\n<Baelgrim sighs and grimly looks at the injured Unbound earthen.>\n\nI am needed here. With Adelgonn's people. My people. Will you gather the ore in my stead?", objectives = "" }
WordHunterWoW_QuestEN[78464] = { title = "Delve into the Earth", description = "The nerubian attack, your meteoric fall...\n\nAnd now Baelgrim is here?\n\nBaelgrim needs more hands for his Coreway, but I couldn't help even if I wanted to. My people are dying as we speak. Some were abducted by the nerubians during the attack.\n\nYou're not the first outlander I've met. A small fellow, like Moira, arrived here earlier and wasted no time following the nerubians. He took the path west to a nearby cave.\n\nI would be in your debt if you found my people.", objectives = "" }
WordHunterWoW_QuestEN[78465] = { title = "Golgrin's Reach", description = "Now that we have the opals, we can meet Brinthe in Golgrin's Reach.\n\nShe said there's a project she's workin' on there she wants me tae help with.\n\nI wonder what it is?", objectives = "" }
WordHunterWoW_QuestEN[78467] = { title = "Charge for a Charge", description = "I am pleased Dagran has brought you here. I need help with a dangerous task.\n\nI used Dagran's opals to repair the titan console we recently recovered from this site.\n\nThe Oathsworn have long wanted to learn more about the titans and restore records unreachable in the Archive--or from before its construction.\n\nThis console may hold some answers if we can bring it back online.\n\nTake this device I have made. It will lead you to titan power cells we can use to power it on now that it is restored.", objectives = "" }
WordHunterWoW_QuestEN[78468] = { title = "The Archive", description = "The memory gem you recovered is what its name suggests. It contains an earthen's memories, directives, and a hard coding of our Edicts.\n\nThis building, the Archive, is the nexus of our civilization. Here, memories are cycled, catalogued, and stored at the end of an earthen's scheduled rotation.\n\nWith the codex I have invented, we can access one or two memories from a memory gem. Take it, and read the memory gem you found.", objectives = "" }
WordHunterWoW_QuestEN[78469] = { title = "Prairie Fever", description = "I was supposed to see Kodun earlier, but I'm as petrified as unliving stone. The attack on the village was... paralyzing.\n\n<Hreka takes a deep breath and focuses on the shape of another jar.> \n\nCould you do me a favor and deliver those jars to Kodun? He's a stone's throw away in the village pottery shop. I must finish this piece before the clay dries.", objectives = "" }
WordHunterWoW_QuestEN[78470] = { title = "The Proscenium", description = "The nerubians are attackin' the earthen again. We must follow that swarm!\n\nI fear we are outnumbered, but if the earthen can come together and stand with us...\n\nWe may just have a chance.", objectives = "" }
WordHunterWoW_QuestEN[78471] = { title = "Convergence", description = "We know the nerubians are in league with Xal'atath. An' we have a fair idea why they attacked us--and Dalaran.\n\nThey seem bent on destroying the earthen--even kickin' 'em when they're down.\n\nBut why? Is it because the Coreway is the key an' destroyin' it was nae enough? Maybe what we're doin' here, repairin' the Coreway, is just what they dunnae want us to do.\n\nWe should go back to Dornogal an try to piece this together.", objectives = "" }
WordHunterWoW_QuestEN[78499] = { title = "Citadel Sortie", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78500] = { title = "Citadel Sortie - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78501] = { title = "Citadel Sortie - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78504] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[78529] = { title = "Violent Impact", description = "<Your vision swims as you slowly regain consciousness. Distant shouts and screams echo in your ringing ears.\n\nThe last thing you remember is Dalaran, the great, floating city of magic, plummeting to the earth--then nothing but darkness.\n\nMixed in with sounds of shouting and battle, you hear a strange, insectoid chittering.\n\nThe nerubians were waiting for you.\n\nYou must rejoin the fight, but first you need to free yourself from the crushing weight of the rubble piled atop you.>", objectives = "" }
WordHunterWoW_QuestEN[78530] = { title = "Slay the Saboteurs", description = "The nerubians are everywhere, {name}.\n\nThere are too many for all of them to be solely crash survivors. I've seen others burrowing up from the ground. \n\nThis Queensguard Zirix was laying in wait here to overwhelm us.\n\nLet them know we are not easy prey. Cut them down!", objectives = "" }
WordHunterWoW_QuestEN[78531] = { title = "Urgent Recovery", description = "We survived mostly unharmed. Not everyone was so lucky.\n\nMany who were in Dalaran when it went down are unaccounted for. They will need our help.\n\nSearch the battlefield for survivors. Help them in any way you can.\n\nWe need everyone up and fighting!", objectives = "" }
WordHunterWoW_QuestEN[78532] = { title = "Erratic Artifacts", description = "Dalaran housed many precious and powerful relics. Many of them were damaged in the crash and are now malfunctioning.\n\nThey must be destroyed!\n\nTake this scroll. I have stored a shattering spell within it. Read the words aloud and its magic will be unleashed.\n\nReport what you have done to Jaina when you are through. She will understand.", objectives = "" }
WordHunterWoW_QuestEN[78533] = { title = "Secure the Beach", description = "Queensguard Zirix emerged from the ground and surprised Magni.\n\nHe's near the farthest edge of the wreckage fighting off his swarm.\n\nMoira and I were trying to help, but we couldn't draw them away.\n\nCome with me. Magni needs our help!", objectives = "" }
WordHunterWoW_QuestEN[78534] = { title = "To Dornogal", description = "You have brought death and destruction to our shores the likes of which has not been seen in millennia.\n\nBut you have nerubian blood on your hands and a thraegar at your side. This is enough to earn my trust--for now.\n\nMy Stormriders and I must return to our capital, Dornogal, and investigate what is likely an ongoing attack there. Fly with us. Our slipstream will allow you to soar through the skies with ease.\n\nI will send other Stormriders to collect your allies once it is safe for them to land.", objectives = "" }
WordHunterWoW_QuestEN[78535] = { title = "They Come from Below", description = "I do not yet know why you have come here, outlander. But you seem... efficient in killing nerubians.\n\nAs are we, the Stormriders, vanguards of this isle.\n\nThe nerubians are an ancient enemy. I would not be surprised if this Zirix knows and fears me, the Stormward.\n\nEven so, we could use your skill to help us protect Dornogal.\n\nI have a stormrook for you to ride. Mount up and help us rid our city of these insects!", objectives = "" }
WordHunterWoW_QuestEN[78536] = { title = "Impossible Odds", description = "By the titans... The Coreway appears completely destroyed! It will take years, perhaps centuries, to remove the rubble and repair the damage the nerubians did to its inner structure, much less traverse to the world's core.\n\nMore than that with the Stonebound gone...\n\nI must take a moment to decide what to do.\n\nYour friends have safely arrived. Speak to them, and stay out of my way. \n\nIf we need you, I will let you know.", objectives = "" }
WordHunterWoW_QuestEN[78538] = { title = "Group Effort", description = "The Unbound have arrived with the equipment and resources needed to begin repairing the Coreway.\n\nThis is a momentous occasion. One for the Archive! I would not say this to Adelgonn, but I see the titans' hands in it...\n\nAnd now it is time for me to exercise my directive! I have devised a plan for how to organize our workers most efficiently--and have also allocated supplies to welcome them.\n\nTake these orders to Adelgonn's workers so that they can begin in earnest. We will meet you there shortly.", objectives = "" }
WordHunterWoW_QuestEN[78539] = { title = "Lasting Repairs", description = "With my Stormriders... inactive, Dornogal is undefended, save a handful of lay peacekeepers. If the nerubians attack us here again, Dornogal will fall--and all of us with it.\n\nIt is imperative we draw them away from the city and take out their commander. \n\nWe can and will make our own web and capture Zirix in it.\n\nI have a plan.", objectives = "" }
WordHunterWoW_QuestEN[78540] = { title = "To the Meadery", description = "Your archer friend is right. We must eliminate Zirix and his forces if the Coreway is to remain safe.\n\nLet us head to the Cinderbrew Meadery at once.", objectives = "" }
WordHunterWoW_QuestEN[78541] = { title = "Lay the Trap", description = "With all these cinderbrew kegs here, this meadery would burn hotter than the Forgegrounds if they were all ignited.\n\nI surmise that's why Wenbrandt's kegs are made out of stout and strong ironwood--they do not break or catch fire easily. \n\nLuckily, we can start a reaction from the inside if we lead fuses into each of them.\n\nThose ropes the workers left around should work in a pinch.", objectives = "" }
WordHunterWoW_QuestEN[78542] = { title = "Evacuation Area", description = "Look, you can blow up my life's work if it is our only choice, but I will not put my workers in danger.\n\nThis was the path we all chose, but I won't have them sacrifice themselves to fire or nerubians for it. Tell them that I said they need to get out of here immediately. \n\nAnd if a single one of them gets so much as chipped, the Council will have a lot to answer for!", objectives = "" }
WordHunterWoW_QuestEN[78543] = { title = "Poking the Spider Nest", description = "The meadery is evacuated and the explosives are primed. It is time to bait the nerubians into our trap.\n\nYour compatriot is by the nerubian burrow north of here. She told me her directive is to keep watch over it in case the nerubians make a move before we are ready.\n\nSo far they have not made a move and may now need... coaxing. Take a keg of cinderbrew to the burrow. Tossing it in should stir their \"nest.\"\n\nRendezvous with us back at the Meadyard--quickly--after.", objectives = "" }
WordHunterWoW_QuestEN[78544] = { title = "Bring the Thunder", description = "The nerubians will strike out in anger and pride--which is exactly what we want.\n\nThey will swarm the meadery soon, seeking to punish us for attacking their burrow. We will hold them here on the ground while you take to the skies. When Zirix appears to command his army, we will light the fuses.\n\nWenbrandt scrounged together some supplies we can use to corral the nerubians. Set them up quickly, and then we will get you on a stormrook. Go!", objectives = "" }
WordHunterWoW_QuestEN[78545] = { title = "Return to the Coreway", description = "We dealt a heavy blow to the nerubians. But Baelgrim...\n\n<Adelgonn pauses to compose herself.>\n\nHe was infuriatingly rigid and we argued ceaselessly, but in the end... he was a defender of our people--all of them.\n\nBaelgrim sacrificed himself to vouchsafe the Isle of Dorn from the nerubians. Everyone needs to know that--and we can't let the nerubians force our hand like that again.\n\nGo back to Merrix in Dornogal. Tell him we will come soon. We just... need a moment here.", objectives = "" }
WordHunterWoW_QuestEN[78546] = { title = "Recompense", description = "We heard the echo of the explosion from here.\n\nI presume you have found victory, but your solitary arrival suggests not all is well.\n\nWhat happened?", objectives = "" }
WordHunterWoW_QuestEN[78555] = { title = "Underground and Overwhelmed", description = "I've been away too long. The Machine Speakers are clearly not faring well here. Does the High Speaker know about this?\n\nNerubian sabotage and gross negligence are a devastating combination. We need to get Ironhaul Station up and running as soon as possible. It's a vital link between the Ringing Deeps and the city up above.\n\nPlease, {name}, help our injured workers, collect any salvageable cargo, and restore safety to Ironhaul Station.", objectives = "" }
WordHunterWoW_QuestEN[78557] = { title = "Getting Off Track", description = "Speaker Brinthe acknowledged. Outlanders, there is work to do.\n\nOne of our larger mine carts has derailed. It's blocking the station's main junction. \n\nMy workers' productivity is impaired, and their functioning is suboptimal. The titans put us here to work, but my workers aren't all working. Could you go and get us back on track?\n\nBe careful. I can see you're made of flesh and bone. I don't want you to be crushed.", objectives = "" }
WordHunterWoW_QuestEN[78558] = { title = "Sholazar Spree", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78559] = { title = "Sholazar Spree - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78560] = { title = "Sholazar Spree - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78562] = { title = "Discarded and Broken", description = "You there! You're here to help, aren't you?\n\nThe humming melody of the machines is changing, and I... I admit I am not ready. For so many years I served faithfully, and then...\n\nWell the important thing is that I'm ready to get to work again. But you see, my tools have all been broken and scattered about. \n\nIf you could keep an eye out for them and bring them back to me, I would be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[78563] = { title = "The Weight of a World", description = "My tools didn't randomly end up where you found them. They were placed there. By me.\n\nI had reached a point so low that I saw no alternative. The machines, the great work of my people, were never going to sing again. So why should I bother to keep them repaired?\n\nBut now I see, and now, I understand!\n\nThe last tool I need, I dropped it into the water, and it was eaten by a giant creature. I think that one might need a bit more force to return it to me.", objectives = "" }
WordHunterWoW_QuestEN[78564] = { title = "Reforged Purpose", description = "That's all of them! Now, it's time to do my duty and recast these tools. Reforge them, and myself, into what I was meant to be: a proud machinist of the Ringing Deeps.", objectives = "" }
WordHunterWoW_QuestEN[78565] = { title = "Getaway to Scenic Grizzly Hills!", description = "Today's special is a magical getaway to the majestic forests of Northrend!\n\nSay, you're one of those adventurers, right? Listen, I need a favor.\n\nCould you pick me a few flowers from Grizzly Hills? I've got my hands full here, but there's someone I'd really like to give a bouquet to.", objectives = "" }
WordHunterWoW_QuestEN[78570] = { title = "Frayed Legacy", description = "Keep true, {race}t.\n\nWe of the Woldguard uphold an ancient promise to Freya to tend to these lands. Our edict is older than those wielded by the demagogues in Dornogal. Older than Dornogal itself.\n\nHowever, not all lands have been tended equally. The leader of our order was to care for the basin nearby but we've not heard from them in many cycles.\n\nI have sent a novice to investigate. Aid them and my order will be in your favor.", objectives = "" }
WordHunterWoW_QuestEN[78571] = { title = "Mycomayhem", description = "Freydrin was the leader of my order. I was sent here to assist them. I was too late.\n\nThere is a darkness that haunts these woods, {race}s.\n\nThese woods were Freydrin's home. It was her charge to tend to them, so given by the Keeper herself. And now she is gone and her woods run amok.\n\nBring me the spores of these mayhemic menaces. Perhaps there is a way to cleanse this land yet.", objectives = "" }
WordHunterWoW_QuestEN[78572] = { title = "Wold Memories", description = "Freydrin must have had some way of fending off the fungarians.\n\nAlthough there are few left in the countryside who still follow the Edicts, Freydrin was long a true believer. She would never have allowed these woods to reach this state while she held faith.\n\nWe should take a look at her home in the woods. Perhaps there is something that may prove useful inside.", objectives = "" }
WordHunterWoW_QuestEN[78573] = { title = "Keeper's Aid", description = "Magical staff? Wards? What were you doing, Freydrin?\n\n<Igris ruminates briefly, her brow crinkling and eyes aglow. After a moment, she turns to you with a smile carved into her face.>\n\nI've got it! \n\nThe life energy in this staff should overcome any mycotic corruptions in the wildlife here. Then you return them to the natural cycle and the land will heal on its own in time.\n\nAnd if you see any wards, take them down. Take her memory gem just in case. It may yield more information yet.", objectives = "" }
WordHunterWoW_QuestEN[78574] = { title = "Boss of the Bosk", description = "There is one final thing I must ask of you.\n\nThere is a great monster that roams these woods. I am certain you've sensed it. It must be felled.\n\nRotbark was Freydrin's final means to control this basin, but even this was too great for any individual earthen. Ours is not to control, but to tend to its needs.\n\nUse the staff once more and bring an end to Rotbark's reign.", objectives = "" }
WordHunterWoW_QuestEN[78589] = { title = "Invasive Cuisine", description = "<This rarely seen plant may be of use to Chef Dinaire.>", objectives = "" }
WordHunterWoW_QuestEN[78591] = { title = "Getaway to Scenic Nagrand!", description = "Today's special is a magical getaway to the great plains of Nagrand!\n\nIf you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera.\n\nMy friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.", objectives = "" }
WordHunterWoW_QuestEN[78594] = { title = "Getaway to Scenic Feralas!", description = "Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala.\n\nCould you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.", objectives = "" }
WordHunterWoW_QuestEN[78595] = { title = "Dream Infused", description = "<Melsysra drops a slightly damp note into your hand.>\n\n{name}, your deeds have helped garner enough strength for a dream infusion! Meet me at the Central Encampment so I can get it to you.\n\n- Elianna", objectives = "" }
WordHunterWoW_QuestEN[78596] = { title = "Summons to Lord Greymane", description = "Greetings, \n\nLord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas.\n\nThat is all I am able to say.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[78597] = { title = "Clandestine Movements", description = "{name},\n\nLilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas.\n\nThey will brief you in full when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[78598] = { title = "Dream Infusion", description = "", objectives = "" }
WordHunterWoW_QuestEN[78600] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "" }
WordHunterWoW_QuestEN[78601] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "" }
WordHunterWoW_QuestEN[78602] = { title = "Amirdrassil, the Dream's Hope: Up in Smoke", description = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", objectives = "" }
WordHunterWoW_QuestEN[78607] = { title = "To Mereldar", description = "We must get to Mereldar and let General Steelstrike know what the Order of Night tried here.\n\nThank the Sacred Flame we stopped them before they could do any worse.", objectives = "" }
WordHunterWoW_QuestEN[78608] = { title = "Geothermal Jaunt", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78609] = { title = "Geothermal Jaunt - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78610] = { title = "Geothermal Jaunt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[78613] = { title = "The Bastion of Hallowfall", description = "I have to admit, I did not think that the first visitors we'd have in Mereldar would have been outsiders. I thought the Empire... Well, nevermind.\n\nYou have been more than helpful to my people, and that deserves recognition. Mereldar is the bastion of the Arathi in Hallowfall. Take some time, rest.", objectives = "" }
WordHunterWoW_QuestEN[78614] = { title = "Mereldar's Light", description = "I still need more time with Alleria to learn about Xal'atath. What I have learned is very worrying.\n\nFaerin sent word that she was going to the orphanage, and asked you to meet her there. \n\nShe often entertains the children while she is in Mereldar, I don't doubt she would appreciate you doing the same.", objectives = "" }
WordHunterWoW_QuestEN[78615] = { title = "The Bell Tolls", description = "Those bells mean Mereldar is under attack! \n\nLet's get to the gates and find out what is going on.", objectives = "" }
WordHunterWoW_QuestEN[78620] = { title = "Crossroads of Twilight", description = "We need to take the Veneration Grounds back from the kobyss. \n\nPush them back and pave a bloody path through them.\n\nWe need to stop whatever is happening at the Eternal Flame! If they manage to corrupt it like they did at the tower... I don't even want to imagine what will happen.", objectives = "" }
WordHunterWoW_QuestEN[78621] = { title = "The Shadow Rising", description = "I can sense three beacons of void ahead, all funneling their power into one massive font of darkness.\n\nYou will need to kill them. With them dead, I can bring down the shield.", objectives = "" }
WordHunterWoW_QuestEN[78624] = { title = "A Candle in the Dark", description = "Beledar has turned to Shadow, we must retreat back to Mereldar!\n\n<Vaelisia looks towards Aelric Leid.>\n\nI-- No. We need to destroy Aelric first.\n\nTake him down, then we retreat.", objectives = "" }
WordHunterWoW_QuestEN[78626] = { title = "Spar Day", description = "Your skills in combat are impressive, {name}. \n\nWe are rotating our next round of reserves into active duty, and they need to sharpen their skills. \n\nWhile Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.", objectives = "" }
WordHunterWoW_QuestEN[78627] = { title = "The Final Front", description = "Just before the kobyss attacked, we received word of a disturbance near Livia's Patience. Now we know the cause.\n\nWe... Light... We can't survive fighting on two fronts, {name}. We have to stop this, now.", objectives = "" }
WordHunterWoW_QuestEN[78628] = { title = "Trapdoor Sprung", description = "We need time to get the Reckoning ready. Take your friends and hold back the nerubians for as long as you can.\n\nThey deserve nothing but death for what they have done to our people.", objectives = "" }
WordHunterWoW_QuestEN[78629] = { title = "Running on Reserves", description = "We have to try to save any of our people left alive in Livia's Patience. \n\nEvery Arathi is or was a member of the military. If you can help them, they'll be able to help themselves.", objectives = "" }
WordHunterWoW_QuestEN[78630] = { title = "The Rise of the Reckoning", description = "The Reckoning is ready!\n\nLet's make these spiders pay. Blood for blood.", objectives = "" }
WordHunterWoW_QuestEN[78631] = { title = "Speaking to the Speakers", description = "I've heard about a problem nearby, and I think I know what's wrong.\n\nWe used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in.\n\nWe haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it.\n\nSomeone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.", objectives = "" }
WordHunterWoW_QuestEN[78634] = { title = "Leave No Stone Behind", description = "Many earthen fell when the kobolds took this mine.\n\nWorse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen?\n\nWe will not fail them again, {name}. Gather the identification plaques of those we lost, so we may commemorate them properly.", objectives = "" }
WordHunterWoW_QuestEN[78635] = { title = "Death and Waxes", description = "Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom!\n\nWe steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead!\n\nAlso means we not have to wait out here in dark until get eaten. Hurry!", objectives = "" }
WordHunterWoW_QuestEN[78636] = { title = "Retaking the Mines", description = "Now that we have the keys, it is time to take the fight to the Candle King.\n\nGet that gate open. Once we're inside, we'll move on to the next step.", objectives = "" }
WordHunterWoW_QuestEN[78637] = { title = "Cracking Cogchewer", description = "Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. \n\nNeed his keys to get in the mines... and get me out of this thing!", objectives = "" }
WordHunterWoW_QuestEN[78638] = { title = "Engineering Destruction", description = "Some of the kobolds are retrofitting equipment left behind when the mines fell.\n\nPlease, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy.\n\nThere was a storage depot on the western edge of the lowest level of the mine. Start there.", objectives = "" }
WordHunterWoW_QuestEN[78639] = { title = "Ko-boldening", description = "Bullies everywhere!\n\nInnocent kobolds kept down by Candle King's thugs all across Warrens.\n\nGive bullies taste of own medicine!\n\nOnce bullies beaten, innocent have chance to run. Be free!", objectives = "" }
WordHunterWoW_QuestEN[78640] = { title = "Manifesto Destiny", description = "Before take mines, my people live in great city. Stoneheads call it the Warrens.\n\nCandle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King.\n\nWhat better way than pamphlets? Everyone love pamphlet! We draw real good!\n\nBrinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets!\n\n<Skitter looks at you expectantly, making small flapping motions as she waits.>", objectives = "" }
WordHunterWoW_QuestEN[78641] = { title = "Tackling Torchsnarl", description = "Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully.\n\nWe show everyone. Bullies can be beaten!", objectives = "" }
WordHunterWoW_QuestEN[78642] = { title = "New Candle, New Hope", description = "We weaken Candle King's grasp. Still need symbol, rally my people.\n\nKing has ancient relic: symbol of hope. Called Candle Crown. Heart of my people. Candle King threw away! Found new prize: Darkflame Candle.\n\nThat crown? Still in hoard. Candle King should come out now. See what we did here!\n\nWhile he looks, we sneak in! Use old tunnels! Take what's ours! We smart.", objectives = "" }
WordHunterWoW_QuestEN[78643] = { title = "Fair Skies and Strong Winds", description = "It has been a long road for us all, {name}.\n\nBut after persevering through hardship and strife, dragonkind stands poised to enter a new age.\n\nBefore you leave for your next adventure, my fellow Aspects and I wish to thank you for all you have done for us.", objectives = "" }
WordHunterWoW_QuestEN[78646] = { title = "Fire Watch", description = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald...\n\nHer shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames.\n\nBut we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", objectives = "" }
WordHunterWoW_QuestEN[78655] = { title = "Adaptive Cooling Salve", description = "Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath.\n\nBring me the materials I don't have, and I'm sure I can put something together.", objectives = "" }
WordHunterWoW_QuestEN[78656] = { title = "Hose It Down", description = "With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline.\n\nWe need your help to clean up this gooey blight! \n\nI have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.", objectives = "" }
WordHunterWoW_QuestEN[78658] = { title = "The Hallowed Path", description = "{name}, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall.\n\nShe's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence.\n\nAdelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.", objectives = "" }
WordHunterWoW_QuestEN[78659] = { title = "Where the Light Touches", description = "Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships.\n\nGeneral Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed.\n\nIf you're willing, ride with me or meet me there.", objectives = "" }
WordHunterWoW_QuestEN[78664] = { title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", objectives = "" }
WordHunterWoW_QuestEN[78665] = { title = "Tunnel Trouble", description = "It's good to have new allies here. Together, we have much better chances of protecting this tower.\n\nThe nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall.\n\nIf you can handle that, we will survey the field from the top of the wall and meet you there.", objectives = "" }
WordHunterWoW_QuestEN[78666] = { title = "The Only Good Spider", description = "{name}, if we don't stem the tide of nerubians climbing up to us, nothing else will matter.\n\nTheir numbers are just too great.\n\nWe need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint.\n\nDo what you can to thin their numbers.", objectives = "" }
WordHunterWoW_QuestEN[78667] = { title = "Rekindled Memories", description = "Good people died here today, {name}--a lot of them.\n\nEvery Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope.\n\nWith the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.", objectives = "" }
WordHunterWoW_QuestEN[78668] = { title = "Rally on the Dawnbreaker", description = "It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent.\n\nThe nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies.\n\nIf we lose our armada, our hopes fade dramatically. Meet us there when you can.", objectives = "" }
WordHunterWoW_QuestEN[78669] = { title = "For Their Eyes Only", description = "We've fought the nerubians since we arrived, {name}. Their attacks have not risen to this level in a long time.\n\nThese airship docks are clearly a target, but do they have any others? Is there a larger goal?\n\nThe nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.", objectives = "" }
WordHunterWoW_QuestEN[78670] = { title = "Siege Weapon Sabotage", description = "{name}, if we're going to hold the nerubians back, we have to deal with their siege weapons. \n\nAround Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work.\n\nGather some barrels, and take them down to the nerubian siege weapons.", objectives = "" }
WordHunterWoW_QuestEN[78671] = { title = "The Light of the Dawntower", description = "{name}, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall. Kyron is there as well.\n\nIt's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light.\n\nMeet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.", objectives = "" }
WordHunterWoW_QuestEN[78672] = { title = "A Lamplighter's Duty", description = "Darkness has fallen. We can't rest yet. \n\n<Faerin gives you a weary smile, but there is a light in her eyes.>\n\nThe light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. \n\nMy patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.", objectives = "" }
WordHunterWoW_QuestEN[78674] = { title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. \n\nPerhaps he has insight to teach you.", objectives = "" }
WordHunterWoW_QuestEN[78679] = { title = "The Gift of Relaxation", description = "Self-love can take many different forms. And on occasion it can take the form of relaxing. \n\nThe night elf by the fireworks seems particularly relaxed. \n\nPerhaps you could ask him for his insights on relaxation.", objectives = "" }
WordHunterWoW_QuestEN[78685] = { title = "The Tunnel's End", description = "So we're hearing more rumors about Taelloch. \n\nThe town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there.\n\nThat tells me we should investigate. And of course, if people are hurting, then we should help them.", objectives = "" }
WordHunterWoW_QuestEN[78686] = { title = "Lights Out", description = "Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid.\n\nThe dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall, it's probably because of the rising tide of kobyss.\n\nLamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?", objectives = "" }
WordHunterWoW_QuestEN[78687] = { title = "Crash Recovery", description = "A lot of things went wrong when the Indomitable crashed, {name}. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades.\n\nIt seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form.\n\nTake back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.", objectives = "" }
WordHunterWoW_QuestEN[78688] = { title = "Cage, Match", description = "When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice.\n\nThose sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims.\n\nLet's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.", objectives = "" }
WordHunterWoW_QuestEN[78689] = { title = "If It Leads, It Bleeds", description = "Everything rises and falls on leadership, {name}. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand.\n\nWithout leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map.\n\nDeal with them, and we'll be much more able to help Velhan's Claim.", objectives = "" }
WordHunterWoW_QuestEN[78690] = { title = "Situational Awareness", description = "Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim.\n\n{name}, will you please check in with the families here? Let them know we're here to help.\n\nSee if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.", objectives = "" }
WordHunterWoW_QuestEN[78691] = { title = "The One That Got Away", description = "{name}, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". \n\nWhen they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away.\n\nI have not handled myself bravely, {name}. The story of the Indomitable says I was a hero; those lies were my report. \n\nIf there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, {name}--help me save Maximillian.", objectives = "" }
WordHunterWoW_QuestEN[78692] = { title = "Teach a Man to Fish", description = "{name}, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. \n\nAnd there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. \n\nGet these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!", objectives = "" }
WordHunterWoW_QuestEN[78693] = { title = "Spears for Fears", description = "It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them.\n\nThis is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human.\n\nHead out there and gather some spears for the people, {name}, and they won't have to be so afraid.", objectives = "" }
WordHunterWoW_QuestEN[78694] = { title = "Reclaiming Velhan's Claim", description = "The problem I see, {name}, is the kobyss. There's just so many of them.\n\nEveryone here was serving in the Empire's military when we arrived in Hallowfall. They may be rusty now, but they've all trained before, and know how to be dangerous.\n\nBut we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.", objectives = "" }
WordHunterWoW_QuestEN[78695] = { title = "Lamp Lit", description = "The kobyss normally live deep underwater, {name}. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them.\n\nAs Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.", objectives = "" }
WordHunterWoW_QuestEN[78696] = { title = "We Don't Go to Taelloch", description = "This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him.\n\nWe shouldn't dally. \n\nWe need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!", objectives = "" }
WordHunterWoW_QuestEN[78697] = { title = "Ghost of a Company Town", description = "The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby!\n\nWe should go further into town and see if anyone has any idea where she might be.\n\nOr maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!", objectives = "" }
WordHunterWoW_QuestEN[78700] = { title = "Controlled Demolition", description = "I know we've fought skardyn before, champion, but this... this is worse. \n\nI knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. \n\nIf we must venture out there, I'm taking down some of those abominations along the way.", objectives = "" }
WordHunterWoW_QuestEN[78701] = { title = "The Truth in Chalk", description = "So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean....\n\nI'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines.\n\nAnd I know the foreman is the key. She has to be.", objectives = "" }
WordHunterWoW_QuestEN[78703] = { title = "Buried in Stone", description = "We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.", objectives = "" }
WordHunterWoW_QuestEN[78704] = { title = "Find the Foreman", description = "Dagran was right. I suppose I shouldn't be surprised by that any longer.\n\nAll the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers.\n\nWe've come this far. Let's see what's inside.", objectives = "" }
WordHunterWoW_QuestEN[78705] = { title = "What She Saw", description = "What is that? That thing the skardyn dropped before we... before it died.\n\nI think I've seen something like that before.", objectives = "" }
WordHunterWoW_QuestEN[78706] = { title = "The High Speaker's Secret", description = "We got what we came for. We need to return to Gundargaz. Brinthe has to know what happened here.\n\nWe'll go on ahead, {name}. Meet us in Gundargaz.", objectives = "" }
WordHunterWoW_QuestEN[78713] = { title = "The War Within", description = "There is a vision being seen across Azeroth. A \"Radiant Song.\" We believe it's a warning, but we are unsure of its meaning.\n\nMeet me in Silithus. We must ask Azeroth's Speaker what this vision means.", objectives = "" }
WordHunterWoW_QuestEN[78714] = { title = "A Poor Reception", description = "There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help.\n\nThat's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us.\n\nHe should be in the Chamber of the Heart. Let's go.", objectives = "" }
WordHunterWoW_QuestEN[78715] = { title = "Azeroth's Voice", description = "I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can.\n\nBut I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what.\n\nFirst, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?", objectives = "" }
WordHunterWoW_QuestEN[78716] = { title = "Painful Lessons", description = "Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran.\n\nFollow us when you can.", objectives = "" }
WordHunterWoW_QuestEN[78717] = { title = "A Mysterious Warning", description = "Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin.\n\nI saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us.\n\nThat's what we need to protect.", objectives = "" }
WordHunterWoW_QuestEN[78718] = { title = "Strengthen the Wards", description = "Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst.\n\nHere, take this wand. It's been attuned with Dalaran's defense magics.\n\nJust wave it near strategic parts of the city to strengthen our magical defenses.", objectives = "" }
WordHunterWoW_QuestEN[78719] = { title = "Citizens of Dalaran", description = "Our citizens must be prepared for Dalaran's departure. Can you ask around the city and see if anyone requires aid?\n\nI'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.", objectives = "" }
WordHunterWoW_QuestEN[78721] = { title = "Meet the Team", description = "If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. \n\nThey're calling themselves the Algari Expedition this time around.\n\nI'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?", objectives = "" }
WordHunterWoW_QuestEN[78722] = { title = "To Khaz Algar!", description = "From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out.\n\nLet me know when you're ready to depart.", objectives = "" }
WordHunterWoW_QuestEN[78724] = { title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Goldshire. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", objectives = "" }
WordHunterWoW_QuestEN[78726] = { title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", objectives = "" }
WordHunterWoW_QuestEN[78727] = { title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire.\n\nI hear they have some extra beds upstairs. Why not see if you can sleep there for a while?\n\nI think I will have a bit of a rest too... Right... here...", objectives = "" }
WordHunterWoW_QuestEN[78729] = { title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a guy that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", objectives = "" }
WordHunterWoW_QuestEN[78738] = { title = "Absent Speaker", description = "It is a dark day for the Ringing Deeps, {name}.\n\nI always knew there was something about the High Speaker that wasn't quite right. Now we have proof.\n\nAnd we need justice. If he has plans for the Awakening Machine, then we've got to stop him.", objectives = "" }
WordHunterWoW_QuestEN[78741] = { title = "Sympathetic Speakers", description = "I have to stop the High Speaker from making more skardyn.\n\nMachine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!", objectives = "" }
WordHunterWoW_QuestEN[78742] = { title = "Battle of the Earthenworks", description = "{name}! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker.\n\nI'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. \n\nWhat do you say, {name}? Up for a scrap?", objectives = "" }
WordHunterWoW_QuestEN[78743] = { title = "Before I Depart", description = "I can feel my energy reserves depleting.\n\nI will soon not be able to execute my duties. That is why I have Urtago here to take over.\n\nBefore my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there.\n\nMaybe it is good you are here. You may have the strength to help us.\n\nPlease, help Urtago rid the site of kobolds.", objectives = "" }
WordHunterWoW_QuestEN[78744] = { title = "Honor Their Memories", description = "Take these gifts and place them by the past caretakers. Each is a gift honoring their memory.\n\nI'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix.\n\nPlease do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.", objectives = "" }
WordHunterWoW_QuestEN[78745] = { title = "You No Take Plunder!", description = "It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. \n\nAbominable.\n\nFind where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later.\n\nThis vandalism will not go unchecked!", objectives = "" }
WordHunterWoW_QuestEN[78746] = { title = "Laws Apply to All", description = "Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here.\n\nStill, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.", objectives = "" }
WordHunterWoW_QuestEN[78747] = { title = "The Great Collapse", description = "Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back.\n\nRemember the stuff that Korgran asked about? Explosive sticks--his recipe. I have brought enough to shake a mountain! More than enough for the kobolds.\n\nHelp me show these kobolds that we will fight for what is ours so they will never come back!", objectives = "" }
WordHunterWoW_QuestEN[78748] = { title = "Cutting the Wick", description = "Knowing kobolds, they will have several workmasters, or leaders, running this raid.\n\nFind and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.", objectives = "" }
WordHunterWoW_QuestEN[78749] = { title = "Who Runs This Fine Establishment?", description = "While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind.\n\nIf that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down.\n\nI will meet you at this cave.", objectives = "" }
WordHunterWoW_QuestEN[78754] = { title = "Lost Delivery", description = "<You find a small yet heavy leather-bound package on the road with an attached label.>\n\nGundargaz Courier Express\n\nEXPEDITED\n\nTo: \nHarvester Farnee\nDurgaz Cabin\n\nOPEN WITH CARE: Contains volatile elemental minerals.", objectives = "" }
WordHunterWoW_QuestEN[78755] = { title = "Playing in the Mud", description = "Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger!\n\nProblem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach!\n\nBring me wet, elementally charged silt to use as our restorative substrate!", objectives = "" }
WordHunterWoW_QuestEN[78756] = { title = "Lots and Lots of Fire Honey", description = "If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. \n\nUnfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. \n\nHead on down to the wold's edge and bring us some honey. You're going to need a lot.", objectives = "" }
WordHunterWoW_QuestEN[78757] = { title = "Honey and Clay the Pain Away", description = "Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. \n\nThe bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond.\n\nThe good news is that we have all we need to tend to him.\n\nWe just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! \n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[78758] = { title = "Pulse Within the Earth", description = "Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. \n\nThough, if the nerubians burrowing up didn't wake him up, I'm not sure what will.\n\nTake these earth shards and plant them on the waterfalls and hills around the lake. \n\nOnce we've got them set up, I'll be able to get a reading on the giant's health.", objectives = "" }
WordHunterWoW_QuestEN[78759] = { title = "To Wake a Giant", description = "By the Coreway, this stuff packs a punch!\n\nCombining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain!\n\nWhich is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide!\n\nIt should be enough to wake him up and alleviate any soreness.\n\nHopefully, anyways.", objectives = "" }
WordHunterWoW_QuestEN[78760] = { title = "Dark Iron from Above", description = "We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening.\n\nNow, we just need to deal with the leader of their forces before they can coordinate a more unified resistance.\n\nAre you ready to do this, {name}?", objectives = "" }
WordHunterWoW_QuestEN[78761] = { title = "Into the Machine", description = "No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him.\n\nRemember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!", objectives = "" }
WordHunterWoW_QuestEN[78762] = { title = "Your First Find", description = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah!\n\nNow, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out.\n\nEmpowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", objectives = "" }
WordHunterWoW_QuestEN[78763] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[78789] = { title = "Flightstones", description = "", objectives = "" }
WordHunterWoW_QuestEN[78821] = { title = "Blooming Dreamseeds", description = "The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.", objectives = "" }
WordHunterWoW_QuestEN[78827] = { title = "Go Take Candle!", description = "Ksk, ksk! You there! Yes, you!\n\n<You hear the sound of jostling behind the vent and a new, even scratchier voice emerges.>\n\nWe, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me.\n\nBring us, me, bring me candles! Yes! \n\nNo ask question, just go get candles. \n\nWe are, er, I am professional, yes. Professionals do not ask questions. \n\nOnly get candles.", objectives = "" }
WordHunterWoW_QuestEN[78837] = { title = "Pomp and Dire Circumstance", description = "I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will.\n\nThe High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.", objectives = "" }
WordHunterWoW_QuestEN[78838] = { title = "Cogs in the Machine", description = "Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed.\n\nAs the number of Machine Speakers decreases, we're in a race against time. \n\nLately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens.\n\nLet me show you around the area. There are some earthen I would like you to meet.", objectives = "" }
WordHunterWoW_QuestEN[78839] = { title = "Kobold Shoulder", description = "The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz.\n\nSee if you can reduce the swarm, {name}, before hostilities escalate further.", objectives = "" }
WordHunterWoW_QuestEN[78860] = { title = "More Candles!", description = "I, er, we...no, no, I! I have new deal for you, oh shadowy one. \n\nMore candles! \n\nIn return, you get... er...\n\n<Frantic shuffling reveals a new voice.>\n\nYou get more candles! Then you give to us! To me! \n\nCandles! Candles! Candles!\n\n<The excitedly whispered chanting continues for some time.>", objectives = "" }
WordHunterWoW_QuestEN[78863] = { title = "A Place Beneath the Boughs", description = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles.\n\nAmirdrassil's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil.\n\nTyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", objectives = "" }
WordHunterWoW_QuestEN[78864] = { title = "The Returning", description = "It is a time of reflection and change, {name}. For the world, and for my people.\n\nMy mother and I have been discussing the roads that led us here... and where those roads will lead in the years to come.\n\nCome, let us speak.", objectives = "" }
WordHunterWoW_QuestEN[78865] = { title = "Siblings Until the End", description = "Some time ago, Vyranoth received an unexpected summons... from Iridikron.\n\nYou will want to hear what he had to say.", objectives = "" }
WordHunterWoW_QuestEN[78874] = { title = "Conjured Help", description = "If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment.\n\nIt's starting to become a problem, actually.\n\nSay... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?", objectives = "" }
WordHunterWoW_QuestEN[78875] = { title = "The Unkillable", description = "I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. \n\nHe be using the altar's centerpiece as a conduit to drain Lukou's power.\n\nRecover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.", objectives = "" }
WordHunterWoW_QuestEN[78876] = { title = "A Glowing Memento", description = "<An unusually persistent ember draws your eye. It glows with a pure, primal heat.> \n\n<Vyranoth would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[78877] = { title = "Bless These Homes", description = "Divine presence acknowledged.\n\nEvery day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. \n\nA sacred task. \n\nThese are dark times we live in--perhaps you could add your own beatitudes to our little rituals?", objectives = "" }
WordHunterWoW_QuestEN[78879] = { title = "Evoking the Forge", description = "Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well...\n\nThere's no one to fix it anymore.\n\nIf you can figure out a way of getting it running hot again, Gundargaz would be in your debt!", objectives = "" }
WordHunterWoW_QuestEN[78880] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[78881] = { title = "The Eastern Kingdoms Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[78893] = { title = "A Scrap of Bronze", description = "The vendors of Pandaria do not want the equipment you will find in this timeline.\n\nYou can convert unwanted equipment into Bronze using the magic of the infinite dragonflight.\n\nUse the Unraveling Sands ability and scrap the Unraveling Tunic.", objectives = "" }
WordHunterWoW_QuestEN[78894] = { title = "Infinite Growth", description = "", objectives = "" }
WordHunterWoW_QuestEN[78895] = { title = "A Shadow Over Gundargaz", description = "You look dangerous.\n\n<Toki spits on the ground.>\n\nThat's good. We need dangerous. Something is stalking Gundargaz. \n\nSomething mean. \n\nSomething... recent. \n\nJust before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock.\n\nFingers, mostly. \n\nIf you could sniff out what's stalking my town, I'd be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[78897] = { title = "Boom or Blight", description = "This place is infested with cave borers. They pose a threat to the great roots that stretch through this place.\n\nYes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. \n\nBy my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?", objectives = "" }
WordHunterWoW_QuestEN[78898] = { title = "Intention vs Instinct", description = "Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention.\n\nA wormcaller of the nerubians must be present.\n\nFind them and recover the tool they use to call these worms here. With it we can lead them away in time.", objectives = "" }
WordHunterWoW_QuestEN[78900] = { title = "On Cold, Dark Wings", description = "You came down the Coreway, right? From up top?\n\n<Toki chuckles.>\n\nThey have it easy, those city earthen. Down here, death comes for you from all around. \n\nFrom below. From above.\n\nYou look like you've killed a fair few beasts in your time. Care to add another to the list?", objectives = "" }
WordHunterWoW_QuestEN[78901] = { title = "Heeeelllp!!!", description = "Hey! You!\n\nGet me down! Away from these worms! Please!\n\nI'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! \n\nJust get me down!\n\nAlso, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.", objectives = "" }
WordHunterWoW_QuestEN[78902] = { title = "Delegated Dig", description = "Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp.\n\nThis is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. \n\nI'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a {class} would know how to use it. \n\nTell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!", objectives = "" }
WordHunterWoW_QuestEN[78906] = { title = "Hello World", description = "", objectives = "" }
WordHunterWoW_QuestEN[78915] = { title = "Squashing the Threat", description = "I need your help!\n\nThe massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites.\n\nMom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs.\n\nCan you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?", objectives = "" }
WordHunterWoW_QuestEN[78918] = { title = "Brax's Brass Knuckles", description = "I have a proposition for you.\n\nWe get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. \n\nUsually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts.\n\nMind fetching my knuckles and administering some love taps?", objectives = "" }
WordHunterWoW_QuestEN[78929] = { title = "Tricks of the Dark", description = "Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper!\n\nAnd that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. \n\nThey eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!", objectives = "" }
WordHunterWoW_QuestEN[78932] = { title = "Fickle Fiendish Fish", description = "Judging by the glint in your eye, you wish to join Faerin in this madness?\n\nTo push into the kobyss waters? In the darkness?\n\nYou are a fool with a death wish. \n\nTake as many of those damnable fish out as you can, before they drag you into the depths for their dinner.", objectives = "" }
WordHunterWoW_QuestEN[78933] = { title = "The Sweet Eclipse", description = "I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor!\n\nTo balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness.\n\nPlease assist me in harvesting the following ingredients: Frog-Kissed Caviar, Darkroot Persimmon and Ethereal Sugar.", objectives = "" }
WordHunterWoW_QuestEN[78934] = { title = "Blades of the Arathi", description = "I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing.\n\nWith the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow.\n\nLight a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength.\n\nWe will catch up with you. May the Flame guide you, my friend.", objectives = "" }
WordHunterWoW_QuestEN[78936] = { title = "Something's Fishy", description = "So you outsiders and Faerin managed to both survive and save the villagers at the beach? \n\n<Steelstrike breathes a quick prayer in relief.> \n\nWe're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. \n\nWe have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.", objectives = "" }
WordHunterWoW_QuestEN[78937] = { title = "Shadow upon Shadow", description = "<Faerin's wide eyes dart around in surprise.>\n\nWhat just happened? Did you see that shadow? And the oil well... it's gone dark? \n\nI've never seen anything like this before. \n\nCould it be the nearby dawntower? Hurry!", objectives = "" }
WordHunterWoW_QuestEN[78938] = { title = "Champion of the Waterlords", description = "I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing.\n\nProve your conviction! Slay Ragnaros, once and for all!", objectives = "" }
WordHunterWoW_QuestEN[78939] = { title = "The Darkened Flame", description = "This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what.\n\nWe should investigate.", objectives = "" }
WordHunterWoW_QuestEN[78940] = { title = "Quest 00", description = "Placeholder for RP/Pacing as needed.", objectives = "" }
WordHunterWoW_QuestEN[78941] = { title = "A Tide Needing Turned", description = "Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment?\n\nSomething is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands.\n\nReport to the Arathi general. I'll head to the battlefield directly.", objectives = "" }
WordHunterWoW_QuestEN[78942] = { title = "The Might of Khaz Algar", description = "The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight.\n\nThe Algari Offensive stands at your back, {name}. Spare no enemy.", objectives = "" }
WordHunterWoW_QuestEN[78943] = { title = "Steel and Flames", description = "Our forces may be able to hold their own, but seeing you in the fray may help their spirits. \n\nTake this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.", objectives = "" }
WordHunterWoW_QuestEN[78948] = { title = "A Light in the Dark", description = "Something is very wrong. As the battle continues, each side has become more aggressive.\n\nAlleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.", objectives = "" }
WordHunterWoW_QuestEN[78950] = { title = "Cutting Off the Legs", description = "While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical.\n\nTake them out. Hopefully that will allow us some breathing room. \n\nSpeak with Anduin after you are done. He and the Arathi girl went after Alleria.", objectives = "" }
WordHunterWoW_QuestEN[78951] = { title = "Ever Deeper Shadow", description = "When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. \n\nIt pains me, but... my light alone is not enough to banish these shadows. \n\nAnd so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. \n\nWe must stop them before this darkness spreads.", objectives = "" }
WordHunterWoW_QuestEN[78952] = { title = "The Final Resistance", description = "<Faerin speaks in a hushed, furious whisper.>\n\nGood work. But before we can leave, there's something else. \n\nDown this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself.\n\nIt will be dangerous, but we must stop them. Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[78954] = { title = "Restore the Flame", description = "Do you feel it? Hope, returning? \n\nThank you for your help, {name}.\n\nThe dawntower's flame remains dark. But this time, I think we'll be able to restore it. \n\nLet's meet at the tower.", objectives = "" }
WordHunterWoW_QuestEN[78972] = { title = "Harvest Havoc", description = "Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. \n\nWe have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!", objectives = "" }
WordHunterWoW_QuestEN[78978] = { title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a gal that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", objectives = "" }
WordHunterWoW_QuestEN[78979] = { title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Razor Hill inn. It may not look like much, but it is surprisingly comfortable!\n\nWhy don't you see if they have any extra beds you could use?\n\nI think I will have a bit of a rest too... Right... here...", objectives = "" }
WordHunterWoW_QuestEN[78980] = { title = "Take a Look Around", description = "Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well!\n\nGo, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!", objectives = "" }
WordHunterWoW_QuestEN[78981] = { title = "Love is in the Air", description = "Smell these roses! My partner got them for me at the Gala of Gifts.\n\nInterested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!", objectives = "" }
WordHunterWoW_QuestEN[78982] = { title = "I Smell Trouble", description = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it?\n\nWell, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away!\n\nAre you in? I could use a good partner to solve this.", objectives = "" }
WordHunterWoW_QuestEN[78983] = { title = "An Unwelcome Gift", description = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent!\n\nBut let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", objectives = "" }
WordHunterWoW_QuestEN[78984] = { title = "Crushing the Crown", description = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver.\n\n<Snagglebolt points to the unmarked box.>\n\nBombs. I got bombs.\n\nPlaytime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", objectives = "" }
WordHunterWoW_QuestEN[78985] = { title = "The Stench of Revenge", description = "We're never gonna see an end to this unless we take on the boss himself.\n\nLook, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research.\n\nYou go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", objectives = "" }
WordHunterWoW_QuestEN[78986] = { title = "Getaway to Scenic Grizzly Hills!", description = "Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend!\n\nAlthough perhaps I could beg you for a favor. You seem the adventurous type. \n\nI could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. \n\nI would do it myself but... Well, you see, she is rather intimidating in her beauty.", objectives = "" }
WordHunterWoW_QuestEN[78987] = { title = "Getaway to Scenic Nagrand!", description = "Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand!\n\nWould you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn.\n\nHe has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.", objectives = "" }
WordHunterWoW_QuestEN[78988] = { title = "Getaway to Scenic Feralas!", description = "Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala.\n\nCould you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.", objectives = "" }
WordHunterWoW_QuestEN[78989] = { title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", objectives = "" }
WordHunterWoW_QuestEN[78990] = { title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress.\n\nPerhaps he has insight to teach you.", objectives = "" }
WordHunterWoW_QuestEN[78991] = { title = "The Gift of Relaxation", description = "Love is a gift, yes. But it is also a gift that you can give yourself.\n\nSometimes, the best way to love yourself is simply to relax.\n\nI met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.", objectives = "" }
WordHunterWoW_QuestEN[78992] = { title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Razor Hill. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", objectives = "" }
WordHunterWoW_QuestEN[78993] = { title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", objectives = "" }
WordHunterWoW_QuestEN[78996] = { title = "Weapons and Warriors", description = "Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough.\n\nI know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment.\n\nWe will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use.\n\nI will go with the farmers and train them as best I can.", objectives = "" }
WordHunterWoW_QuestEN[78997] = { title = "Pilfered Pearls", description = "The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing.\n\nThe gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[78998] = { title = "Frontline Farmers", description = "Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. \n\nI need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.", objectives = "" }
WordHunterWoW_QuestEN[78999] = { title = "Heart of a Hero", description = "It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily.\n\nIt will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created.\n\nElementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them.\n\nThis should end the gorloc threat to the farmers once and for all.", objectives = "" }
WordHunterWoW_QuestEN[79000] = { title = "[DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[79006] = { title = "Faction Switch", description = "Default", objectives = "" }
WordHunterWoW_QuestEN[79009] = { title = "The Harbinger", description = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger...\n\nLet us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", objectives = "" }
WordHunterWoW_QuestEN[79010] = { title = "Door to the Ren'dorei", description = "If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation.\n\nI'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.", objectives = "" }
WordHunterWoW_QuestEN[79011] = { title = "Riftwalker Reports", description = "The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience.\n\nMany of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports.\n \nWould you check in on them while I speak with Alleria?", objectives = "" }
WordHunterWoW_QuestEN[79012] = { title = "Cracks in the Void", description = "Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us.\n\nThe recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them.\n\nCould you close any unstable void rifts you find along your path?", objectives = "" }
WordHunterWoW_QuestEN[79013] = { title = "Galakrond's Unrest", description = "Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it.\n\nAnd now one of our Riftwalkers is missing, right where it all began.\n\nI don't believe this is a coincidence, {name}. Let's travel to Northrend and search the area.", objectives = "" }
WordHunterWoW_QuestEN[79014] = { title = "Walk a Mile in Her Shadows", description = "I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them.\n\nI cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. \n\nWhich means following the shadows.", objectives = "" }
WordHunterWoW_QuestEN[79015] = { title = "Dark Descension", description = "What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart?\n\nWell. I do not mean to stand idly by.\n\nWe must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.", objectives = "" }
WordHunterWoW_QuestEN[79016] = { title = "Legacy of the Void", description = "Make no mistake, {name}. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk.\n\nBe at the ready. We venture forth.", objectives = "" }
WordHunterWoW_QuestEN[79017] = { title = "The Path Taken", description = "These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine?\n\nWe need to explore. Discover why we were led here.", objectives = "" }
WordHunterWoW_QuestEN[79018] = { title = "And Be One Traveler, Long I Stood", description = "I sense another memory ahead.\n\nWhile I'm loath to play along with the Harbinger's game, it's the only path forward for us.\n\nStill, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[79019] = { title = "Defend Telogrus Rift", description = "No. Not the ren'dorei. Not Telogrus Rift. Not today.\n\n<Alleria tightens her grip on her bow.>\n\nThese ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. \n\nI'll go ahead. Engage the enemies here.", objectives = "" }
WordHunterWoW_QuestEN[79020] = { title = "Null and Void", description = "We must defeat that loathsome apparition of Turalyon.\n\nThe abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. \n\nI will end it with my own hands.", objectives = "" }
WordHunterWoW_QuestEN[79021] = { title = "Radiant Warnings", description = "So she goes by Harbinger now, does she? How fitting.\n\nI no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board.\n\nAs are you, champion of fate.", objectives = "" }
WordHunterWoW_QuestEN[79022] = { title = "A Mysterious Signal", description = "High Speaker Brinthe has sent an urgent missive for you, {name}.\n\nShe is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps.\n\nCan you meet her there and provide your expertise?", objectives = "" }
WordHunterWoW_QuestEN[79023] = { title = "Small Friend, Big Plans", description = "I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast.\n\nIf we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional.\n\nFortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?", objectives = "" }
WordHunterWoW_QuestEN[79024] = { title = "Factory Recon", description = "ZZ-01-47 should be able to make its way in there without drawing too much attention.\n\nBut be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.", objectives = "" }
WordHunterWoW_QuestEN[79025] = { title = "A Plan Comes Together", description = "We have our work cut out for us, {name}. But I think, with Dagran's help, we can break this down and tackle it piece by piece.\n\nWhy don't you take us through what we've learned so far.", objectives = "" }
WordHunterWoW_QuestEN[79026] = { title = "Putting the Works in Waterworks", description = "Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles!\n\nDo you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.", objectives = "" }
WordHunterWoW_QuestEN[79027] = { title = "Elemental Trepidation", description = "<ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>", objectives = "" }
WordHunterWoW_QuestEN[79028] = { title = "We Require More Minerals", description = "Zee-Zee is ready to help you get the Shadowvein site up and running again.", objectives = "" }
WordHunterWoW_QuestEN[79029] = { title = "It's Sabotage", description = "We're back, and we're ready.\n\nYou and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out.\n\nWe don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve.\n\nThe Darkfuse lackeys will clear out when the coin stops flowing.", objectives = "" }
WordHunterWoW_QuestEN[79030] = { title = "The Voice of the Speakers", description = "Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.", objectives = "" }
WordHunterWoW_QuestEN[79074] = { title = "Summoning All Soldiers!", description = "The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this brochure to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", objectives = "" }
WordHunterWoW_QuestEN[79085] = { title = "A Pile of Fish", description = "<A pile of fish, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "" }
WordHunterWoW_QuestEN[79087] = { title = "A Pile of Clams", description = "<A pile of clams, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "" }
WordHunterWoW_QuestEN[79089] = { title = "Consecrated Cleanup", description = "Our Veneration Grounds have been desecrated. Its beauty marred. \n\nIt's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.", objectives = "" }
WordHunterWoW_QuestEN[79105] = { title = "Breach", description = "As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. \n\nRescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.", objectives = "" }
WordHunterWoW_QuestEN[79106] = { title = "Rupture", description = "Follow me. We'll work together to find any others in need of rescuing.", objectives = "" }
WordHunterWoW_QuestEN[79107] = { title = "After the Storm", description = "Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. \n\nMany were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly.\n\nThe surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.", objectives = "" }
WordHunterWoW_QuestEN[79108] = { title = "Seeds of Evil", description = "{class}, some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better.\n\nMy idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait.\n\nClearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.", objectives = "" }
WordHunterWoW_QuestEN[79109] = { title = "Follow Miral", description = "Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble.\n\nCan you find out what is bothering her for me?", objectives = "" }
WordHunterWoW_QuestEN[79110] = { title = "Save Tomothy", description = "<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>", objectives = "" }
WordHunterWoW_QuestEN[79111] = { title = "Missing Lynx", description = "", objectives = "" }
WordHunterWoW_QuestEN[79113] = { title = "UNUSED PLACEHOLDER", description = "Upon arriving at a deserted beetle ranch, the player discovers 2 nerubians having an argument. \n\nThe larger of the two storms off in a huff.\n\nThe remaining nerubian informs you that the larger one was assigned to this ranch along with him, and they're Not Having A Good Time.\n\nHe asks you to follow the larger one to the barn.", objectives = "" }
WordHunterWoW_QuestEN[79114] = { title = "Beautification Project", description = "A fine enough job, for one of your... ilk.\n\nIf you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply.\n\nRak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows.\n\nFind a way to clear them. I don't care how.", objectives = "" }
WordHunterWoW_QuestEN[79115] = { title = "Expert Consultant", description = "You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight.\n\nThe niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead.\n\nGo and barter with the rats. Come back with able bodies.", objectives = "" }
WordHunterWoW_QuestEN[79117] = { title = "Bright Young Niffen", description = "You need swarmhands, huh? \n\nLast time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo.\n\nWe've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! \n\nMaybe if you lighten their workload, they'll take you up on your offer.", objectives = "" }
WordHunterWoW_QuestEN[79118] = { title = "Rak-Ush Under New Management", description = "Well, you got your swarmhands. \n\nWhat are you still doing here? Go on then, you don't need my permission!\n\nMake sure the nerubians treat them fairly, now.", objectives = "" }
WordHunterWoW_QuestEN[79119] = { title = "It's Rough to Be a Bug!", description = "Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead.\n\nSince this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose.\n\nGo. We are to restore the stagshell hollows and fill them with swarmbeasts.", objectives = "" }
WordHunterWoW_QuestEN[79120] = { title = "Beetle in a Haystack", description = "There are still feral stagshells on the outskirts of Rak-Ush.\n\nThis scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location.\n\nOnce they are stunned, one of the rats will take them back to their hollow.\n\nCapture them and bring them back. We will be waiting.", objectives = "" }
WordHunterWoW_QuestEN[79121] = { title = "Bug Test", description = "Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things.\n\nLoathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I.\n\nThey can enlighten you on your duties, if this was not explanation enough.", objectives = "" }
WordHunterWoW_QuestEN[79122] = { title = "Scarab Scouting", description = "The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. \n\nThe truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.", objectives = "" }
WordHunterWoW_QuestEN[79123] = { title = "Permanent Hire", description = "Rak-Ush is beginning to look like a functioning swarmery.\n\nThe role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. \n\nSaffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.", objectives = "" }
WordHunterWoW_QuestEN[79124] = { title = "Conduit of the Southern Storm", description = "I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter.\n\nBut... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them.\n\nTo summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.", objectives = "" }
WordHunterWoW_QuestEN[79125] = { title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79126] = { title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79127] = { title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79128] = { title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79129] = { title = "Rook Rally", description = "Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. \n\nThrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts.\n\nAn earthen trusting their feelings and instincts. That's... a challenge.\n\nYou will help me, right? I'm not a fighter, and it looks dangerous up there. \n\nIf anything happens to me, make sure Shraubendre makes it out safe. Please.", objectives = "" }
WordHunterWoW_QuestEN[79130] = { title = "The Northrend Cup Circuit", description = "It is time once again to test your mettle.\n\nMy bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit!\n\nAre you up to the task?", objectives = "" }
WordHunterWoW_QuestEN[79131] = { title = "The Northrend Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79132] = { title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79133] = { title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", objectives = "" }
WordHunterWoW_QuestEN[79134] = { title = "A Spring Awakening", description = "The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.", objectives = "" }
WordHunterWoW_QuestEN[79135] = { title = "Quacking Down", description = "Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!", objectives = "" }
WordHunterWoW_QuestEN[79136] = { title = "A Spring Awakening", description = "The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.", objectives = "" }
WordHunterWoW_QuestEN[79137] = { title = "The Wall Between Us", description = "I know this fight was not ours, {name}. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned.\n\nI do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken.\n\nLet us meet with Lilian in Pyrewood Village. This celebration is not for us.", objectives = "" }
WordHunterWoW_QuestEN[79139] = { title = "Alone in the Dark", description = "My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now?\n\nBut the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that.\n\nThe nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.", objectives = "" }
WordHunterWoW_QuestEN[79140] = { title = "Goldbricking", description = "Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. \n\nWe've got a lot of work to do.\n\nGet down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.", objectives = "" }
WordHunterWoW_QuestEN[79145] = { title = "Metal and Stone", description = "While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it.\n\nEarthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.", objectives = "" }
WordHunterWoW_QuestEN[79146] = { title = "Ground Pounders", description = "The rooks and their chosen riders will need time to bond. \n\nPerhaps you should use this time to check in on our other trainees. \n\nThe Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines.\n\nAdelgonn, Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.", objectives = "" }
WordHunterWoW_QuestEN[79147] = { title = "Flight Training 101", description = "Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No?\n\nRight then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. \n\nAfter that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.", objectives = "" }
WordHunterWoW_QuestEN[79148] = { title = "The Nibelgaz Refinery", description = "Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. \n\nI am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers.\n\nHere, take this healing clay. It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.", objectives = "" }
WordHunterWoW_QuestEN[79149] = { title = "Rampage in the Refinery", description = "Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs.\n\nDuty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!", objectives = "" }
WordHunterWoW_QuestEN[79150] = { title = "Thespians at the Proscenium", description = "When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way.\n\nMy old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea.\n\nI think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.", objectives = "" }
WordHunterWoW_QuestEN[79151] = { title = "An Orphan's Request", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", objectives = "" }
WordHunterWoW_QuestEN[79152] = { title = "Gutting the Pool", description = "The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated.\n\nKill any stupid fish-faces you see.", objectives = "" }
WordHunterWoW_QuestEN[79153] = { title = "Vae Victis", description = "Ah it's time.\n\nKill their leader. Salt his bones, take his head, and laugh as his tribe crumbles!\n\nSharpscale's last moments are upon him, and he doesn't even realize it yet. \n\nStupid fish-face.", objectives = "" }
WordHunterWoW_QuestEN[79154] = { title = "A Final Goodbye", description = "Well, parents avenged, fish killed, more fish killed, biggest fish killed. \n\nPretty good day.\n\nI guess I should go burn stuff.", objectives = "" }
WordHunterWoW_QuestEN[79156] = { title = "The Edicts", description = "Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders.\n\nI'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.", objectives = "" }
WordHunterWoW_QuestEN[79157] = { title = "Titanic Failsafe", description = "So, the titans sent their ancient machines against their disobedient children.\n\nWould our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart?\n\nNo, today we are all Unbound, and we will fight for our freedom. For Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[79158] = { title = "Seeds of Salvation", description = "These once obedient harvestbots have run amok and are wreaking havoc in our fields.\n\nThe success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters!\n\nWould you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?", objectives = "" }
WordHunterWoW_QuestEN[79159] = { title = "Dereliction of Duty", description = "A moment, if you have one.\n\nOne of my lieutenants, Shinda Creedpike, did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren.\n\nI am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? \n\nTake all the time you need.", objectives = "" }
WordHunterWoW_QuestEN[79160] = { title = "Fishing is Good for the Soul", description = "I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time.\n\nPerhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!", objectives = "" }
WordHunterWoW_QuestEN[79162] = { title = "Burnout", description = "Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.", objectives = "" }
WordHunterWoW_QuestEN[79165] = { title = "A Moment to Rest", description = "Good, you're both here. \n\nI have a favor to ask. \n\nFaerin's wandered off. I think it might help if you and your... disheveled friend here find her. \n\nShe'll be in Light's Redoubt.", objectives = "" }
WordHunterWoW_QuestEN[79166] = { title = "Lost Pieces", description = "There was a time when I would have known what words to say to help her.\n\nBut now... they are as lost to me as everything else. \n\n<Anduin sighs.>\n\nThere must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. \n\nI'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings... could you try to look?", objectives = "" }
WordHunterWoW_QuestEN[79167] = { title = "Crowdsourcing", description = "Light's Gambit is an old and honored game. There's a reason so many Arathi play it! \n\nIt can teach you a lot about strategy. And it can tell you a lot about your opponents. \n\n<Faerin suddenly deflates.> \n\nBut we're still missing a few pieces that we need in order to play.\n\nSometimes, folks around Mereldar lend us pieces for a game. Could you ask around?", objectives = "" }
WordHunterWoW_QuestEN[79168] = { title = "Light's Gambit", description = "It's fine! We can catch you up on the rest of the rules later!\n\nResolving combat is the most fun, anyway!\n\nYou and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance!\n\n<Faerin laughs.>", objectives = "" }
WordHunterWoW_QuestEN[79173] = { title = "Supply the Effort", description = "When shadow fell upon our town, many necessary supplies were taken in the cover of darkness.\n\nWith the light returning, it is time to rebuild, but first, we must retrieve what was lost. \n\nSearch the surrounding areas, recover any supplies that might be useful.", objectives = "" }
WordHunterWoW_QuestEN[79174] = { title = "Infested Infestation", description = "These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it!\n\nThey already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. \n\nGo to Pillar-nest Vosh and take some of those spore-afflicted beasts out!", objectives = "" }
WordHunterWoW_QuestEN[79175] = { title = "I Think I'm a Drone Now", description = "There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth.\n\nAnd now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.", objectives = "" }
WordHunterWoW_QuestEN[79176] = { title = "Opals and Runes", description = "You have certainly made my disaster of a day far less stressful, {name}. \n\nFor that, you have the thanks of the entire Forgegrounds and those who keep it running.\n\n<Vokgret winks as she gives you a knowing smile.>\n\nBevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps.\n\nHere is her liquid opal. Give it to her with my compliments.", objectives = "" }
WordHunterWoW_QuestEN[79178] = { title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", objectives = "" }
WordHunterWoW_QuestEN[79184] = { title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nI'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us!\n\n-Farala, Master of Ceremonies\"", objectives = "" }
WordHunterWoW_QuestEN[79186] = { title = "It's Hearthstone's Anniversary!", description = "Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!", objectives = "" }
WordHunterWoW_QuestEN[79189] = { title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!", objectives = "" }
WordHunterWoW_QuestEN[79193] = { title = "Spinning Spore Spines", description = "Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that.\n\nDid you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some?\n\nI will make my way back to the refinery. I am eager to get back and meet this Orsenth.", objectives = "" }
WordHunterWoW_QuestEN[79194] = { title = "To the Source", description = "Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz, supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. \n\nI will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.", objectives = "" }
WordHunterWoW_QuestEN[79197] = { title = "Surface Bound", description = "{name}, the moment is upon us. We must make haste to the city of Dornogal, where our allies await. \n\nOnly together do we stand a chance against Harbinger's machinations.", objectives = "" }
WordHunterWoW_QuestEN[79200] = { title = "Who am I?", description = "It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn, and this is Foreman Uzjax.\n\nMany things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it.\n\nLike many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. \n\nEmbrace it.", objectives = "" }
WordHunterWoW_QuestEN[79201] = { title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", objectives = "" }
WordHunterWoW_QuestEN[79202] = { title = "Rock Beats Rock", description = "Welcome to the Procedural Forum.\n\nForeman Uzjax informs me that this chamber once served as our assignment testing facility. \n\nWith his guidance, we've repurposed this chamber.\n\nEarthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.", objectives = "" }
WordHunterWoW_QuestEN[79203] = { title = "Authorization: Negated", description = "The Bulwark of Authorization! That's what this chamber was once called.\n\nI had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. \n\nA golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers.\n\nDawn seems to think you've got what it takes to deal with it. Up to the challenge?", objectives = "" }
WordHunterWoW_QuestEN[79204] = { title = "Whoever You Want to Be", description = "After an awakening protocol like that, I can see why Dawn says you're special.\n\nThe world is not prepared for an earthen like you. \n\n<Kuldas claps you on the back with a gravely chuckle.>\n\nDawn and the Foreman are waiting for you in the Awakening Vestibule.\n\nGo on, then! \n\nComplete your Awakening Protocol and get out of here!", objectives = "" }
WordHunterWoW_QuestEN[79205] = { title = "Not Waste, Not Want", description = "Everything have use, friend. Even things stoneheads throw away and think worthless.\n\nKobolds know better.\n\nGo and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!", objectives = "" }
WordHunterWoW_QuestEN[79206] = { title = "Broken Memories", description = "Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe.", objectives = "" }
WordHunterWoW_QuestEN[79213] = { title = "The Anachronism", description = "Insert the batteries into the cylindrical holes on the console.\n\nThen, titans willing, we will see what it holds.", objectives = "" }
WordHunterWoW_QuestEN[79216] = { title = "Web of Manipulation", description = "This town has been under siege, overrun by spiders! Even when we clear them out, they always return.\n\nSomething is behind these attacks!\n\nA small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!", objectives = "" }
WordHunterWoW_QuestEN[79217] = { title = "Back to Base", description = "Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours.\n\nHis mind will be a big help to us here.", objectives = "" }
WordHunterWoW_QuestEN[79221] = { title = "The Unusual Bug", description = "Nerubians in Rak-Ush may find this strange little spider of interest.", objectives = "" }
WordHunterWoW_QuestEN[79222] = { title = "Shadow-Hardened Mainspring", description = "<Maybe it was the effects of prolonged darkness or tinkering by Ezgi Irongear, but the strength of this spring would be of interest to Speaker Kuldas in Gundargaz.>", objectives = "" }
WordHunterWoW_QuestEN[79223] = { title = "Finally, An Archivist!", description = "So you've got your bearings now? You've felt the dirt? You've smelled the history?\n\nWhy not celebrate this glorious moment of above average success with... a cap!\n\nThat's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", objectives = "" }
WordHunterWoW_QuestEN[79224] = { title = "Gathering Intel", description = "The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy.\n\nMy own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster.\n\nUnfortunately, she is... well. You'll see.", objectives = "" }
WordHunterWoW_QuestEN[79225] = { title = "The Lost Flame", description = "<A tinderbox of a Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.>\n\nAn expedition scout might possess knowledge about this item.>", objectives = "" }
WordHunterWoW_QuestEN[79226] = { title = "The Big Dig: Traitor's Rest", description = "Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!", objectives = "" }
WordHunterWoW_QuestEN[79227] = { title = "A Spider's-Eye View", description = "I have eyes in every crevice of the city save for one that has... eluded me.\n\nThe Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded.\n\nA more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.", objectives = "" }
WordHunterWoW_QuestEN[79230] = { title = "Creeping Through Corridors", description = "I've identified three sites of interest to investigate. \n\nA stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there.\n\nThere's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them.\n\nStay sharp, stay quiet.", objectives = "" }
WordHunterWoW_QuestEN[79231] = { title = "Back to Headquarters! Again!", description = "You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist.\n\nMeet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.", objectives = "" }
WordHunterWoW_QuestEN[79232] = { title = "Those Who Fell", description = "Since the Day of Shadows these lands have been a dangerous place. \n\nThe kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves.\n\nThe memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. \n\nSearch for the Tinderboxes of these missing expedition members and return them to me.", objectives = "" }
WordHunterWoW_QuestEN[79233] = { title = "Lab Access", description = "As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer.\n\nOf course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery.\n\nThe nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.", objectives = "" }
WordHunterWoW_QuestEN[79234] = { title = "A Small Bag of Seeds", description = "<This small bag of seeds seems forgotten, perhaps Aliya Hillhelm could make use of them.>", objectives = "" }
WordHunterWoW_QuestEN[79237] = { title = "Making of a Monster", description = "We've got a new objective: Figure out what Ansurek's plans are for this... thing.\n\nWe'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it.\n\nI scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck.\n\nMeet you in there.", objectives = "" }
WordHunterWoW_QuestEN[79239] = { title = "The Queen's Chains", description = "Ansurek... that worm, that witless, gutless little--\n\n<Y'tekhi growls under their breath, struggling to maintain their composure.>\n\nIf this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do.\n\nWhen the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.", objectives = "" }
WordHunterWoW_QuestEN[79240] = { title = "Rogue Agent", description = "We lost Y'tekhi.\n\nWe can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse.\n\n<Lilian snorts.>\n\nI guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.", objectives = "" }
WordHunterWoW_QuestEN[79241] = { title = "Go Loud", description = "So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up.\n\nThey're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least.\n\nI've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.", objectives = "" }
WordHunterWoW_QuestEN[79243] = { title = "Manufactured Mutiny", description = "We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count.\n\nThere's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in.\n\nHit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.", objectives = "" }
WordHunterWoW_QuestEN[79244] = { title = "News From Below", description = "I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly.\n\nY'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim.\n\nAlleria is going to want a status report. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[79245] = { title = "[Unused - Reuse Quest Bit]", description = "", objectives = "" }
WordHunterWoW_QuestEN[79248] = { title = "From Limb to Limb", description = "", objectives = "" }
WordHunterWoW_QuestEN[79251] = { title = "Leveling Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[79252] = { title = "Leveling Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[79253] = { title = "From Limb to Limb", description = "", objectives = "" }
WordHunterWoW_QuestEN[79255] = { title = "Crunchy Competition [DNT]", description = "The spiders steal our prey! They feast on the grubs and leave none for us.\n\nNo, no grubs for the kobolds where spiders lay in wait.\n\nKill them so we can have the Chittering Den to ourselves.", objectives = "" }
WordHunterWoW_QuestEN[79256] = { title = "A Hint of Fear", description = "My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker.\n\nHe said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either.\n\nI'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.", objectives = "" }
WordHunterWoW_QuestEN[79258] = { title = "Mineral Water Woes", description = "When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder.\n\nFortunately, I am a hero!\n\nAnd as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it.\n\nThat mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.", objectives = "" }
WordHunterWoW_QuestEN[79259] = { title = "Put On a Good Face", description = "Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it.\n\nIf we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. \n\nThose Lashrooms look like they're a good place to start. \n\nIt all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.", objectives = "" }
WordHunterWoW_QuestEN[79260] = { title = "Epicenter", description = "There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps, didn't it? Look at the size of that crater!\n\nWith the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it!\n\nBut if it does turn aggressive, don't worry, I'll be right behind you.\n\nWe'll get that hammer out of here safely!", objectives = "" }
WordHunterWoW_QuestEN[79261] = { title = "Boiling Mad", description = "That gravel-brained ingrate! He took Fearbreaker and ran off to the north!\n\nIt's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power!\n\nWe need to track him down before he hurts himself or someone else with that hammer!", objectives = "" }
WordHunterWoW_QuestEN[79262] = { title = "Clean Up House", description = "It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things.\n\nIf this was a thriving mining operation, it ain't anymore. \n\nWe need to help the earthen get it under control again, and that means thinning out these beasts.", objectives = "" }
WordHunterWoW_QuestEN[79263] = { title = "Fault Lines", description = "Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero.\n\nBut ye can't go about doing the wrong thing for the right reasons.  I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. \n\nHe's likely tae need saving himself now. Let's find him in this blasted place.", objectives = "" }
WordHunterWoW_QuestEN[79264] = { title = "These Strong Hands", description = "<Berrund the Gleaming coughs dustily.>\n\nI knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be.\n\nBut it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... <He coughs again.>\n\nIt's clearly not mine. It never was. I'm... I'm... sorry.", objectives = "" }
WordHunterWoW_QuestEN[79265] = { title = "Fearbreaker", description = "The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker.\n\nWe're going to finish that job before I take the hammer back to Magni.\n\nWhat kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[79266] = { title = "The Bronzebeard Legacy", description = "Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it.\n\nNow it's time tae bring it back tae Magni.\n\nLet's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.", objectives = "" }
WordHunterWoW_QuestEN[79267] = { title = "Wax On, Pot Off", description = "If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy.\n\nTake that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any.\n\nIt should certainly make any candles made with that wax quite feisty, once they're lit.", objectives = "" }
WordHunterWoW_QuestEN[79268] = { title = "Gundrak Fast Track", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79269] = { title = "Gundrak Fast Track - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79270] = { title = "Gundrak Fast Track - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79272] = { title = "Coldarra Climb", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79273] = { title = "Coldarra Climb - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79274] = { title = "Coldarra Climb - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[79276] = { title = "The Squishier, the Better [DNT]", description = "Spiders stole my key. I can't get to my treasure without my key!", objectives = "" }
WordHunterWoW_QuestEN[79282] = { title = "The Grand Debut", description = "The Proscenium is looking amazing! Are you ready to get on stage?\n\nGive us a hand as part of the crew, and we'll give you a chance to act.\n\nWill you accept this directive?", objectives = "" }
WordHunterWoW_QuestEN[79297] = { title = "Nightwatch", description = "Xal'atath is using the Order of Night to serve her whims.\n\nI overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike. I'll be there as soon as I can.\n\nWe need to convince her of the severity of this threat.", objectives = "" }
WordHunterWoW_QuestEN[79300] = { title = "The Notebook", description = "{name}, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report!\n\nI'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it.\n\nI thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?", objectives = "" }
WordHunterWoW_QuestEN[79301] = { title = "Height Club", description = "I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain.\n\nHe's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher.\n\nBut if I can't turn in my report, he'll be the next captain. Take it back from him!", objectives = "" }
WordHunterWoW_QuestEN[79302] = { title = "Gone with the Wind", description = "I can't believe Edwyn threw my report out into the wind. \n\nCan you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. \n\nThis report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in.\n\nBring me whatever pages you find!", objectives = "" }
WordHunterWoW_QuestEN[79303] = { title = "A Principled Principal", description = "Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch! He's probably in the classroom.\n\nI sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.", objectives = "" }
WordHunterWoW_QuestEN[79304] = { title = "Care Package", description = "My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew.\n\nShe's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?", objectives = "" }
WordHunterWoW_QuestEN[79309] = { title = "Status Report", description = "Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens.\n\nOne such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.", objectives = "" }
WordHunterWoW_QuestEN[79310] = { title = "Seek the Lost", description = "Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer.\n\nI am afraid.\n\nI won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror.\n\nTell Captain Trueflame her scouts died in darkness, one and all.", objectives = "" }
WordHunterWoW_QuestEN[79311] = { title = "Stem the Flow", description = "The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night.\n\nIt is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. \n\nI've lost my nerve. But you, outsider, can still make this right.", objectives = "" }
WordHunterWoW_QuestEN[79312] = { title = "Mow the Masses", description = "Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back.\n\nOnly later did I find the tiny bite marks on my ankles. Be warned, there's something in the water.\n\nI took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.", objectives = "" }
WordHunterWoW_QuestEN[79313] = { title = "What Grows in the Dark", description = "We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. \n\nBut your courage shines with splendor, {name}. At your side, my way is lit.\n\nNo more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.", objectives = "" }
WordHunterWoW_QuestEN[79321] = { title = "The Catalyst's Gift", description = "I have an urgent message for you, adventurer.\n\nThe Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats!\n\nMiraculously, it now shares its power for nothing in return except one's mere presence.\n\nAntuka will know more. Go with haste, {name}. This is wondrous news.", objectives = "" }
WordHunterWoW_QuestEN[79322] = { title = "What the Duck?", description = "What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom!\n\nWe need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?", objectives = "" }
WordHunterWoW_QuestEN[79323] = { title = "A Fowl Concoction", description = "We need to put an end to this duck invasion.\n\nWhile I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen!\n\nPlease, {name}. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.", objectives = "" }
WordHunterWoW_QuestEN[79324] = { title = "To the Waterworks", description = "Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility.\n\nMeet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.", objectives = "" }
WordHunterWoW_QuestEN[79325] = { title = "Shadowvein Extraction", description = "I sent Zee-Zee ahead to the Shadowvein extraction site.\n\nFrom what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you.\n\nI don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.", objectives = "" }
WordHunterWoW_QuestEN[79327] = { title = "The Glittering Shard", description = "<Glistening with an inner light, this shard of crystal feels warm to the touch..\n\nOrsenth may be interested in examining this piece of ore.>", objectives = "" }
WordHunterWoW_QuestEN[79328] = { title = "Embassies and Envoys", description = "I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians.\n\nWith your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.", objectives = "" }
WordHunterWoW_QuestEN[79330] = { title = "Duck Tales", description = "Take this potion, {name}. You should be able to communicate with your feathery friends with it.\n\nBut don't blame me for any unintended side effects you may experience.", objectives = "" }
WordHunterWoW_QuestEN[79331] = { title = "Just a Waddle Away", description = "We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it.\n\nI convinced Emmery to give me more of that potion. Take it and find my heirloom!", objectives = "" }
WordHunterWoW_QuestEN[79333] = { title = "The Fleet Arrives", description = "From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. \n\nJaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen.\n\nAn' I have to say we've done well on our own, haven't we? \n\n<Moira smiles at you proudly.>\n\nBut it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!", objectives = "" }
WordHunterWoW_QuestEN[79335] = { title = "One More Tradition", description = "Before I shut down, I must craft an item that is meaningful to me. \n\nAs a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after.\n\nI wish to forge a new lantern to guide my way through these final moments.\n\nThe lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills.\n\nGather the materials, and I will forge the lantern.", objectives = "" }
WordHunterWoW_QuestEN[79336] = { title = "The Forging of Memories", description = "Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am.\n\n<Korgran lets out a deep sigh.>\n\nThese hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge.\n\nPlease, add the right material to the forge as I call them out.", objectives = "" }
WordHunterWoW_QuestEN[79337] = { title = "The Last Journey", description = "This lantern is perfect.\n\nEnough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony.\n\n<Korgran forces a smile.>\n\nIt is nothing fancy, I promise. As I said, it is more symbolic than anything else.\n\nMy head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago!", objectives = "" }
WordHunterWoW_QuestEN[79338] = { title = "The Lost Earthen", description = "This is horrible! I knew I should have been keeping a closer eye on him.\n\nConfusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is.\n\nI am such a boulder head!\n\n{name}, please, I think I saw him go east into the trees. Meet me there up the road!", objectives = "" }
WordHunterWoW_QuestEN[79339] = { title = "A Change of Tradition", description = "An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before...\n\nI may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. \n\nAs Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets.\n\n{name}, meet me at the shore to the southeast of here.", objectives = "" }
WordHunterWoW_QuestEN[79340] = { title = "Tools of Declaration", description = "As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. \n\nFiguratively, of course.\n\nTo do that, Korgran will need a horn.\n\nHe would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me.\n\nI saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.", objectives = "" }
WordHunterWoW_QuestEN[79341] = { title = "Cleansing Ashes", description = "The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. \n\nIt is a symbolic process of purification. For it, we need to gather ashenfold, a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities.\n\nWe are then ready to embrace our final moments.\n\n<Urtago looks at Korgran with a hand on her chest. Her face falls.>", objectives = "" }
WordHunterWoW_QuestEN[79342] = { title = "As He Departs", description = "It is time for the ceremony, {name}.\n\nPlease place the bowl of ashenfolds by Korgran and then hand him the horn.\n\nOnce the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend.\n\nKorgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time.\n\nMy core is mud, but it is a great honor to stand here with him... and with you.", objectives = "" }
WordHunterWoW_QuestEN[79343] = { title = "Everyday I'm Snufflin'", description = "Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.", objectives = "" }
WordHunterWoW_QuestEN[79344] = { title = "Urban Odyssey", description = "Did ye hear, {name}?\n\nA lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in.\n\nThe more support we gather, the better.", objectives = "" }
WordHunterWoW_QuestEN[79346] = { title = "Chew On That", description = "Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves.\n\nI've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time!\n\nIf you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.", objectives = "" }
WordHunterWoW_QuestEN[79349] = { title = "Entrepreneur, Inc.", description = "Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding.\n\nYou should meet my business partner, Ripsnoodle. He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you.\n\nYou can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.", objectives = "" }
WordHunterWoW_QuestEN[79350] = { title = "Intro Dummy Quest Week 1 (Text Only)", description = "I am chuffed you are helping us with this venture that is so close to my heart.\n\nAs a lad, I loved dragons--as young children do--and was smitten with Sindragosa. I read all I could about her. When the Dragon Isles opened, I begged the Algeth'ar Academy to let me study the many volumes of Sindragosa's memoirs.\n\nIn them found a brief mention of a battle at Traitor's Rest. The Blue Dragons are staying mum, but clues to an epic story are all about here!\n\nI must know what happened here. For Sindragosa", objectives = "" }
WordHunterWoW_QuestEN[79354] = { title = "The Machine Speakers", description = "Ah, {name}! The {race} of the hour... We were just discussing you.\n\n<Moira nods towards Speaker Brinthe.>\n\nThere is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more.\n\nCare to stick around?", objectives = "" }
WordHunterWoW_QuestEN[79355] = { title = "Prisoner Preservation", description = "The beasts took our people! Dragged them away when we were gettin' our first rest since our escape!\n\nWe only just escaped those nerubians. We can't afford ta lose more people.\n\nSearch Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.", objectives = "" }
WordHunterWoW_QuestEN[79356] = { title = "Antifungal Firestarter", description = "Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. \n\nMaybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts.\n\nTake these antifungal firebombs and torch as many fungal spore pods as you can!", objectives = "" }
WordHunterWoW_QuestEN[79357] = { title = "Removing the Cap", description = "Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave.\n\nWe can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom.\n\nGet to Pillar-nest Vosh and kill that fungarian leader!", objectives = "" }
WordHunterWoW_QuestEN[79367] = { title = "A Nebb in Need", description = "You! You no spider. Please, must help before spiders come again. \n\nNebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light.\n\nCan't leave post. You take candles, yes? Light up barricade. Keep spiders away.", objectives = "" }
WordHunterWoW_QuestEN[79368] = { title = "Hair of the Spider", description = "Light good, but more to do. \n\nSpiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now.\n\nNebb might know a way, yes, turn venom into cure. Use bite to cure bite.\n\nBring venom. Hurry now!", objectives = "" }
WordHunterWoW_QuestEN[79369] = { title = "Protecting the Harvest", description = "Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw.\n\nCan no waste time. Kobolds starve if spiders gobble grubs and eggs.\n\nSave them, gather eggs. As many as can carry before spiders snatch all.", objectives = "" }
WordHunterWoW_QuestEN[79370] = { title = "A Poultice for Poison", description = "Little venom, little wax...\n\n<Nebb reaches into his pouch and gives you a handful of thick, pungent wax.>\n\nYes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw. He feel right better.", objectives = "" }
WordHunterWoW_QuestEN[79371] = { title = "A Royal Cure", description = "Poultice no work! Wax right, venom wrong?\n\nYes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave.\n\nNow you must follow. Collect royal venom. Please, Snubjaw have little time.", objectives = "" }
WordHunterWoW_QuestEN[79372] = { title = "A Clutch of Hope", description = "<The broodmother lies dead, coiled around a single egg. She gave her life to keep it from the spiders.\n\nYou should take it to Nebb. He and the other Grubtenders would know what to do with it.>", objectives = "" }
WordHunterWoW_QuestEN[79387] = { title = "Test Quest - Account Test (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[79432] = { title = "It's About Time", description = "Your timing is serendipitous. I require your assistance.\n\nNot all infinites have seen what Nozdormu has shown me. Not all would agree even if they had. Archaios is one such detractor. He must be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[79433] = { title = "Seeking Expert Advice", description = "Take this spool to Moratari. Perhaps she can make sense of this relic.", objectives = "" }
WordHunterWoW_QuestEN[79434] = { title = "Weave It To Me", description = "The other infinites are not as judicious in their treatment of the timeline. They have rather torn through time in their reckless opposition to our efforts.\n\nThough we cannot simply mend the timeways, we may yet repurpose its loose threads.\n\nReclaim the threads of time from our enemies and we shall weave you a cloak worthy of the Infinite Dragonflight.", objectives = "" }
WordHunterWoW_QuestEN[79435] = { title = "What's Hours Is Yours", description = "Horos, our antiquities collector, should have a chronobadge you can use to fasten together the temporal threads you collected.\n\nWith the chronobadge, Momentus can craft the threads into a powerful cloak for you to wear!", objectives = "" }
WordHunterWoW_QuestEN[79437] = { title = "Knot My Problem", description = "These temporal anomalies are getting out of control. Normally, our research does not unravel the timeline this much--I suspect the other infinites are to blame.\n\nUse this chronostabilizer to zip up the frayed rifts.\n\nBe aware--this may briefly create even more anomalies. I trust you know how to handle them.", objectives = "" }
WordHunterWoW_QuestEN[79438] = { title = "Goodbyes Are Hard When You Live Forever", description = "We have one last anomaly to deal with here before we can study the history of Pandaria.\n\nHelp us stabilize the timeway and secure our mission.", objectives = "" }
WordHunterWoW_QuestEN[79440] = { title = "Recalling the War", description = "Our operations here are secure. For now, anyway!\n\nIt is time for you to begin your journey to the past so that we may observe how history unfolded.\n\nSpeak with Eternus if you have any final questions about our mission. She can show you how these events began.", objectives = "" }
WordHunterWoW_QuestEN[79448] = { title = "Leave No Flightstone Unturned", description = "It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream!\n\nSo I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.", objectives = "" }
WordHunterWoW_QuestEN[79453] = { title = "Awakened Crests, Unlimited Possibilities", description = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here.\n\nOf course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.", objectives = "" }
WordHunterWoW_QuestEN[79475] = { title = "Charging Up That Hill", description = "Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. \n\nThe way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit.\n\nWhile you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.", objectives = "" }
WordHunterWoW_QuestEN[79476] = { title = "Heeding the Call", description = "Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too.\n\nMaybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure...\n\nBah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.", objectives = "" }
WordHunterWoW_QuestEN[79477] = { title = "Strays", description = "Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us.\n\nUnfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home.\n\nWould you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.", objectives = "" }
WordHunterWoW_QuestEN[79480] = { title = "Paying Respects", description = "Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim.\n\nUnfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.", objectives = "" }
WordHunterWoW_QuestEN[79481] = { title = "Tending to the Terrified", description = "All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming.\n\nNebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. \n\nWe tenders, not fighters. Do not let friends become meals.", objectives = "" }
WordHunterWoW_QuestEN[79489] = { title = "Gems of Power", description = "You have found a gem that improves your combat capabilities when socketed into a prismatic socket found in your chest or leg armor.\n\nSocket this Chipped Deadly Sapphire into your equipment to increase your Critical Strike chance.", objectives = "" }
WordHunterWoW_QuestEN[79504] = { title = "Dripsy Forgot Her Candle", description = "Gather round, tenderfoots, and Granny Scribbles tell you story.\n\nStory of what happen when Dripsy forgot her candle.\n\nDripsy little tenderfoot, like you, who wander away from tribe...", objectives = "" }
WordHunterWoW_QuestEN[79505] = { title = "Chomps and the Cave-In", description = "Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day.\n\nAbout what happen when not listen to old, wise kobold. Like me!\n\nStory of Chomps and the cave-in...", objectives = "" }
WordHunterWoW_QuestEN[79507] = { title = "The Day the Stoneheads Came", description = "What? Want scary story?\n\nYou ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots.\n\nScariest story Granny know, yes. Story about the day the stoneheads came...", objectives = "" }
WordHunterWoW_QuestEN[79508] = { title = "Mipsy Mole-Rider", description = "Time for happy story. Not all days bad.\n\n<Granny Scribbles gently scratches Ol' Snorler behind his ears.>\n\nTell story of how be friends with moles. Story of Mipsy mole-rider...", objectives = "" }
WordHunterWoW_QuestEN[79510] = { title = "The Wickless Candle", description = "Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about.\n\n<Granny Scribbles nods sagely as she points you out.>\n\nStory of how kobold discover it long go, and what find when do. Story of the wickless candle...", objectives = "" }
WordHunterWoW_QuestEN[79511] = { title = "Identity Crisis", description = "Hey {name}, over here!\n\nI just finished speaking with Emberthal. I'm not sure what, but something is bothering her! \n\nShe had lots of odd questions about visage forms. Could she be ready to choose one? How exciting! I think I saw her head over to the Victorious Visage.\n\nYou should check on her, I bet you could get her to spill the secret!", objectives = "" }
WordHunterWoW_QuestEN[79512] = { title = "Who Are You?", description = "Perhaps Cindrethresh is right. \n\nStill, if I'm to pick a visage, I should at least give it some thought.\n\nI just do not fully understand the concept of visage forms.\n\nI have heard that visage is supposed to be ones own expression of self.\n\nHow does one discover what that is?\n\nMaybe some of the individuals here in Valdrakken hold the answers.\n\n{name}, I need you to gather intel. I will remain here. Report back your findings when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[79513] = { title = "Dragon Isles Adventuring: Being Yourself", description = "I worry about Emberthal. Her mood has grown increasingly dark.\n\nBy sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique.\n\nPerhaps a broader sample size is in order?\n\nShe needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles.\n\nGo, and speak with them. \n\nWould that I could go myself, but the duties of a Scalecommander never rest.", objectives = "" }
WordHunterWoW_QuestEN[79514] = { title = "Don't Threaten Me With a Good Time", description = "Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form!\n\nChromie told us all about the celebrations dragons used to have for Visage Day.\n\nSo, Kalecgos and I are going to blow stuff up! Fireworks, mostly.\n\nWe'll need some arcane residue to make them, though.\n\nConveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest.\n\nThe three of us have some other preparations to make here in Valdrakken.", objectives = "" }
WordHunterWoW_QuestEN[79515] = { title = "Gather Your Rosebuds", description = "Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form.\n\nNot to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration.\n\nThe fireworks are to match the colors of the dragonflights.\n\nEach enclave of the city grows special flowers in accordance with that enclave's flight.\n\nThree of each color should be enough for the first batch of fireworks.", objectives = "" }
WordHunterWoW_QuestEN[79521] = { title = "Seizing Evidence", description = "Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here.\n\nDornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading.\n\nWe have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.", objectives = "" }
WordHunterWoW_QuestEN[79522] = { title = "Withheld Information", description = "There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled.\n\nThe Councilward will want us to get to the bottom of this, and I refuse to disappoint him.\n\nWe haven't been able to get any additional information out of the workers, but maybe you'll have more luck. \n\nSpeak to the ones we have detained here, and see if you can learn anything.", objectives = "" }
WordHunterWoW_QuestEN[79523] = { title = "Something Hidden", description = "So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing.\n\nExcellent work, {name}! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence.\n\nSmash the bottoms out of the crates and bring anything you find back to me.", objectives = "" }
WordHunterWoW_QuestEN[79525] = { title = "Report to the Councilward", description = "Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts.\n\nBring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise.\n\nI'll package up the rest of the evidence to be brought to him later. Good work today.", objectives = "" }
WordHunterWoW_QuestEN[79526] = { title = "Sedition", description = "<The poster reads:>\n\nMERRIX is CORRUPT! STEELVEIN is WEAK!\n\nThey cannot protect the earthen! They do not care about them! They spit upon the Edicts!\n\nMerrix was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind Merrix's authority!\n\nThey are taking from YOUR pockets to line THEIRS!\n\nDO NOT TRUST THEIR LIES!", objectives = "" }
WordHunterWoW_QuestEN[79527] = { title = "Damage Mitigation", description = "Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers.\n\nIt is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city.\n\nIt is imperative that we remove them before these rumors spread further. Tear them down for me.", objectives = "" }
WordHunterWoW_QuestEN[79528] = { title = "Dispelling Rumors", description = "Many of my peacekeepers have already caught wind of Ardgrin's sedition.\n\nI am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers.\n\nI can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition.\n\nIf you find any discussing the matter, kindly disperse them.", objectives = "" }
WordHunterWoW_QuestEN[79529] = { title = "Forcing My Hand", description = "I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have.\n\nI believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded.\n\nI would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.", objectives = "" }
WordHunterWoW_QuestEN[79530] = { title = "Bad Business", description = "I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot.\n\nOnce there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment.\n\nWe will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.", objectives = "" }
WordHunterWoW_QuestEN[79532] = { title = "Tinker, Tailor, Soldier, Spider", description = "I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry.\n\nMeesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences.\n\nI believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'", objectives = "" }
WordHunterWoW_QuestEN[79537] = { title = "Jrz Test Currency Quest", description = "{name}, the Primalists have managed to summon fierce Elemental Storms all across the Dragon Isles. \n\nWhen a storm is active go to it and slay the imbued creatures there. \n\nThen collect the Elemental Overflow from the slain foes. Be aware that the stronger the foe, the more Elemental Overflow you will collect.\n\nWe must not let the Primalist elemental corruption grow unchecked.", objectives = "" }
WordHunterWoW_QuestEN[79538] = { title = "Smelly Shrubberies", description = "Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity!\n\nWe've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins.\n\nBut I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!", objectives = "" }
WordHunterWoW_QuestEN[79539] = { title = "Electrifying!", description = "You wanna help the Venture Company? And you don't mind being disposable?\n\nOkay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business.\n\nFortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat.\n\nTake the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.", objectives = "" }
WordHunterWoW_QuestEN[79540] = { title = "The Party's Over", description = "Nope, nope, nope!\n\nLook, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. \n\nThis is OUR place, why are they buggin' us?", objectives = "" }
WordHunterWoW_QuestEN[79541] = { title = "Burn It With Fire", description = "So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad?\n\nHonestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects.\n\nHead in, clear out the nests, and put the right incense back in there!", objectives = "" }
WordHunterWoW_QuestEN[79542] = { title = "The Councilward's Summons", description = "Councilward Merrix requests your presence in his office.\n\nHe received the documents you left and would like to discuss the Steelvein situation with you further.\n\n<Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>", objectives = "" }
WordHunterWoW_QuestEN[79543] = { title = "Dornogal's Benefactor", description = "You are in a unique position, {name}. A position to learn.\n\nYou met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? \n\nHumor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\"\n\nYou might be surprised to learn who benefits from these... illicit deeds.", objectives = "" }
WordHunterWoW_QuestEN[79544] = { title = "Security Through Trade", description = "If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends.\n\nOne of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it.\n\nEven as Councilward, I am not able to access it. However, there are others in the city who can.\n\nBevrusi, a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.", objectives = "" }
WordHunterWoW_QuestEN[79545] = { title = "The Market Reeve of the Forgegrounds", description = "I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare.\n\nLuckily for you, there is one person who can find the stuff. Vokgret, the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge.\n\nI don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure!\n\nAt this hour, you'll find her over by the inn.", objectives = "" }
WordHunterWoW_QuestEN[79546] = { title = "The Machine Speakeasy", description = "Machine Speakers are odd and secretive units, some prone to paranoia. \n\nEven so, the grievance they have against Steelvein must be smoothed over.\n\nAs you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it.\n\nLet us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps.\n\nI will meet you in the tunnels.", objectives = "" }
WordHunterWoW_QuestEN[79552] = { title = "Hot Wax", description = "Oh. Fire bees bit bigger than Janky expect. Look mean.\n\nOther hives meaner, though. This best spot.\n\nYou go grab wax. Janky stay here to...supervise. Yes!", objectives = "" }
WordHunterWoW_QuestEN[79553] = { title = "A Natural Remedy", description = "We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies.\n\nFungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to.\n\n<Adelgonn looks grimly proud.>\n\nOne we will adapt to. As the Unbound always do.\n\nBut I can't leave Ebona's side. Will you help me?", objectives = "" }
WordHunterWoW_QuestEN[79554] = { title = "Holy Hydrocarbons", description = "These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.", objectives = "" }
WordHunterWoW_QuestEN[79555] = { title = "Deep Wax Galactic", description = "While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle.\n\nJanky the candlesmith in Gundargaz might be interested in this.", objectives = "" }
WordHunterWoW_QuestEN[79556] = { title = "On the Job Training", description = "Stoneheads use steam to run whole place. Have lava, have water, make sense.\n\nRepairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot.\n\nHelp get old machines work. We watch, learn. Maybe not get yelled at for helping.", objectives = "" }
WordHunterWoW_QuestEN[79558] = { title = "Feathered Fiend", description = "The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.", objectives = "" }
WordHunterWoW_QuestEN[79559] = { title = "The Verdigrease Knight", description = "Think you brave?\n\nBeen looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee.\n\nHow about way to prove it? You hit me as hard as can. Try kill me.\n\nIf I not dead, then I get kill you, later.\n\nNot look like it take more than one chop for you.\n\nDeal?", objectives = "" }
WordHunterWoW_QuestEN[79561] = { title = "Lord of the Giants", description = "Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must.\n\nGreasebaddaden, king of giant slimes, lair nearby. Perfect chance to prove valor to court!\n\nHas giant fork jammed in head, can't miss. You know what do.", objectives = "" }
WordHunterWoW_QuestEN[79563] = { title = "Lady of the Lake", description = "Shown great bravery. Humbility. Honor.\n\nWould make good Knight of Brown Table.\n\nOnly task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not.\n\nLake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.", objectives = "" }
WordHunterWoW_QuestEN[79564] = { title = "The Verdigrease Knight Returns", description = "Am back, as promise.\n\nHear you now brave knight.\n\nReady fulfill your end of oath? My turn strike YOU down.\n\nKneel.", objectives = "" }
WordHunterWoW_QuestEN[79565] = { title = "Janky Candles", description = "With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee.\n\nOnly problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need.\n\nMay need barter, but you talk good! Make him give parts.\n\nMeet you down there!", objectives = "" }
WordHunterWoW_QuestEN[79574] = { title = "The Second Front", description = "Our reinforcements are already inbound. \n\nThese spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike.", objectives = "" }
WordHunterWoW_QuestEN[79575] = { title = "What the Duck?", description = "I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg!\n\nThese chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?", objectives = "" }
WordHunterWoW_QuestEN[79576] = { title = "A Fowl Concoction", description = "My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen!\n\nEnough is enough. We simply must put an end to this duck invasion.\n\nPlease, {name}. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.", objectives = "" }
WordHunterWoW_QuestEN[79577] = { title = "Duck Tales", description = "Take this potion, {name}. Drink it, and you should be able to chit chat with those feathery fiends.\n\nOh, but if you happen to experience any... unintended side effects, don't blame me.", objectives = "" }
WordHunterWoW_QuestEN[79578] = { title = "Just a Waddle Away", description = "We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. \n\nI convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!", objectives = "" }
WordHunterWoW_QuestEN[79579] = { title = "That Airspace is Mine(d)!", description = "Our advantage is air superiority. The nerubians are threatening that with their mines. \n\nYour mount is more maneuverable than our skiffs. Get in the air and take those mines out.\n\nI will deploy what resources I can to provide you some blessings to improve your capabilities.", objectives = "" }
WordHunterWoW_QuestEN[79580] = { title = "Offensive Counter", description = "I will not yield this ground. \n\nGet out there and kill anything with more than two legs!", objectives = "" }
WordHunterWoW_QuestEN[79622] = { title = "Warband Test Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[79625] = { title = "Not Quite Dead", description = "I am General Anub'azal.\n\nI loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! \n\nI have decided to use you and your kind against Zev'kall. And yes, you will get something out of it.\n\nSearch that rubbish pile there. You will see.", objectives = "" }
WordHunterWoW_QuestEN[79627] = { title = "Wine and Die", description = "I can see it now, morsel. The pattern of our newest weave is laid bare before my mind.\n\nMeesk is well-guarded. He believes himself to be safe. That is where his weakness lies.\n\nGo to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward.\n\nI trust you, {name}. And if you lay our threads out properly, I can guarantee you quite the show.", objectives = "" }
WordHunterWoW_QuestEN[79630] = { title = "Searching the Web", description = "Oh, thank the hollows! You look like someone that can help.\n\n<The nerubian dabs at her many eyes with a silken handkerchief.>\n\nIt's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony...\n\nBut when we were to retire for the evening, he disappeared.\n\n<She sniffles dramatically.>\n\nPlease, could you find him and bring him home to me?", objectives = "" }
WordHunterWoW_QuestEN[79631] = { title = "Klaskin's Great Escape", description = "Silken threads, I'm saved!\n\nIt's incredibly important that I make it back home without my wife seeing me.\n\nI took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne.\n\nWill you help me avoid the guards and get back home?", objectives = "" }
WordHunterWoW_QuestEN[79633] = { title = "The Weaver's Legacy", description = "Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this.\n\nAh, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.", objectives = "" }
